const u8 String_0004[] = _("カ―トリッジ上部にある太陽セ\nンサ―は、太陽の光の強さを感\n知する。");
const u8 String_0005[] = _("蛍光灯(けいこうとう)や電球の\n光では反応しないので、注意が\n必要だ。");
const u8 String_0006[] = _("「ゾクタイ」では、太陽センサ\n―が感知した太陽の光が、");
const u8 String_0007[] = _("ゲ―ムの世界にさまざまな影響\n(えいきょう)をあたえる。\n太陽の光が攻略のカギだ!!");
const u8 String_0008[] = _("太陽センサ―は精密機械だ。");
const u8 String_0009[] = _("カ―トリッジを落としたり、\n汚(よご)したりしないよう、\n大切にあつかってほしい。");
const u8 String_000A[] = _("エナジ―を回復するには太陽の\n光が必要だが、一度に集めすぎ\nるとオ―バ―ヒ―トしてしまう");
const u8 String_000B[] = _("こまめな休憩(きゅうけい)を\nこころがけよう。");
const u8 String_000C[] = _("カ―トリッジの向きや傾(かた\nむ)きによって、");
const u8 String_000D[] = _("太陽センサ―が感知する太陽の\n光の強さも変化する。\nいろいろ試してみよう。");
const u8 String_000E[] = _("日の当たる場所なら太陽の光は\n強いが、日陰(ひかげ)にも太陽\nの力は届いている。");
const u8 String_000F[] = _("自分だけの「ゾクタイプレイス\n」を見つけよう!!");
const u8 String_0010[] = _("夕方になると太陽の光は弱くな\nる。");
const u8 String_0011[] = _("明るいからといって油断は禁物\n太陽ゲ―ジをチェックしよう!!");
const u8 String_0012[] = _("夜にはもちろん太陽の光がない");
const u8 String_0013[] = _("太陽の力に頼(たよ)ることがで\nきないが、そんなときにこそ本\n当の実力が試される!!");
const u8 String_0014[] = _("その日の天気によって、太陽の\n光の強さは大きく変化する。");
const u8 String_0015[] = _("晴れた日は「ゾクタイ日和(び\nより)」だ!!");
const u8 String_0016[] = _("くもりの日だからといって、\n太陽の光がないわけではない。");
const u8 String_0017[] = _("たとえ太陽が見えなくても、\nあきらめずにチャレンジだ!!");
const u8 String_0018[] = _("天気を知るものはゾクタイを制\nす!!");
const u8 String_0019[] = _("天気予報をチェックして自分だ\nけの「ゾクタイスケジュ―ル」\nを立ててみよう。");
const u8 String_001A[] = _("炎天下でプレイすると、\nオ―バ―ヒ―トになりやすい。");
const u8 String_001B[] = _("木陰(こかげ)などの日陰(ひか\nげ)を探そう。帽子(ぼうし)を\nかぶるのも忘れずに!!");
