const u8 String_00ED[] = _("・・・仕方ありません。\nおしおきをさせていただきます");
const u8 String_00EE[] = _("さあ、行きますよ?」");
const u8 String_00EF[] = _("<PROC=0>\n<END>");
const u8 String_00F0[] = _("暗黒ロ―ンの暗子ちゃん\n「・・・<NAME>さん、\nあなたわざとやっていますね?");
const u8 String_00F1[] = _("えっ?\nわたしにおしおきをされたい?");
const u8 String_00F2[] = _("<NAME>さんって・・・");
const u8 String_00F3[] = _("そういう趣味(しゅみ)の人だっ\nたんですか!?」");
const u8 String_00F4[] = _("<PROC=0>\n<END>");
const u8 String_00F5[] = _("暗黒ロ―ンの暗子ちゃん\n「・・・<NAME>さん、");
const u8 String_00F6[] = _("わたし・・・\n覚悟(かくご)を決めました。");
const u8 String_00F7[] = _("たとえあなたが、いけない趣味\n(しゅみ)の人だったとしても、");
const u8 String_00F8[] = _("このわたしが好きなだけ、\nおしおきをしてあげます!");
const u8 String_00F9[] = _("これがわたしたちの・・・\n・・・愛の形なんですね♥");
const u8 String_00FA[] = _("あれ、<NAME>さん?\n待ってください!\n<NAME>さ―――ん!!」");
const u8 String_00FB[] = _("<PROC=0>\n<END>");
const u8 String_00FC[] = _("暗黒ロ―ンの暗子ちゃん\n「さあ、<NAME>さん。\nおしおきですよ♥」");
const u8 String_00FD[] = _("<PROC=0>\n<END>");
const u8 String_00FE[] = _("暗黒ロ―ンの暗子ちゃん\n「あなたには今からここで、\n発電をしてもらいます。");
const u8 String_00FF[] = _("方法は簡単。\n<EXTEND=0>とＡボタンを交互(\nこうご)に押(お)して走るだけ");
const u8 String_0100[] = _("エネルギ―が発電されれば、\nそれが返済にあてられるという\nわけです。");
const u8 String_0101[] = _("簡単ですね♪");
const u8 String_0102[] = _("それでは<NAME>さん、\nよろしくお願いします」");
const u8 String_0103[] = _("<PROC=0>\n<END>");
const u8 String_0104[] = _("✚ボタン左");
const u8 String_0105[] = _("<PROC=0>\n<END>");
const u8 String_0106[] = _("✚ボタン上");
const u8 String_0107[] = _("<PROC=0>\n<END>");
const u8 String_0108[] = _("✚ボタン右");
const u8 String_0109[] = _("<PROC=0>\n<END>");
const u8 String_010A[] = _("✚ボタン下");
const u8 String_010B[] = _("<PROC=0>\n<END>");
const u8 String_010C[] = _("暗黒ロ―ンの暗子ちゃん\n「はい、けっこうです!");
const u8 String_010D[] = _("ご返済ありがとうございます。\nこれであなたも自由の身です。");
const u8 String_010E[] = _("もうこんなところに来てはいけ\nませんよ、<NAME>さん。");
const u8 String_010F[] = _("それでは今後とも暗黒ロ―ンを\nよろしくお願いします。");
const u8 String_0110[] = _("<PROC=1>ありがとうございました!!」<PROC=2>");
const u8 String_0111[] = _("<PROC=0>\n<END>");
const u8 String_0112[] = _("暗黒ロ―ンの暗子ちゃん\n「はい、もうけっこうです。");
const u8 String_0113[] = _("今のあなたに、これ以上は無理\nのようですね・・・");
const u8 String_0114[] = _("今日のところは、これでかんべ\nんしてあげます。");
const u8 String_0115[] = _("これからは身のほどをわきまえ\nてくださいよ?\nいいですね、<NAME>さん?");
const u8 String_0116[] = _("それでは今後とも暗黒ロ―ンを\nよろしくお願いします」");
const u8 String_0117[] = _("<PROC=0>\n<END>");
const u8 String_0118[] = _("暗黒ロ―ンの暗子ちゃん\n「はい、お疲れさまでした!\nご返済ありがとうございます。");
const u8 String_0119[] = _("なかなかの走りでしたが、");
const u8 String_011A[] = _("もうこんなところに来てはいけ\nませんよ、<NAME>さん。");
const u8 String_011B[] = _("<PROC=0>\n<END>");
const u8 String_011C[] = _("「チョコレ―ト」\nを手に入れた!!");
const u8 String_011D[] = _("<PROC=0>\n<END>");
const u8 String_011E[] = _("それでは今後とも暗黒ロ―ンを\nよろしくお願いします。\n<PROC=1>ありがとうございました!!」<PROC=2>");
const u8 String_011F[] = _("<PROC=0>\n<END>");
const u8 String_0120[] = _("暗黒ロ―ンの暗子ちゃん\n「はい、お疲れさまでした!\nご返済ありがとうございます。");
const u8 String_0121[] = _("なかなかいい走りでしたが、");
const u8 String_0122[] = _("もう無理をしてはいけませんよ\n<NAME>さん。");
const u8 String_0123[] = _("<PROC=0>\n<END>");
const u8 String_0124[] = _("「太陽の実」\nを手に入れた!!");
const u8 String_0125[] = _("<PROC=0>\n<END>");
const u8 String_0126[] = _("それでは今後とも暗黒ロ―ンを\nよろしくお願いします。\n<PROC=1>ありがとうございました!!」<PROC=2>");
const u8 String_0127[] = _("<PROC=0>\n<END>");
const u8 String_0128[] = _("暗黒ロ―ンの暗子ちゃん\n「はい、お疲れさまでした!\nご返済ありがとうございます。");
const u8 String_0129[] = _("すばらしい走りです!!");
const u8 String_012A[] = _("でも、返済期限は守ってくださ\nいね、<NAME>さん。");
const u8 String_012B[] = _("<PROC=0>\n<END>");
const u8 String_012C[] = _("「魔法薬」\nを手に入れた!!");
const u8 String_012D[] = _("<PROC=0>\n<END>");
const u8 String_012E[] = _("それでは今後とも暗黒ロ―ンを\nよろしくお願いします。\n<PROC=1>ありがとうございました!!」<PROC=2>");
const u8 String_012F[] = _("<PROC=0>\n<END>");
const u8 String_0130[] = _("太陽樹の朝露により・・・");
const u8 String_0131[] = _("<PROC=0>\n<END>");
const u8 String_0132[] = _("ライフとエナジ―が回復した!!");
const u8 String_0133[] = _("<PROC=0>\n<END>");
const u8 String_0134[] = _("カ―モスの呪いが解かれた!!");
const u8 String_0135[] = _("<PROC=0>\n<END>");
const u8 String_0136[] = _("「ズ―ボルテルテ」が浄化され\n「テルテルボ―ズ」となった!!");
const u8 String_0137[] = _("<PROC=0>\n<END>");
const u8 String_0138[] = _("　　<ALTER>クロスオ―バ―バトル</ALTER>\n　　<ALTER>　　ゲ―ムの説明　　</ALTER>");
const u8 String_0139[] = _("<PROC=0>\n<END>");
const u8 String_013A[] = _(" <ALTER>対戦の内容</ALTER>　　<ALTER>対戦の流れ</ALTER>\n <ALTER>オジャマ1</ALTER> 　　<ALTER>オジャマ2</ALTER>\n <ALTER>ブロッキング</ALTER>　<ALTER>ポイント</ALTER>");
const u8 String_013B[] = _("<PROC=0>\n<END>");
const u8 String_013C[] = _("クロスオ―バ―バトルでは、");
const u8 String_013D[] = _("ワイヤレスアダプタを使って、\nロックマン エグゼ5との対戦を\nすることができる。");
const u8 String_013E[] = _("ゾクタイとエグゼ5、それぞれ\nのゲ―ムでシェ―ドマンと戦い");
const u8 String_013F[] = _("シェ―ドマンを先に倒(たお)す\nか、");
const u8 String_0140[] = _("相手のゲ―ムにオジャマバット\nを送り込んで、ライバルを先に\n倒した方が勝ちとなる。");
const u8 String_0141[] = _("<PROC=0>\n<END>");
const u8 String_0142[] = _("クロスオ―バ―バトルはラウン\nド制で行われる。");
const u8 String_0143[] = _("対戦の開始前とラウンド間のイ\nンタ―バル画面では、");
const u8 String_0144[] = _("画面の左右に表示されたリスト\nの中から、");
const u8 String_0145[] = _("使いたい魔法と武器を、Ｌ・Ｒ\nボタンで選択(せんたく)するこ\nとができ、");
const u8 String_0146[] = _("選択された武器と魔法は、次の\n1ラウンドの間のみ使うことが\nできる。");
const u8 String_0147[] = _("リストは8種類の魔法と、素手\nをふくむ13種類の武器の中から");
const u8 String_0148[] = _("毎回ランダムに4つずつが選ば\nれる。");
const u8 String_0149[] = _("それぞれの魔法と武器は、対戦\n中に1度ずつしか使うことがで\nきないが、");
const u8 String_014A[] = _("素手だけは何度でも使うことが\nできる。");
const u8 String_014B[] = _("<PROC=0>\n<END>");
const u8 String_014C[] = _("シェ―ドマンに特定の攻撃を当\nてると、ライバルにオジャマバ\nットを送ることができる。");
const u8 String_014D[] = _("背後からの攻撃を当てると、\n赤オジャマ(ビッグノイズ発動)");
const u8 String_014E[] = _("ソ―ドでエンチャント攻撃を当\nてると、青オジャマ(メット―\nル出現)、");
const u8 String_014F[] = _("スピアでエンチャント攻撃を当\nてると、黄オジャマ(ララチュ\n―バ出現)、");
const u8 String_0150[] = _("ハンマ―でエンチャント攻撃を\n当てると、緑オジャマ(シェ―\nドマンのHP回復)が送られる。");
const u8 String_0151[] = _("<PROC=0>\n<END>");
const u8 String_0152[] = _("ライバルがシェ―ドマンに特定\nの攻撃を当てると、オジャマバ\nットを送られてしまう。");
const u8 String_0153[] = _("チップ攻撃をカウンタ―で当て\nると、赤オジャマ(ウイングス\nト―ム発動)、");
const u8 String_0154[] = _("バットキャノン1を当てると、\n黄オジャマ(ステ―タス異常発\n生)、");
const u8 String_0155[] = _("バットキャノン2を当てると、\n青オジャマ(シェ―ドクロウ召\n喚)、");
const u8 String_0156[] = _("バットキャノン3を当てると、\n緑オジャマ(シェ―ドマンのラ\nイフ回復)、");
const u8 String_0157[] = _("バットキャノン4を当てると、\n黄・青・緑のオジャマバットが\n送られてくる。");
const u8 String_0158[] = _("<PROC=0>\n<END>");
const u8 String_0159[] = _("ブロッキングを使えば、");
const u8 String_015A[] = _("対戦中に1度だけ、ライバルか\nら送られて来たオジャマバット\nを送り返すことができる。");
const u8 String_015B[] = _("ブロッキングは、インタ―バル\n画面でSELECTボタンを押せば、");
const u8 String_015C[] = _("オン・オフの切り換(か)えがで\nきる。");
const u8 String_015D[] = _("<PROC=0>\n<END>");
const u8 String_015E[] = _("対戦の成績に応じて得られるク\nロスオ―バ―ポイントは、");
const u8 String_015F[] = _("ゲ―ム本編のどこかで、防具と\n交換(こうかん)することができ\nる。");
const u8 String_0160[] = _("<PROC=0>\n<END>");
const u8 String_0161[] = _("<LABEL>「PET」\nを手に入れた!!</LABEL>");
const u8 String_0162[] = _("<PROC=0>\n<END>");
const u8 String_0163[] = _("セ―ブしますか?\n <ALTER>はい</ALTER>　<ALTER>いいえ</ALTER>");
const u8 String_0164[] = _("<PROC=0>\n<END>");
const u8 String_0165[] = _("<LABEL=OTENKO>おてんこさま</LABEL>\n「もうすぐだな・・・");
const u8 String_0166[] = _("この渓谷(けいこく)を抜(ぬ)け\nれば、いよいよ太陽の街サン・\nミゲルか。");
const u8 String_0167[] = _("闇(やみ)の一族イモ―タルの呪\n(のろ)い、吸血変異によって、");
const u8 String_0168[] = _("死の街と化したおまえの故郷(\nこきょう)。");
const u8 String_0169[] = _("クイ―ンを倒(たお)し、吸血変\n異は収まったはずだが・・・");
const u8 String_016A[] = _("私の太陽感は告げている。");
const u8 String_016B[] = _("いまださまようアンデッド、\n生と死を奪(うば)われた暗黒の\n下僕(げぼく)たち。");
const u8 String_016C[] = _("そしてそれを操るイモ―タルの\n影(かげ)・・・");
const u8 String_016D[] = _("<PROC=0>\n<END>");
const u8 String_016E[] = _("<LABEL=OTENKO></LABEL>行くぞ、\n太陽少年<NAME>!!");
const u8 String_016F[] = _("太陽の街をおおう暗雲を振(ふ\n)り払(はら)うんだ!");
const u8 String_0170[] = _("<PROC=1><LOCK=85>太陽と共にあらんことを!」");
const u8 String_0171[] = _("<PROC=0>\n<END>");
const u8 String_0172[] = _("<LABEL=OTENKO>おてんこさま</LABEL>\n「まて、<NAME>!!");
const u8 String_0173[] = _("サン・ミゲルは北だ。\n画面右上の方向に進むんだ」");
const u8 String_0174[] = _("<PROC=0>\n<END>");
const u8 String_0175[] = _("<LABEL=OTENKO>おてんこさま</LABEL>\n「ん?");
const u8 String_0176[] = _("そこにあるのはヒントパネルか\n・・・");
const u8 String_0177[] = _("<PROC=0>\n<END>");
const u8 String_0178[] = _("<LABEL=OTENKO></LABEL>ヒントパネルは、先人が残した\n冒険者(ぼうけんしゃ)への道し\nるべだ。");
const u8 String_0179[] = _("冒険に必要な基本的な知識や、\n困難を乗り越(こ)えるためのヒ\nントを教えてくれる。");
const u8 String_017A[] = _("パネルを読むには、近づいてＡ\nボタン(アクションボタン)を押\n(お)せばいい。");
const u8 String_017B[] = _("チェックしておいて損はないぞ\n」");
const u8 String_017C[] = _("<PROC=0>\n<END>");
const u8 String_017D[] = _("<LABEL=OTENKO>おてんこさま</LABEL>\n「ここが太陽の街サン・ミゲル");
const u8 String_017E[] = _("しかし今では死の街そのものだ\nな・・・");
const u8 String_017F[] = _("・・・ん!?\nこれは・・・");
const u8 String_0180[] = _("闇(やみ)の気配・・・\nその中にかすかにだが命の気配\nを感じる!");
const u8 String_0181[] = _("吸血変異を逃(のが)れ、生きの\nびた者がいるというのか?」");
const u8 String_0182[] = _("<PROC=0>\n<END>");
const u8 String_0183[] = _("<LABEL=RINGO1>帽子(ぼうし)の男</LABEL>\n「・・・」");
const u8 String_0184[] = _("<PROC=0>\n<END>");
const u8 String_0185[] = _("<LABEL=OTENKO>おてんこさま</LABEL>\n「気をつけろ!!\nこの男は・・・");
const u8 String_0186[] = _("間違(まちが)いない・・・\nイモ―タルの眷族(けんぞく)、\nヴァンパイアだ!」");
const u8 String_0187[] = _("<PROC=0>\n<END>");
const u8 String_0188[] = _("<LABEL=RINGO1>ヴァンパイア</LABEL>\n「・・・う!?");
const u8 String_0189[] = _("う・・・う!!」");
const u8 String_018A[] = _("<PROC=0>\n<END>");
const u8 String_018B[] = _("<LABEL=RINGO1>ヴァンパイア</LABEL>\n「たい・・・よう・・・");
const u8 String_018C[] = _("たいよう・・・じゅう・・・");
const u8 String_018D[] = _("太陽銃(たいようじゅう)・・・");
const u8 String_018E[] = _("ガン・デル・ソル!!」");
const u8 String_018F[] = _("<PROC=0>\n<END>");
const u8 String_0190[] = _("<LABEL=OTENKO>おてんこさま</LABEL>\n「太陽銃を奪(うば)われた!?\n・・・しかし、");
const u8 String_0191[] = _("ムダだ!!\n太陽銃は太陽仔(たいようし)に\nしかあつかえない!");
const u8 String_0192[] = _("ましてやヴァンパイアになど\n・・・!!」");
const u8 String_0193[] = _("<PROC=0>\n<END>");
const u8 String_0194[] = _("<LABEL=OTENKO>おてんこさま</LABEL>\n「<NAME>!!");
const u8 String_0195[] = _("<PROC=0>\n<END>");
const u8 String_0196[] = _("バカな、\nなぜヴァンパイアが!?」");
const u8 String_0197[] = _("<LABEL=RINGO1>ヴァンパイア</LABEL>\n「<NAME>・・・?");
const u8 String_0198[] = _("う・・・う!?」");
const u8 String_0199[] = _("<PROC=0>\n<END>");
const u8 String_019A[] = _("<LABEL=OTENKO>おてんこさま</LABEL>\n「助かった・・・のか?");
const u8 String_019B[] = _("だが、ヤツはいったい・・・");
const u8 String_019C[] = _("太陽銃をあつかえるヴァンパイ\nア、");
const u8 String_019D[] = _("ヤツがサン・ミゲルをおおう暗\n雲なのか・・・?」");
const u8 String_019E[] = _("<PROC=0>\n<END>");
const u8 String_019F[] = _("<LABEL=OTENKO>おてんこさま</LABEL>\n「<NAME>、");
const u8 String_01A0[] = _("過ぎてしまったことは仕方がな\nい・・・\n過去を変えることはできない。");
const u8 String_01A1[] = _("だが、これで未来が決まってし\nまったわけではない!");
const u8 String_01A2[] = _("今、この時をいかに生きるのか\nそれこそが未来を決定するのだ");
const u8 String_01A3[] = _("<PROC=1><LOCK=71>明日もまた日は昇(のぼ)る!");
const u8 String_01A4[] = _("<PROC=2>その深紅のマフラ―に染み込(\nこ)んだ、血と魂(たましい)を\n思い出せ!");
const u8 String_01A5[] = _("おまえの親父はこんなことでは\n決してくじけなかったぞ!!」");
const u8 String_01A6[] = _("<PROC=0>\n<END>");
const u8 String_01A7[] = _("<LABEL=OTENKO>おてんこさま</LABEL>\n「行こう、<NAME>。");
const u8 String_01A8[] = _("サン・ミゲルに行けば何らかの\n手がかりが得られるはず。");
const u8 String_01A9[] = _("あのヴァンパイアを追い、\n太陽銃を取り戻(もど)すんだ!");
const u8 String_01AA[] = _("<PROC=1><LOCK=85>太陽と共にあらんことを!」");
const u8 String_01AB[] = _("<PROC=0>\n<END>");
const u8 String_01AC[] = _("<LABEL=NONE>黒い影</LABEL>\n「やはり現われたね。\n太陽少年<NAME>・・・」");
const u8 String_01AD[] = _("<LABEL=NONE>赤毛の少女</LABEL>\n「しかしあのような少年に、");
const u8 String_01AE[] = _("伯爵(はくしゃく)はともかく、\nクイ―ンまでもが敗れるとは」");
const u8 String_01AF[] = _("<LABEL=NONE>黒い影</LABEL>\n「あなどってはいけない。");
const u8 String_01B0[] = _("彼(かれ)には太陽と月、2つの\n血が流れているんだ。");
const u8 String_01B1[] = _("それにクイ―ン、いやヘルは、\n自らのいるべきところに帰った\nだけだよ・・・");
const u8 String_01B2[] = _("さあ、邪魔(じゃま)の入らない\nうちに事を進めなければ。");
const u8 String_01B3[] = _("眠(ねむ)り姫(ひめ)が目覚めの\nキスを待っている。彼らの足止\nめは任せたよ」");
const u8 String_01B4[] = _("<LABEL=NONE>赤毛の少女</LABEL>\n「・・・はい。");
const u8 String_01B5[] = _("器のほうはいかがなさいますか\n?」");
const u8 String_01B6[] = _("<LABEL=NONE>黒い影</LABEL>\n「今はまだ好きにさせておくさ");
const u8 String_01B7[] = _("その魂(たましい)が、\nすべて闇(やみ)に沈(しず)むま\nではね・・・」");
const u8 String_01B8[] = _("<PROC=0>\n<END>");
const u8 String_01B9[] = _("<PROC=0>\n<END>");
const u8 String_01BA[] = _("<LABEL=OTENKO>おてんこさま</LABEL>\n「さすがだな、<NAME>!");
const u8 String_01BB[] = _("敵モンスタ―を倒(たお)すこと\nによって得られる経験値が、一\n定の値を超(こ)えると、");
const u8 String_01BC[] = _("レベルをアップすることができ\nる。");
const u8 String_01BD[] = _("レベルアップ時に得られるステ\n―タスポイントを割り振(ふ)れ\nば、");
const u8 String_01BE[] = _("おまえの能力を強化することが\nできるぞ。");
const u8 String_01BF[] = _("強化できる能力は、ライフゲ―\nジの最大値に影響(えいきょう)\nする生命力(カラダ)、");
const u8 String_01C0[] = _("エナジ―ゲ―ジの最大値に影響\nする精神力(ココロ)、");
const u8 String_01C1[] = _("攻撃力(こうげきりょく)に影響\nする力強さ(チカラ)、");
const u8 String_01C2[] = _("移動速度や防御力(ぼうぎょり\nょく)に影響するきびんさ(ハヤ\nサ)、以上の4つだ。");
const u8 String_01C3[] = _("ポイントの割り振りは、メニュ\n―画面のステ―タスメニュ―に\nて行うことができる。");
const u8 String_01C4[] = _("レベルアップしても、ポイント\nを割り振らなければ能力は強化\nされない。");
const u8 String_01C5[] = _("忘れずにポイントの割り振りを\n行っておくんだ」");
const u8 String_01C6[] = _("<PROC=0>\n<END>");
const u8 String_01C7[] = _("<LABEL=OTENKO>おてんこさま</LABEL>\n「<NAME>、");
const u8 String_01C8[] = _("武器もなくスケルトンを倒(た\nお)すことはできん!");
const u8 String_01C9[] = _("ひとまず東側通路に回避(かい\nひ)するんだ!」");
const u8 String_01CA[] = _("<PROC=0>\n<END>");
const u8 String_01CB[] = _("<LABEL=OTENKO>おてんこさま</LABEL>\n「グラディウスか・・・\nソ―ド(けん)タイプの武器だな");
const u8 String_01CC[] = _("太陽銃(たいようじゅう)とは比\nべるべくもないが、\n素手で戦うよりはマシだろう。");
const u8 String_01CD[] = _("太陽の力を借りなければ、アン\nデッドを浄化(じょうか)するこ\nとはできない。");
const u8 String_01CE[] = _("しかしスケルトンはシング(物\n体)タイプのモンスタ―・・・");
const u8 String_01CF[] = _("その身体を破壊(はかい)すれば\n一時をしのぐことはできる。");
const u8 String_01D0[] = _("頼(たの)んだぞ、\n<NAME>!」");
const u8 String_01D1[] = _("<PROC=0>\n<END>");
const u8 String_01D2[] = _("<LABEL=OTENKO>おてんこさま</LABEL>\n「太陽機ソル・デ・バイスに月\n光魔法か・・・");
const u8 String_01D3[] = _("ともかくこれで、アンデッドを\n浄化(じょうか)することができ\nる。");
const u8 String_01D4[] = _("イモ―タルと渡(わた)り合うに\nはまだまだ戦力不足だが、ぜい\nたくは言っていられない。");
const u8 String_01D5[] = _("それにしてもあの少女、\nあの言葉使い・・・");
const u8 String_01D6[] = _("商店街で待っていると言ってい\nたな。");
const u8 String_01D7[] = _("商店街は街の中心、太陽街にあ\nるはずだ。");
const u8 String_01D8[] = _("<NAME>、\nこのまま北に向かうんだ」");
const u8 String_01D9[] = _("<PROC=0>\n<END>");
const u8 String_01DA[] = _("<LABEL=ZAJI>魔法少女</LABEL>\n「あかん、あかんて。");
const u8 String_01DB[] = _("そのゾンビはアンデッドタイプ\nのモンスタ―や。\n太陽の力なしに倒(たお)せへん");
const u8 String_01DC[] = _("まったく太陽少年が太陽銃(た\nいようじゅう)取られるやなん\nて、何考えてんねん?");
const u8 String_01DD[] = _("<PROC=0>\n<END>");
const u8 String_01DE[] = _("<LABEL=ZAJI></LABEL>あ?");
const u8 String_01DF[] = _("泣くん?\n泣くんか?\n泣けばええと思っとるんか?");
const u8 String_01E0[] = _("たとえ雨が降っても、");
const u8 String_01E1[] = _("<PROC=1><LOCK=72>ひまわりはうつむかへん!");
const u8 String_01E2[] = _("これ貸したるから元気出しや」");
const u8 String_01E3[] = _("<PROC=0>\n<END>");
const u8 String_01E4[] = _("太陽機「ソル・デ・バイス」\nを手に入れた!!");
const u8 String_01E5[] = _("<PROC=0>\n<END>");
const u8 String_01E6[] = _("<LABEL=ZAJI>魔法少女</LABEL>\n「その手甲(てっこう)は太陽機\nソル・デ・バイス。");
const u8 String_01E7[] = _("太陽の力を利用して、あらゆる\n武器に属性を付加(エンチャン\nト)させることのできる、");
const u8 String_01E8[] = _("ものご―――――――――――\n――――――――――――――\n―――――っつい魔法機械や。");
const u8 String_01E9[] = _("ただしエンチャントには、それ\nぞれの属性の月光魔法が必要や\nねん。");
const u8 String_01EA[] = _("何?\n何で太陽機に月光魔法がいるん\nかって?」");
const u8 String_01EB[] = _("<PROC=0>\n<END>");
const u8 String_01EC[] = _("<LABEL=ZAJI>魔法少女</LABEL>\n「ちゃうねん!!\nほんまは知ってんねんで?");
const u8 String_01ED[] = _("いちいち細かいこと気にしなや\n道具は使えりゃええねん。");
const u8 String_01EE[] = _("何?\n魔法使われへんの?\nほんま困ったやっちゃなぁ。");
const u8 String_01EF[] = _("あんた太陽少年やろ?\nエンチャント・ソルくらいとっ\nくに使えるんやで?");
const u8 String_01F0[] = _("しゃあない、乙女(おとめ)の出\n血大サ―ビスや。ヴァンパイ\nアも大喜びや。行くで?」");
const u8 String_01F1[] = _("<PROC=0>\n<END>");
const u8 String_01F2[] = _("<LOCK=106>月光魔法\n「エンチャント・ソル」\nを覚えた!!");
const u8 String_01F3[] = _("<PROC=0>\n<END>");
const u8 String_01F4[] = _("<LABEL=ZAJI>魔法少女</LABEL>\n「ええか?");
const u8 String_01F5[] = _("魔法を使うには、まずメニュ―\n画面で使いたい魔法を装備して\nおかなあかん。");
const u8 String_01F6[] = _("したら、今セットしている魔法\nが画面左下に表示されるんや。");
const u8 String_01F7[] = _("エンチャント(付加)魔法は、Ｌ\nボタン(魔法ボタン)でオン・オ\nフの切り換(か)えができる。");
const u8 String_01F8[] = _("エンチャント・オンの状態で武\n器攻撃(ぶきこうげき)を行えば");
const u8 String_01F9[] = _("その攻撃は属性攻撃になるっち\nゅうわけや。");
const u8 String_01FA[] = _("それから、魔法はエナジ―を消\n費すんねん。残量に気ぃつけて\n忘れんと太陽チャ―ジしぃや。");
const u8 String_01FB[] = _("ほなら後はまかせたで?\nうちは先、商店街行っとるから\nさっさと来ぃや。」");
const u8 String_01FC[] = _("<PROC=0>\n<END>");
const u8 String_01FD[] = _("<PROC=0>\n<END>");
const u8 String_01FE[] = _("自らの目指すべき道に\n迷うことなかれ。");
const u8 String_01FF[] = _("画面右上は北、左下は南、\n右下は東、左上は西と知れ。");
const u8 String_0200[] = _("<PROC=0>\n<END>");
const u8 String_0201[] = _("危険は事前に察知せよ。");
const u8 String_0202[] = _("Ｒボタンを押(お)しながら✚ボ\nタンを動かせば、");
const u8 String_0203[] = _("見回しで周りの状況(じょうき\nょう)を確認することができる");
const u8 String_0204[] = _("<PROC=0>\n<END>");
const u8 String_0205[] = _("倒(たお)せ!!");
const u8 String_0206[] = _("攻撃(こうげき)はＢボタン(武\n器ボタン)にて行う。");
const u8 String_0207[] = _("ボタンを押(お)せば武器を構え\n放せば攻撃をすることができる");
const u8 String_0208[] = _("<PROC=0>\n<END>");
const u8 String_0209[] = _("あきらめは死の友と知れ。");
const u8 String_020A[] = _("クモの巣など、敵モンスタ―や\nその罠(わな)に捕(つか)まって\nしまったときは、");
const u8 String_020B[] = _("✚ボタンをすばやく動かして、\nただちに脱出(だっしゅつ)せよ");
const u8 String_020C[] = _("<PROC=0>\n<END>");
const u8 String_020D[] = _("太陽の光、その力を知れ。");
const u8 String_020E[] = _("画面下中央にある太陽(SUN)ゲ\n―ジは、太陽センサ―がキャッ\nチした太陽の光の強さを示す。");
const u8 String_020F[] = _("<PROC=0>\n<END>");
const u8 String_0210[] = _("自らのライフ(命)、\nその限界を知れ。");
const u8 String_0211[] = _("画面左上のライフ(LIFE)ゲ―ジ\nは、命の消耗(しょうもう)度合\nいを示す。");
const u8 String_0212[] = _("敵からの攻撃(こうげき)などに\nよりダメ―ジを受けると、ライ\nフは減少し、");
const u8 String_0213[] = _("ライフがゼロになればゲ―ムオ\n―バ―となる。");
const u8 String_0214[] = _("アイテムを使い、早めに回復す\nることを心がけよ。");
const u8 String_0215[] = _("<PROC=0>\n<END>");
const u8 String_0216[] = _("自らのエナジ―(太陽エネルギ\n―)、その限界を知れ。");
const u8 String_0217[] = _("画面左上のエナジ―(ENE)ゲ―\nジは、太陽エネルギ―の消耗(\nしょうもう)度合いを示す。");
const u8 String_0218[] = _("太陽銃(たいようじゅう)は、エ\nナジ―を消費して太陽ショット\nを放つ魔法機械。");
const u8 String_0219[] = _("エナジ―がゼロになれば撃(う)\nつことはできない。");
const u8 String_021A[] = _("エナジ―の回復には太陽チャ―\nジが必要となる。");
const u8 String_021B[] = _("屋外エリアでは、太陽センサ―\nに太陽の光を当てることにより");
const u8 String_021C[] = _("エナジ―は自然にチャ―ジされ\nる。");
const u8 String_021D[] = _("またＡボタンを押(お)しっぱな\nしにすれば、急速チャ―ジを行\nうこともできる。");
const u8 String_021E[] = _("<PROC=0>\n<END>");
const u8 String_021F[] = _("状況(じょうきょう)を理解し、\n万事に備えよ。");
const u8 String_0220[] = _("メニュ―画面では、マップ(地\n図)やステ―タス(状態)などを\n確認することができる。");
const u8 String_0221[] = _("STARTボタンでメニュ―画面に\n入り、");
const u8 String_0222[] = _("Ｌ・Ｒボタンで各種メニュ―を\n選択(せんたく)することができ\nる。");
const u8 String_0223[] = _("アクション画面に戻(もど)るに\nはＢボタンを使え。");
const u8 String_0224[] = _("<PROC=0>\n<END>");
const u8 String_0225[] = _("アイテムを集め、\n有効に活用せよ。");
const u8 String_0226[] = _("宝箱は、近づいてＡボタンを押\n(お)せば開けることができる。");
const u8 String_0227[] = _("入手したアイテムの使用はメニ\nュ―画面において行う。");
const u8 String_0228[] = _("アイテムは一定の数までしか持\nつことができない。");
const u8 String_0229[] = _("ムダ使いはもちろん、使い惜(\nお)しんで宝の持ちぐされとな\nらぬよう、注意せよ。");
const u8 String_022A[] = _("<PROC=0>\n<END>");
const u8 String_022B[] = _("張りつけ!!");
const u8 String_022C[] = _("崩(くず)れた通路などのせまい\n足場は、");
const u8 String_022D[] = _("壁(かべ)に張りつくことによっ\nて通過することができる。");
const u8 String_022E[] = _("壁に向かって✚ボタンを押(お)\nしっぱなしにすれば、張りつき\nが可能。");
const u8 String_022F[] = _("そのまま✚ボタンを壁にそって\n動かせば、張りつき移動ができ\nる。");
const u8 String_0230[] = _("<PROC=0>\n<END>");
const u8 String_0231[] = _("押(お)せ!!");
const u8 String_0232[] = _("岩ブロックなどの移動ブロック\nは、");
const u8 String_0233[] = _("ブロックに向かって✚ボタンを\n押しっぱなしにすれば、動かす\nことができる。");
const u8 String_0234[] = _("<PROC=0>\n<END>");
const u8 String_0235[] = _("天窓を探し出し、\n有効に活用せよ。");
const u8 String_0236[] = _("太陽の光の届かない屋内エリア\nでは、");
const u8 String_0237[] = _("太陽センサ―が太陽の光をキャ\nッチしていても、太陽チャ―ジ\nをすることはできない。");
const u8 String_0238[] = _("しかし天窓エリアでは、太陽の\n光があれば屋外エリア同様、太\n陽チャ―ジを行うことができる");
const u8 String_0239[] = _("また、太陽の光を苦手とするア\nンデッド(不死)タイプのモンス\nタ―には、");
const u8 String_023A[] = _("天窓の光でダメ―ジをあたえる\nことも可能だ。");
const u8 String_023B[] = _("<PROC=0>\n<END>");
const u8 String_023C[] = _("叩(たた)け!!");
const u8 String_023D[] = _("聴覚(ちょうかく)を持つ敵は、\n物音を聞くと音の鳴った場所を\n調べに来る。");
const u8 String_023E[] = _("壁叩(かべたた)きを利用すれば\n敵モンスタ―を誘(さそ)い出す\nことが可能だ。");
const u8 String_023F[] = _("壁を叩くには、壁張りつき中に\nＡボタンを押(お)せばいい。");
const u8 String_0240[] = _("<PROC=0>\n<END>");
const u8 String_0241[] = _("己の武器を知れ。");
const u8 String_0242[] = _("手に入れた武器は、メニュ―画\n面にて内容の確認と装備の変更\n(へんこう)をする事ができる。");
const u8 String_0243[] = _("アクション画面では、現在セッ\nトしている武器が画面右下に表\n示される。");
const u8 String_0244[] = _("<PROC=0>\n<END>");
const u8 String_0245[] = _("守れ!!");
const u8 String_0246[] = _("防具を装備すれば、敵から受け\nるダメ―ジを減らすことができ\nる。");
const u8 String_0247[] = _("手に入れた防具は、メニュ―画\n面にて内容の確認と装備の変更\n(へんこう)をする事ができる。");
const u8 String_0248[] = _("<PROC=0>\n<END>");
const u8 String_0249[] = _("敵の後ろを取れ。");
const u8 String_024A[] = _("敵モンスタ―に見つかれば、\n当然攻撃(こうげき)を受ける。");
const u8 String_024B[] = _("しかし視界を持つ敵に対しては\nその視界に入らなければ見つか\nることはない。");
const u8 String_024C[] = _("敵の背後を通れば、戦わずにや\nり過ごすことも可能だ。");
const u8 String_024D[] = _("また背後からの攻撃は、敵モン\nスタ―により大きなダメ―ジを\nあたえることができる。");
const u8 String_024E[] = _("<PROC=0>\n<END>");
const u8 String_024F[] = _("<LABEL=ZAJI></LABEL>これでトリガ―・オブ・ソルや\nなんて、かあちゃん情けないわ");
const u8 String_0250[] = _("<PROC=0>\n<END>");
const u8 String_0251[] = _("<LABEL=ZAJI></LABEL>ガンマスタ―の称号(しょうご\nう)も返さなあかんなぁ。");
const u8 String_0252[] = _("<PROC=0>\n<END>");
const u8 String_0253[] = _("<LABEL=ZAJI></LABEL>コンティニュ―に頼(たよ)っと\nるからそんなことになんねん。");
const u8 String_0254[] = _("<PROC=0>\n<END>");
const u8 String_0255[] = _("<LABEL=ZAJI></LABEL>もうちょい考えて行動しぃや。");
const u8 String_0256[] = _("<PROC=0>\n<END>");
const u8 String_0257[] = _("<LABEL=ZAJI></LABEL>ザコをなんぼ倒(たお)したか\nて意味ないで。");
const u8 String_0258[] = _("<PROC=0>\n<END>");
const u8 String_0259[] = _("<LABEL=ZAJI></LABEL>アンデッドに情けかけとる場合\nちゃうで。");
const u8 String_025A[] = _("<PROC=0>\n<END>");
const u8 String_025B[] = _("<LABEL=ZAJI></LABEL>グラディエ―タ―ちゅうのはま\nぐれなん?");
const u8 String_025C[] = _("<PROC=0>\n<END>");
const u8 String_025D[] = _("<LABEL=ZAJI></LABEL>暗子ちゃんもあきれとるで。");
const u8 String_025E[] = _("<PROC=0>\n<END>");
const u8 String_025F[] = _("<LABEL=ZAJI></LABEL>太陽商人言うなら、せめて他の\n武器と交換(こうかん)しぃや。");
const u8 String_0260[] = _("<PROC=0>\n<END>");
const u8 String_0261[] = _("<LABEL=ZAJI></LABEL>ほんまはパチモンちゃうん?");
const u8 String_0262[] = _("<PROC=0>\n<END>");
const u8 String_0263[] = _("<LABEL=ZAJI></LABEL>太陽嫌(きら)いなん?");
const u8 String_0264[] = _("<PROC=0>\n<END>");
const u8 String_0265[] = _("<LABEL=ZAJI></LABEL>キングの称号(しょうごう)に泥\n(どろ)ぬりなや。");
const u8 String_0266[] = _("<PROC=0>\n<END>");
const u8 String_0267[] = _("<LABEL=ZAJI></LABEL>称号(しょうごう)ル―クが聞い\nてあきれるわ。");
const u8 String_0268[] = _("<PROC=0>\n<END>");
const u8 String_0269[] = _("<LABEL=ZAJI></LABEL>称号(しょうごう)ナイトで満足\nしとる場合ちゃうで。");
const u8 String_026A[] = _("<PROC=0>\n<END>");
const u8 String_026B[] = _("<LABEL=ZAJI></LABEL>称号(しょうごう)ポ―ンはダテ\nやないな?");
const u8 String_026C[] = _("<PROC=0>\n<END>");
const u8 String_026D[] = _("赤の水晶");
const u8 String_026E[] = _("青の水晶");
const u8 String_026F[] = _("緑の水晶");
const u8 String_0270[] = _("黄の水晶");
const u8 String_0271[] = _("丸いくぼみがある。\n何かをはめ込(こ)む穴のようだ");
const u8 String_0272[] = _("<PROC=0>\n<END>");
const u8 String_0273[] = _("何をはめ込みますか?\n <ALTER><EXTEND=0></ALTER>");
const u8 String_0274[] = _("何をはめ込みますか?\n <ALTER><EXTEND=0></ALTER>　<ALTER><EXTEND=1></ALTER>");
const u8 String_0275[] = _("何をはめ込みますか?\n <ALTER><EXTEND=0></ALTER>　<ALTER><EXTEND=1></ALTER>\n <ALTER><EXTEND=2></ALTER>");
const u8 String_0276[] = _("何をはめ込みますか?\n <ALTER><EXTEND=0></ALTER>　<ALTER><EXTEND=1></ALTER>\n <ALTER><EXTEND=2></ALTER>　<ALTER><EXTEND=3></ALTER>");
const u8 String_0277[] = _("はまらないようだ・・・");
const u8 String_0278[] = _("<PROC=0>\n<END>");
const u8 String_0279[] = _("「<EXTEND=0>」\nがはまっている。");
const u8 String_027A[] = _("<PROC=0>\n<END>");
const u8 String_027B[] = _("いつわりの墓、その全てが暴か\nれるとき、道は開かれる。");
const u8 String_027C[] = _("凶暴(きょうぼう)なる墓守は、\n真なる墓を守る。注意すべし。");
const u8 String_027D[] = _("<PROC=0>\n<END>");
const u8 String_027E[] = _("よく見ると、メッセ―ジが書き\n足されている。");
const u8 String_027F[] = _("「いつわりの墓、すなわちグレ\nイブキ―パ―が振(ふ)り向かな\nい墓の、墓石を押(お)せ」");
const u8 String_0280[] = _("<PROC=0>\n<END>");
const u8 String_0281[] = _("");
const u8 String_0282[] = _("");
const u8 String_0283[] = _("");
const u8 String_0284[] = _("<PROC=0>\n<END>");
const u8 String_0285[] = _("2つ目の色、\nそれは暗黒なる瞳(ひとみ)、\nその赤き輝(かがや)き。");
const u8 String_0286[] = _("瞳は多くの椅子(いす)が並ぶ集\nいの間に眠(ねむ)る。");
const u8 String_0287[] = _("眠る瞳は目には見えず、\n太陽の光によってのみ輝く。");
const u8 String_0288[] = _("<PROC=0>\n<END>");
const u8 String_0289[] = _("4つ目の色、\nそれは大いなる空と海、\nその青き輝(かがや)き。");
const u8 String_028A[] = _("空と海は2体の白き門番、\n雲と波によって守られている。");
const u8 String_028B[] = _("<PROC=0>\n<END>");
const u8 String_028C[] = _("3つ目の色、\nそれは豊かなる緑、\nその葉の輝(かがや)き。");
const u8 String_028D[] = _("葉は時を超(こ)える言の葉、\n書によって守られている。");
const u8 String_028E[] = _("こ、と、の、は、\nを書に問うべし。");
const u8 String_028F[] = _("<PROC=0>\n<END>");
const u8 String_0290[] = _("「暗黒物質と吸血変異」\n「ヴァンパイア・血の歴史」");
const u8 String_0291[] = _("<PROC=0>");
const u8 String_0292[] = _("「ガンマン10ヶ条」\n「荒野(こうや)の歩き方」");
const u8 String_0293[] = _("<PROC=0>");
const u8 String_0294[] = _("「最後の竜・残された言葉」\n「世紀末の輪廻(りんね)」");
const u8 String_0295[] = _("<PROC=0>");
const u8 String_0296[] = _("「太陽の一族・太陽仔の謎」\n「トロ―ルの姫」");
const u8 String_0297[] = _("<PROC=0>");
const u8 String_0298[] = _("「奈落(ならく)のナイトメア」\n「呪(のろ)いと浄化」");
const u8 String_0299[] = _("<PROC=0>");
const u8 String_029A[] = _("「発掘(はっくつ)の魔法機械」\n「滅びの一族・月光仔の謎」");
const u8 String_029B[] = _("<PROC=0>");
const u8 String_029C[] = _("「魔法使いになる方法」\n「魔法カ―ド・タロット入門」");
const u8 String_029D[] = _("<PROC=0>");
const u8 String_029E[] = _("「闇の一族・イモ―タルの謎」\n「ユグドラシル幻想」");
const u8 String_029F[] = _("<PROC=0>");
const u8 String_02A0[] = _("「ラグナロク大崩壊」\n「螺旋(らせん)の伝承」");
const u8 String_02A1[] = _("<PROC=0>");
const u8 String_02A2[] = _("「」\n「」");
const u8 String_02A3[] = _("<PROC=0>");
const u8 String_02A4[] = _("本の奥にスイッチがある。");
const u8 String_02A5[] = _("<PROC=0>");
const u8 String_02A6[] = _("スイッチを押しますか?\n <ALTER>押す</ALTER>　<ALTER>押さない</ALTER>\n");
const u8 String_02A7[] = _("本の奥のスイッチは、すでに押\n(お)されている。");
const u8 String_02A8[] = _("<PROC=0>\n<END>");
const u8 String_02A9[] = _("壊(こわ)せ!!");
const u8 String_02AA[] = _("移動ブロックの木箱は、ハンマ\n―タイプの武器で破壊(はかい)\nすることができる。");
const u8 String_02AB[] = _("<PROC=0>\n<END>");
const u8 String_02AC[] = _("ヤリは攻撃距離が剣やオノ\nより長いので、離れた場所\nを攻撃することができる。");
const u8 String_02AD[] = _("どこかにヤリがないか探し\nてみよう。");
const u8 String_02AE[] = _("<PROC=0>\n<END>");
const u8 String_02AF[] = _("火と水が合わさるとき、\n世界の姿は色となって現れる。");
const u8 String_02B0[] = _("4つの色が現れるとき、\n隠(かく)された道もまた現れる");
const u8 String_02B1[] = _("1つ目の色、\nそれは大地を照らす太陽、\nその黄金の輝(かがや)き。");
const u8 String_02B2[] = _("<PROC=0>\n<END>");
const u8 String_02B3[] = _("載(の)せろ!!");
const u8 String_02B4[] = _("床(ゆか)に設置された重量スイ\nッチは、その上におもりとなる\nモノを載せると起動する。");
const u8 String_02B5[] = _("<PROC=0>\n<END>");
const u8 String_02B6[] = _("太陽スタンド説明");
const u8 String_02B7[] = _("<PROC=0>\n<END>");
const u8 String_02B8[] = _("灯(とも)せ!!");
const u8 String_02B9[] = _("フレイムをエンチャントして攻\n撃(こうげき)すれば、");
const u8 String_02BA[] = _("燭台(しょくだい)に火を灯すこ\nとができる。");
const u8 String_02BB[] = _("<PROC=0>\n<END>");
const u8 String_02BC[] = _("叩(たた)け!!");
const u8 String_02BD[] = _("錆(さ)びたレバ―スイッチは、");
const u8 String_02BE[] = _("ハンマ―タイプの武器で攻撃(\nこうげき)しなくては、起動さ\nせることができない。");
const u8 String_02BF[] = _("<PROC=0>\n<END>");
const u8 String_02C0[] = _("たどり着け!!");
const u8 String_02C1[] = _("青色のランプ、接触(せっしょ\nく)スイッチは触(さわ)ること\nで起動する。");
const u8 String_02C2[] = _("<PROC=0>\n<END>");
const u8 String_02C3[] = _("クイックチェンジを使いこなせ");
const u8 String_02C4[] = _("SELECTボタンを押(お)しながら\nＲボタンを押すことで、");
const u8 String_02C5[] = _("セットする武器を素早く切り換\n(か)えることができる。");
const u8 String_02C6[] = _("ただし切り換えることができる\nのは、メニュ―画面にて装備し\nた武器に限られる。");
const u8 String_02C7[] = _("<PROC=0>\n<END>");
const u8 String_02C8[] = _("上空にいるドゥネイルに攻撃(\nこうげき)を当てることはでき\nない。");
const u8 String_02C9[] = _("燭台(しょくだい)に火を灯(と\nも)し、ドゥネイルを低空に誘\n(さそ)い出せ。");
const u8 String_02CA[] = _("<PROC=0>\n<END>");
const u8 String_02CB[] = _("燭台(しょくだい)に火を灯(と\nも)すには2つの方法がある。");
const u8 String_02CC[] = _("1つはフレイムをエンチャント\nした武器で燭台を攻撃し、\n直接火を点けるという方法。");
const u8 String_02CD[] = _("もう1つは4つのレバ―スイッチ\nを起動して、燭台を点火すると\nいう方法だ。");
const u8 String_02CE[] = _("<PROC=0>\n<END>");
const u8 String_02CF[] = _("<LABEL=OTENKO>おてんこさま</LABEL>\n「大聖堂はこの奥(おく)か。\nどこにいる、スミス・・・」");
const u8 String_02D0[] = _("<PROC=0>\n<END>");
const u8 String_02D1[] = _("<LABEL=OTENKO>おてんこさま</LABEL>\n「この扉(とびら)を開けるには\nカギが必要だ。");
const u8 String_02D2[] = _("<NAME>、\n今は別のル―トを探そう」");
const u8 String_02D3[] = _("<PROC=0>\n<END>");
const u8 String_02D4[] = _("<LABEL=OTENKO>おてんこさま</LABEL>\n「クラブか・・・ハンマ―(つ\nち)タイプの武器だな。");
const u8 String_02D5[] = _("威力(いりょく)も大きいが、\nそのぶん隙(すき)も大きい。\n注意してくれ。");
const u8 String_02D6[] = _("ともかくそれを使えば、通路を\nふさいでいた木箱を破壊(はか\nい)できるはずだ」");
const u8 String_02D7[] = _("<PROC=0>\n<END>");
const u8 String_02D8[] = _("<LABEL=OTENKO>おてんこさま</LABEL>\n「ここは・・・");
const u8 String_02D9[] = _("どうやら大聖堂の中に入ったよ\nうだな」");
const u8 String_02DA[] = _("<PROC=0>\n<END>");
const u8 String_02DB[] = _("<LABEL=OTENKO>おてんこさま</LABEL>\n「ショ―トスピアか・・・\nスピア(やり)タイプの武器だな");
const u8 String_02DC[] = _("射程距離(しゃていきょり)が長\nいぶん、ふところには隙(すき)\nができる。注意してくれ。");
const u8 String_02DD[] = _("ともかくそれを使えば、1ブロ\nック離(はな)れた場所にも攻撃\n(こうげき)ができる。");
const u8 String_02DE[] = _("東側の2つの部屋にあったそれ\nぞれの仕掛(しか)けも、これで\n動かせるはずだ」");
const u8 String_02DF[] = _("<PROC=0>\n<END>");
const u8 String_02E0[] = _("<LABEL=OTENKO>おてんこさま</LABEL>\n「この気配は・・・\nイモ―タル!!");
const u8 String_02E1[] = _("太陽銃(たいようじゅう)はない\nが・・・\n行けるな、<NAME>?」");
const u8 String_02E2[] = _("<PROC=0>\n<END>");
const u8 String_02E3[] = _("<LABEL=OTENKO>おてんこさま</LABEL>\n「まて、<NAME>!");
const u8 String_02E4[] = _("奥の部屋を調べるのが先だ」");
const u8 String_02E5[] = _("<PROC=0>\n<END>");
const u8 String_02E6[] = _("<LABEL=OTENKO>おてんこさま</LABEL>\n「カギを手に入れたようだな。");
const u8 String_02E7[] = _("青い扉(とびら)にはカギがかか\nっている。");
const u8 String_02E8[] = _("扉の前でＡボタンを押(お)して\nカギを使うんだ。");
const u8 String_02E9[] = _("ただしカギの形が合わなければ\n扉は開かない。注意してくれ」");
const u8 String_02EA[] = _("<PROC=0>\n<END>");
const u8 String_02EB[] = _("<LABEL=OTENKO>おてんこさま</LABEL>\n「大広間の床絵(ゆかえ)が現れ\nたようだが・・・");
const u8 String_02EC[] = _("色が足りないな。");
const u8 String_02ED[] = _("あと3つ、水晶が必要だという\nことか・・・」");
const u8 String_02EE[] = _("<PROC=0>\n<END>");
const u8 String_02EF[] = _("<LABEL=OTENKO>おてんこさま</LABEL>\n「ここが砂漠(さばく)の遺跡(\nいせき)だな。");
const u8 String_02F0[] = _("ここにあのヴァンパイアが\n・・・");
const u8 String_02F1[] = _("<PROC=0>\n<END>");
const u8 String_02F2[] = _("<NAME>、\nあのときの借りを返すぞ!!");
const u8 String_02F3[] = _("<PROC=1><LOCK=85>太陽と共にあらんことを!」");
const u8 String_02F4[] = _("<PROC=0>\n<END>");
const u8 String_02F5[] = _("<LABEL=OTENKO>おてんこさま</LABEL>\n「この暑さ、まさに砂漠だな。");
const u8 String_02F6[] = _("水なしではおまえのライフが持\nつまい。");
const u8 String_02F7[] = _("画面上中央に水の残量がカウン\nトされるから、");
const u8 String_02F8[] = _("水がなくなったら、無理をせず\n補給に戻(もど)るんだ。\nいいな、<NAME>」");
const u8 String_02F9[] = _("<PROC=0>\n<END>");
const u8 String_02FA[] = _("<LABEL=OTENKO>おてんこさま</LABEL>\n「待て、<NAME>!!");
const u8 String_02FB[] = _("感じるか?\nこの気配・・・\n間違(まちが)いない。");
const u8 String_02FC[] = _("この奥にヤツが、\nあのヴァンパイアがいる!");
const u8 String_02FD[] = _("覚悟(かくご)はいいな?");
const u8 String_02FE[] = _("<PROC=1><LOCK=85>太陽と共にあらんことを!」");
const u8 String_02FF[] = _("<PROC=0>\n<END>");
const u8 String_0300[] = _("<LABEL=OTENKO>おてんこさま</LABEL>\n「これはワ―プ魔方陣(まほう\nじん)・・・");
const u8 String_0301[] = _("どうやらダンジョンの入口辺り\nにつながっているようだ。");
const u8 String_0302[] = _("これを使えばダンジョンの行き\n来が自由にできる。");
const u8 String_0303[] = _("転移(ワ―プ)を行なうには、魔\n方陣の上でＡボタンを押(お)せ\nばいい。");
const u8 String_0304[] = _("もし今の装備に不安があるなら\n1度街に戻(もど)って装備を整\nえたらどうだ?」");
const u8 String_0305[] = _("<PROC=0>\n<END>");
const u8 String_0306[] = _("<LABEL>「おいしい水」\nを手に入れた!!</LABEL>");
const u8 String_0307[] = _("<PROC=0>\n<END>");
const u8 String_0308[] = _("<LABEL=OTENKO>おてんこさま</LABEL>\n「待つんだ、<NAME>!!");
const u8 String_0309[] = _("水も持たずにこの先の砂漠に入\nるのは危険だ。そこに見えるわ\nき水をくんでいこう」");
const u8 String_030A[] = _("<PROC=0>\n<END>");
const u8 String_030B[] = _("ヴァンパイアに正面からの攻撃\nは通じない。");
const u8 String_030C[] = _("サバタが作り出すブラックホ―\nルで、ヴァンパイアの動きを封\n(ふう)じろ。");
const u8 String_030D[] = _("<PROC=0>\n<END>");
const u8 String_030E[] = _("サバタを守り、ブラックホ―ル\nを完成させろ。");
const u8 String_030F[] = _("サバタがダメ―ジを受けないよ\nうに、ヴァンパイアの攻撃を自\n分に引きつけ、");
const u8 String_0310[] = _("サバタを狙(ねら)うヴァンパイ\nアソ―ドは、確実に叩(たた)き\n落とせ。");
const u8 String_0311[] = _("<PROC=0>\n<END>");
const u8 String_0312[] = _("<LABEL=SABATA>サバタ</LABEL>\n「なぜ俺(おれ)がここにいるの\nか、不思議に思うか?");
const u8 String_0313[] = _("俺はおまえとは違(ちが)う。\nこの街がどうなろうと知ったこ\nとではない。");
const u8 String_0314[] = _("この俺を暗黒の戦士として育て\nたクイ―ン・オブ・イモ―タル\n・・・ヘル。");
const u8 String_0315[] = _("もう、あのいつわりの母親を憎\n(にく)んでいるわけでもない。\nだが、");
const u8 String_0316[] = _("彼女(かのじょ)を、そして俺自\n身をも狂気(きょうき)へと走ら\nせた銀河意思ダ―ク、");
const u8 String_0317[] = _("そしてその意思に従う闇(やみ)\nの一族イモ―タル。ヤツらの思\nい通りにさせるつもりはない。");
const u8 String_0318[] = _("ただそれだけだ・・・」");
const u8 String_0319[] = _("<PROC=0>\n<END>");
const u8 String_031A[] = _("<LABEL=SABATA>サバタ</LABEL>\n「ヤツは強い・・・");
const u8 String_031B[] = _("俺(おれ)の攻撃(こうげき)もほ\nとんどがかわされ、");
const u8 String_031C[] = _("レンズを1つ奪(うば)い取るの\nがやっとだった。");
const u8 String_031D[] = _("ヤツから太陽銃(たいようじゅ\nう)を取り戻(もど)すなど至難\nの業。");
const u8 String_031E[] = _("あるいは破壊(はかい)してしま\nうべきかもしれん・・・」");
const u8 String_031F[] = _("<PROC=0>\n<END>");
const u8 String_0320[] = _("<LABEL=SABATA>サバタ</LABEL>\n「道具屋のキッド?\nあの爆発頭か・・・");
const u8 String_0321[] = _("そうだ。アイツの邪魔(じゃま)\nがなければ、こんな無様なこと\nにはならなかったのだ!!");
const u8 String_0322[] = _("何?\n俺(おれ)がアイツを助けた?\n俺がなぜそんなことをする!」");
const u8 String_0323[] = _("<PROC=0>\n<END>");
const u8 String_0324[] = _("<LABEL=SABATA>サバタ</LABEL>\n「この遺跡(いせき)に残された\n伝承を知っているか?");
const u8 String_0325[] = _("そこには死者の復活がうたわれ\nている。");
const u8 String_0326[] = _("アンデッドのように生前の姿や\n記憶(きおく)を失うのではなく");
const u8 String_0327[] = _("死ぬ前の自分を保ったままの復\n活・・・");
const u8 String_0328[] = _("それはイモ―タルのことを指し\nているのか、それとも人の身に\n起こりうることなのか?");
const u8 String_0329[] = _("だがそんな虫のいい話があるわ\nけがない。過去を変えることな\nど、できはしないのだ・・・」");
const u8 String_032A[] = _("<PROC=0>\n<END>");
const u8 String_032B[] = _("<LABEL=OTENKO>おてんこさま</LABEL>\n「大丈夫か、<NAME>!?」");
const u8 String_032C[] = _("<PROC=0>\n<END>");
const u8 String_032D[] = _("火の祝福を得た!!");
const u8 String_032E[] = _("<PROC=0>\n<END>");
const u8 String_032F[] = _("<PROC=1><LOCK=96>太陽魔法「ダイナマイト」\nを覚えた!!");
const u8 String_0330[] = _("ダイナマイトは足元に爆弾(ば\nくだん)を仕掛(しか)ける攻撃\n(こうげき)魔法だ。");
const u8 String_0331[] = _("仕掛けた爆弾は一定の時間がた\nつと自動的に爆発するが、太陽\nゲ―ジがゼロでは爆発しない。");
const u8 String_0332[] = _("また爆弾の威力(いりょく)は、\n精神力(ココロ)と太陽ゲ―ジ\nの値に比例する。");
const u8 String_0333[] = _("<PROC=0>\n<END>");
const u8 String_0334[] = _("<LABEL=KID>キッド</LABEL>\n「くれぐれも注意しろよ?\n特に宝箱にはな」");
const u8 String_0335[] = _("<PROC=0>\n<END>");
const u8 String_0336[] = _("<EXTEND=0>\n(やられた・・・)");
const u8 String_0337[] = _("<PROC=0>\n<END>");
const u8 String_0338[] = _("<LABEL=R_DJUNGO><NAME></LABEL>");
const u8 String_0339[] = _("<PROC=0>\n<END>");
const u8 String_033A[] = _("<LABEL=B_DJUNGO><NAME></LABEL>");
const u8 String_033B[] = _("<PROC=0>\n<END>");
const u8 String_033C[] = _("太陽の光をコントロ―ルせよ。");
const u8 String_033D[] = _("太陽の光が強ければ、風と炎は\nその力を増す。");
const u8 String_033E[] = _("太陽の光を操り、風と炎を乗り\n越(こ)えよ。");
const u8 String_033F[] = _("<PROC=0>\n<END>");
const u8 String_0340[] = _("砕(くだ)け!!");
const u8 String_0341[] = _("クラウドをエンチャントして攻\n撃(こうげき)すれば、");
const u8 String_0342[] = _("岩ブロックを破壊(はかい)する\nことができる。");
const u8 String_0343[] = _("<PROC=0>\n<END>");
const u8 String_0344[] = _("消せ!!");
const u8 String_0345[] = _("フロストをエンチャントして攻\n撃(こうげき)すれば、\n炎を消すことができる。");
const u8 String_0346[] = _("<PROC=0>\n<END>");
const u8 String_0347[] = _("溶(と)かせ!!");
const u8 String_0348[] = _("フレイムをエンチャントして攻\n撃(こうげき)すれば、\n氷を溶かすことができる。");
const u8 String_0349[] = _("<PROC=0>\n<END>");
const u8 String_034A[] = _("属性を使いこなせ。");
const u8 String_034B[] = _("属性キュ―ブは特定の属性をエ\nンチャントして攻撃(こうげき)\nすると、その性質を変化させる");
const u8 String_034C[] = _("フレイムでは、\n炎を宿し周りに熱を発する。");
const u8 String_034D[] = _("フロストでは、\n凍りつき浮遊(ふゆう)の力をな\nくし、");
const u8 String_034E[] = _("クラウドでは、\n雲のごとく宙を移動する。");
const u8 String_034F[] = _("そしてア―スでは、\n大地の元に消え去る。");
const u8 String_0350[] = _("<PROC=0>\n<END>");
const u8 String_0351[] = _("突(つ)け!!");
const u8 String_0352[] = _("属性キュ―ブはクラウドのエン\nチャント攻撃(こうげき)で空中\nを移動させることができる。");
const u8 String_0353[] = _("このときスピアタイプの武器を\n使えば、2ブロック移動させる\nことができる。");
const u8 String_0354[] = _("<PROC=0>\n<END>");
const u8 String_0355[] = _("合わせろ!!");
const u8 String_0356[] = _("紋章(もんしょう)スイッチは、\nその上に同じ紋章のブロックを\n載(の)せれば起動する。");
const u8 String_0357[] = _("<PROC=0>\n<END>");
const u8 String_0358[] = _("残されたメッセ―ジ");
const u8 String_0359[] = _("「燭台(しょくだい)に火を灯せ\nば鉄格子は開く。");
const u8 String_035A[] = _("<PROC=0>\n<END>");
const u8 String_035B[] = _("吹(ふ)き出す炎のために近づく\nことはできないが、");
const u8 String_035C[] = _("アレに火を点けて放り込(こ)め\nばいい」");
const u8 String_035D[] = _("<PROC=0>\n<END>");
const u8 String_035E[] = _("音に注意せよ。");
const u8 String_035F[] = _("アンデッドタイプのモンスタ―\nマミ―は、");
const u8 String_0360[] = _("視覚を持たない代わりに聴覚(\nちょうかく)がすぐれている。");
const u8 String_0361[] = _("姿を見られて見つかることはな\nいが、小さな足音にも敏感(び\nんかん)に反応する。注意せよ");
const u8 String_0362[] = _("<PROC=0>\n<END>");
const u8 String_0363[] = _("四角いくぼみがある。\n何かをはめ込(こ)む穴のようだ");
const u8 String_0364[] = _("<PROC=0>\n<END>");
const u8 String_0365[] = _("石版のかけらをはめ込みますか\n?\n <ALTER>はい</ALTER>　<ALTER>いいえ</ALTER>");
const u8 String_0366[] = _("<PROC=0>\n<END>");
const u8 String_0367[] = _("石版のかけらをはめ込んだ。");
const u8 String_0368[] = _("<PROC=0>\n<END>");
const u8 String_0369[] = _("石版のかけらをはめ込んだ。\n石版が完成した!!");
const u8 String_036A[] = _("<PROC=0>\n<END>");
const u8 String_036B[] = _("くぼみの下に文字が刻まれてい\nる。読んでみますか?\n <ALTER>はい</ALTER>　<ALTER>いいえ</ALTER>");
const u8 String_036C[] = _("<PROC=0>\n<END>");
const u8 String_036D[] = _("遺跡(いせき)を守るため、カギ\nとなる石版を3つに分け砂漠(さ\nばく)に隠(かく)した。");
const u8 String_036E[] = _("<PROC=0>\n<END>");
const u8 String_036F[] = _("2つのドクロの間。");
const u8 String_0370[] = _("<PROC=0>\n<END>");
const u8 String_0371[] = _("朽(く)ちたゴ―レムの後ろ。");
const u8 String_0372[] = _("<PROC=0>\n<END>");
const u8 String_0373[] = _("サボテンの輪の中。");
const u8 String_0374[] = _("<PROC=0>\n<END>");
const u8 String_0375[] = _("サボテンの王の下。");
const u8 String_0376[] = _("<PROC=0>\n<END>");
const u8 String_0377[] = _("バットの巣の下。");
const u8 String_0378[] = _("<PROC=0>\n<END>");
const u8 String_0379[] = _("枯(か)れたオアシスの下。");
const u8 String_037A[] = _("<PROC=0>\n<END>");
const u8 String_037B[] = _("ミミックの下。");
const u8 String_037C[] = _("<PROC=0>\n<END>");
const u8 String_037D[] = _("群れからはぐれた炎の下。");
const u8 String_037E[] = _("<PROC=0>\n<END>");
const u8 String_037F[] = _("影(かげ)を封(ふう)じた4人の\n兄弟王を称(たた)え、");
const u8 String_0380[] = _("その燭台(しょくだい)に兄から\n弟の順に火を灯せ。");
const u8 String_0381[] = _("ただし王の1人はウソをついて\nいる。");
const u8 String_0382[] = _("<PROC=0>\n<END>");
const u8 String_0383[] = _("火の王の燭台\n「私は長男であり、\n最も賢(かしこ)い」");
const u8 String_0384[] = _("<PROC=0>\n<END>");
const u8 String_0385[] = _("水の王の燭台\n「私は最も若く美しい」");
const u8 String_0386[] = _("<PROC=0>\n<END>");
const u8 String_0387[] = _("大地の王の燭台\n「私は火の王よりも若いが、\n最も力が強い」");
const u8 String_0388[] = _("<PROC=0>\n<END>");
const u8 String_0389[] = _("風の王の燭台\n「私は水の王の兄であり最も素\n早いが、長男ではない」");
const u8 String_038A[] = _("<PROC=0>\n<END>");
const u8 String_038B[] = _("残されたメッセ―ジ");
const u8 String_038C[] = _("「この仕掛(しか)けを解くには\n年上の王の燭台(しょくだい)か\nら順番に火を灯していけばいい");
const u8 String_038D[] = _("しかしどの王がウソをついてい\nるのか?");
const u8 String_038E[] = _("まずはそれを突(つ)き止める必\n要がある」");
const u8 String_038F[] = _("<PROC=0>\n<END>");
const u8 String_0390[] = _("残されたメッセ―ジ");
const u8 String_0391[] = _("「地の王がウソをついていると\nすると、");
const u8 String_0392[] = _("地の王は火の王よりも年上とい\nうことになる。");
const u8 String_0393[] = _("しかしそれでは火の王の長男だ\nという言葉もウソになってしま\nう。");
const u8 String_0394[] = _("ウソをついているのは1人だけ\nのはず。");
const u8 String_0395[] = _("したがって地の王はウソをつい\nていないことになる」");
const u8 String_0396[] = _("<PROC=0>\n<END>");
const u8 String_0397[] = _("残されたメッセ―ジ");
const u8 String_0398[] = _("「風の王がウソをついていると\nすると、");
const u8 String_0399[] = _("風の王は水の王よりも年下とい\nうことになる。");
const u8 String_039A[] = _("しかしそれでは水の王の最も若\nいという言葉もウソになってし\nまう。");
const u8 String_039B[] = _("したがって風の王はウソをつい\nていないことになる」");
const u8 String_039C[] = _("<PROC=0>\n<END>");
const u8 String_039D[] = _("残されたメッセ―ジ");
const u8 String_039E[] = _("「火の王がウソをついていると\nすると、");
const u8 String_039F[] = _("火の王は最年長ではないという\nことになる。");
const u8 String_03A0[] = _("しかしそれでは他の3人の言葉\nに矛盾(むじゅん)が生じてしま\nう。");
const u8 String_03A1[] = _("したがって火の王はウソをつい\nていないことになる」");
const u8 String_03A2[] = _("<PROC=0>\n<END>");
const u8 String_03A3[] = _("残されたメッセ―ジ");
const u8 String_03A4[] = _("「これで答えは定まった。");
const u8 String_03A5[] = _("あとはウソをついた王の言葉が\n成立しないように兄弟の順番を\n決め、");
const u8 String_03A6[] = _("その順番通りに燭台(しょくだ\nい)に火を灯していけばいい」");
const u8 String_03A7[] = _("<PROC=0>\n<END>");
const u8 String_03A8[] = _("火の試練");
const u8 String_03A9[] = _("炎を移し、\n燭台(しょくだい)に火を灯せ。");
const u8 String_03AA[] = _("<PROC=0>\n<END>");
const u8 String_03AB[] = _("水の試練");
const u8 String_03AC[] = _("重き氷を、\n2つのパネルに載(の)せよ。");
const u8 String_03AD[] = _("<PROC=0>\n<END>");
const u8 String_03AE[] = _("地の試練");
const u8 String_03AF[] = _("大地を踏(ふ)みしめ、\nすべてのパネルを赤く染めよ。");
const u8 String_03B0[] = _("<PROC=0>\n<END>");
const u8 String_03B1[] = _("風の試練");
const u8 String_03B2[] = _("風を操り、\nパネルにたどり着け。");
const u8 String_03B3[] = _("<PROC=0>\n<END>");
const u8 String_03B4[] = _("\n　　　　 猛犬注意!!　　　　 \n");
const u8 String_03B5[] = _("ビ―スト(獣)タイプのモンスタ\n―、バンデットは、アイテムを\n盗む能力を持つ。");
const u8 String_03B6[] = _("奪われたアイテムはバンデット\nを倒せば取り戻すことができる\nが、");
const u8 String_03B7[] = _("食べられたアイテムを取り戻す\nことはできない。");
const u8 String_03B8[] = _("<PROC=0>\n<END>");
const u8 String_03B9[] = _("\n　　　　 頭上注意!!　　　　 \n");
const u8 String_03BA[] = _("ビ―スト(獣)タイプのモンスタ\n―、ポイズンビ―は、ハチの巣\nに潜(ひそ)んでいる。");
const u8 String_03BB[] = _("戦いを避(さ)けたくば、巣を刺\n激(しげき)しないよう注意せよ");
const u8 String_03BC[] = _("<PROC=0>\n<END>");
const u8 String_03BD[] = _("\n　　　　 足元注意!!　　　　 \n");
const u8 String_03BE[] = _("一部の床(ゆか)は、その上を移\n動すると大きな音を発する鳴り\n床となっている。");
const u8 String_03BF[] = _("無闇(むやみ)に音を立てて、敵\nモンスタ―に見つからないよう\nに注意せよ。");
const u8 String_03C0[] = _("<PROC=0>\n<END>");
const u8 String_03C1[] = _("\n　　暗闇(くらやみ)注意!!　　\n");
const u8 String_03C2[] = _("ファントム(幻影)タイプのモン\nスタ―、ゴ―ストは、");
const u8 String_03C3[] = _("視覚でも聴覚(ちょうかく)でも\nなく、大気の動き、すなわち相\n手の動きを感知して行動する。");
const u8 String_03C4[] = _("また、暗闇では姿を見ることが\nできるが、");
const u8 String_03C5[] = _("天窓や燭台(しょくだい)の明か\nりのもとでは姿を消してしまう\nその性質をよく理解せよ。");
const u8 String_03C6[] = _("<PROC=0>\n<END>");
const u8 String_03C7[] = _("重量をコントロ―ルせよ。");
const u8 String_03C8[] = _("重量昇降床(じゅうりょうしょ\nうこうゆか)は乗ったモノの重\nさにより行き先が変化し、");
const u8 String_03C9[] = _("軽いものは上のフロアへ、\n重いものは下のフロアへと運ぶ");
const u8 String_03CA[] = _("<PROC=0>\n<END>");
const u8 String_03CB[] = _("太陽結界について。");
const u8 String_03CC[] = _("太陽結界には闇(やみ)を縛(し\nば)りつける力がある。");
const u8 String_03CD[] = _("結界の上に置いておけば、棺桶\n(かんおけ)に逃(に)げられるこ\nとはない。");
const u8 String_03CE[] = _("<PROC=0>\n<END>");
const u8 String_03CF[] = _("???\n「<NAME>・・・");
const u8 String_03D0[] = _("使うんだ・・・\nヴァンパイアの力、\n暗黒魔法を・・・");
const u8 String_03D1[] = _("スリ―ピングは棺桶(かんおけ)\nを使った回復魔法だ。");
const u8 String_03D2[] = _("棺桶で眠(ねむ)れば、太陽の光\nに頼(たよ)らずともエナジ―を\n回復することができる。");
const u8 String_03D3[] = _("受け入れるんだ、\n暗黒の力を・・・」");
const u8 String_03D4[] = _("<PROC=0>\n<END>");
const u8 String_03D5[] = _("???\n「<NAME>・・・");
const u8 String_03D6[] = _("使うんだ・・・\nヴァンパイアの力、\n暗黒魔法を・・・");
const u8 String_03D7[] = _("チェンジ・マウスはマウス(ね\nずみ)へのチェンジ(変身)魔法\nだ。");
const u8 String_03D8[] = _("マウスになれば、");
const u8 String_03D9[] = _("通常は通ることのできない小さ\nな穴を、潜(くぐ)り抜(ぬ)ける\nことができる。");
const u8 String_03DA[] = _("受け入れるんだ、\n暗黒の力を・・・」");
const u8 String_03DB[] = _("<PROC=0>\n<END>");
const u8 String_03DC[] = _("???\n「<NAME>・・・");
const u8 String_03DD[] = _("使うんだ・・・\nヴァンパイアの力、\n暗黒魔法を・・・");
const u8 String_03DE[] = _("チェンジ・バットはバット(こ\nうもり)へのチェンジ(変身)魔\n法だ。");
const u8 String_03DF[] = _("バットになれば、");
const u8 String_03E0[] = _("超音波(ちょうおんぱ)によって\n通常は見ることのできないモノ\nを見ることができる。");
const u8 String_03E1[] = _("受け入れるんだ、\n暗黒の力を・・・」");
const u8 String_03E2[] = _("<PROC=0>\n<END>");
const u8 String_03E3[] = _("???\n「<NAME>・・・");
const u8 String_03E4[] = _("使うんだ・・・\nヴァンパイアの力、\n暗黒魔法を・・・");
const u8 String_03E5[] = _("チェンジ・ウルフはウルフ(お\nおかみ)へのチェンジ(変身)魔\n法だ。");
const u8 String_03E6[] = _("チェンジ・ウルフを使えば、噛\n(か)みついた相手からライフを\n奪(うば)い取ることができる。");
const u8 String_03E7[] = _("ただし噛みつきは、相手の後ろ\nから行なわなければ成功しない\n注意するんだ。");
const u8 String_03E8[] = _("噛みつき中にＬボタンを連打す\nれば、より多くのライフを奪う\nことができる。");
const u8 String_03E9[] = _("受け入れるんだ、\n暗黒の力を・・・」");
const u8 String_03EA[] = _("<PROC=0>\n<END>");
const u8 String_03EB[] = _("???\n「<NAME>・・・");
const u8 String_03EC[] = _("使うんだ・・・\nヴァンパイアの力、\n暗黒魔法を・・・");
const u8 String_03ED[] = _("チェンジ・バットはバット(こ\nうもり)へのチェンジ(変身)魔\n法だ。");
const u8 String_03EE[] = _("バットになれば、");
const u8 String_03EF[] = _("通常は通ることのできない小さ\nな窓を、潜(くぐ)り抜(ぬ)ける\nことができる。");
const u8 String_03F0[] = _("受け入れるんだ、\n暗黒の力を・・・」");
const u8 String_03F1[] = _("<PROC=0>\n<END>");
const u8 String_03F2[] = _("???\n「気をつけるんだ、\n<NAME>・・・");
const u8 String_03F3[] = _("ヴァンパイアは太陽の光と水に\n弱い。水たまりといえども油断\nは禁物・・・");
const u8 String_03F4[] = _("使うんだ・・・\nヴァンパイアの力、\n暗黒魔法を・・・");
const u8 String_03F5[] = _("チェンジ・バットはバット(こ\nうもり)へのチェンジ(変身)魔\n法だ。");
const u8 String_03F6[] = _("バットになれば、通常は通るこ\nとのできない障害物を、飛び越\n(こ)えることができる。");
const u8 String_03F7[] = _("受け入れるんだ、\n暗黒の力を・・・」");
const u8 String_03F8[] = _("<PROC=0>\n<END>");
const u8 String_03F9[] = _("囮(おとり)のつぼみが現れたら\nつぼみの動きに注目し、ドゥラ\nスロ―ルを探し出せ。");
const u8 String_03FA[] = _("チェンジ・バットを使えば、つ\nぼみの中を見通すこともできる");
const u8 String_03FB[] = _("<PROC=0>\n<END>");
const u8 String_03FC[] = _("ドゥラスロ―ルの後を取れば、");
const u8 String_03FD[] = _("チェンジ・ウルフで噛(か)みつ\nき、ライフを奪(うば)い取るこ\nともできる。");
const u8 String_03FE[] = _("<PROC=0>\n<END>");
const u8 String_03FF[] = _("タロット封印により閉ざされて\nいる。");
const u8 String_0400[] = _("<PROC=0>\n<END>");
const u8 String_0401[] = _("3賢者のカ―ドを使った!");
const u8 String_0402[] = _("扉が開いた!!");
const u8 String_0403[] = _("<PROC=0>\n<END>");
const u8 String_0404[] = _("<LABEL=RINGO2>リンゴ</LABEL>\n「さすがは<NAME>。");
const u8 String_0405[] = _("3賢者(けんじゃ)のカ―ドがす\nべてそろったようだな・・・");
const u8 String_0406[] = _("よし、それを使ってタロット封\n印(ふういん)を解くんだ!!」");
const u8 String_0407[] = _("<PROC=0>\n<END>");
const u8 String_0408[] = _("<LABEL=RINGO2>リンゴ</LABEL>\n「残りのカ―ドは1枚・・・");
const u8 String_0409[] = _("あと少しだ、<NAME>!!」");
const u8 String_040A[] = _("<PROC=0>\n<END>");
const u8 String_040B[] = _("<LABEL=RINGO2>リンゴ</LABEL>\n「残りのカ―ドは2枚・・・");
const u8 String_040C[] = _("時間がない!\n急いでくれ、<NAME>!!」");
const u8 String_040D[] = _("<PROC=0>\n<END>");
const u8 String_040E[] = _("<LABEL=RINGO2>リンゴ</LABEL>\n「黒のダ―インはこの扉(とび\nら)の向こうだ。");
const u8 String_040F[] = _("くさびの封印(ふういん)を守る\nためにも、このタロット封印を\n解除しなければ・・・");
const u8 String_0410[] = _("それにはどうしても3賢者(けん\nじゃ)のカ―ドが必要だ」");
const u8 String_0411[] = _("<PROC=0>\n<END>");
const u8 String_0412[] = _("<LABEL=RINGO2>リンゴ</LABEL>\n「いいか、<NAME>。");
const u8 String_0413[] = _("この封印(ふういん)をほどこし\nたのが何者なのかは分からんが");
const u8 String_0414[] = _("3賢者(けんじゃ)のカ―ドは、\n必ずこのサン・ミゲルのどこか\nにあるはずだ。");
const u8 String_0415[] = _("さもなくばカギとしての役割を\n果たせないからな。");
const u8 String_0416[] = _("こんなとき、星読みでもできれ\nば良いのだが・・・」");
const u8 String_0417[] = _("<PROC=0>\n<END>");
const u8 String_0418[] = _("ドヴァリンの弱点は頭だ。");
const u8 String_0419[] = _("腕(うで)を攻撃(こうげき)する\nことでもダメ―ジはあたえられ\nるが、");
const u8 String_041A[] = _("腕に気を取られて、頭を攻撃す\nるチャンスを見逃すことのない\nように注意しろ。");
const u8 String_041B[] = _("<PROC=0>\n<END>");
const u8 String_041C[] = _("ドヴァリンのダ―クブレスや墨\n玉(すみだま)はダ―ク属性だ。");
const u8 String_041D[] = _("黒<NAME>にトランスすれば\nダメ―ジを減らすこともできる");
const u8 String_041E[] = _("<PROC=0>\n<END>");
const u8 String_041F[] = _("月光魔法「ゼロシフト」は、瞬\n間移動を可能にする転移魔法だ");
const u8 String_0420[] = _("移動の際、姿を消している間は\n敵モンスタ―やその攻撃をすり\n抜(ぬ)けることができる。");
const u8 String_0421[] = _("<PROC=0>\n<END>");
const u8 String_0422[] = _("月光魔法「ブラックサン」は、\n暗黒の欠片を呼び出す召喚(し\nょうかん)魔法だ。");
const u8 String_0423[] = _("ブラックサンを使えば、しばら\nくの間、太陽の光を遮断(しゃ\nだん)することができる。");
const u8 String_0424[] = _("<PROC=0>\n<END>");
const u8 String_0425[] = _("像　ら<EXTEND=0>　 マ　\n　に<VAR=1>　スの　に\nブロ　　をお　　");
const u8 String_0426[] = _("<PROC=0>\n<END>");
const u8 String_0427[] = _("　か　　に<VAR=0>　ス\n<EXTEND=1>　 マ　　所　\n　　ック　　け。");
const u8 String_0428[] = _("<PROC=0>\n<END>");
const u8 String_0429[] = _("南");
const u8 String_042A[] = _("北");
const u8 String_042B[] = _("東");
const u8 String_042C[] = _("西");
const u8 String_042D[] = _("壁に何か書いてある。");
const u8 String_042E[] = _("「カギハドコダ?」");
const u8 String_042F[] = _("<PROC=0>\n<END>");
const u8 String_0430[] = _("<LABEL=OTENKO>おてんこさま</LABEL>\n「覚悟(かくご)はいいな?」\n <ALTER>いい</ALTER>　<ALTER>まだ</ALTER>");
const u8 String_0431[] = _("<PROC=0>\n<END>");
const u8 String_0432[] = _("<LABEL=OTENKO>おてんこさま</LABEL>\n「<NAME>、");
const u8 String_0433[] = _("おまえたちにすべてを託(たく)\nして消えていったリンゴのため\nにも・・・");
const u8 String_0434[] = _("この戦い、\n絶対に負けられないぞ!!」");
const u8 String_0435[] = _("<PROC=0>\n<END>");
const u8 String_0436[] = _("<LABEL=OTENKO>おてんこさま</LABEL>\n「銀河意志ダ―ク・・・");
const u8 String_0437[] = _("吸血変異による全生命種のアン\nデッド化のみならず、");
const u8 String_0438[] = _("原種の欠片による種の還元(か\nんげん)までをも謀(はか)ると\nは・・・");
const u8 String_0439[] = _("下手をすると、この星そのもの\nが飲み込(こ)まれてしまうぞ。");
const u8 String_043A[] = _("そこまでして種の進化を・・・\n太陽系の進化を止めなければな\nらないのか・・・?」");
const u8 String_043B[] = _("<PROC=0>\n<END>");
const u8 String_043C[] = _("<LABEL=SABATA>サバタ</LABEL>\n「この俺(おれ)が月下美人にな\nろうとはな・・・");
const u8 String_043D[] = _("我ながら悪い冗談(じょうだん)\nだ。");
const u8 String_043E[] = _("俺の中に慈愛(じあい)の心など\nあるはずもなかろう?");
const u8 String_043F[] = _("もしそんなものがあるとしたら\nそれはカ―ミラの心・・・");
const u8 String_0440[] = _("ダ―クマタ―と共に俺の内にあ\nる彼女(かのじょ)の魂(たまし\nい)だ。");
const u8 String_0441[] = _("彼女の魂こそが、この俺を月下\n美人へと押(お)し上げた・・・");
const u8 String_0442[] = _("俺が殺した嘆(なげ)きの魔女、\nカ―ミラ・・・");
const u8 String_0443[] = _("できることなら・・・\n彼女に人として生と死を取り戻\n(もど)してやりたかった。");
const u8 String_0444[] = _("・・・それは許されぬ夢。\nそれでも、俺は・・・」");
const u8 String_0445[] = _("<PROC=0>\n<END>");
const u8 String_0446[] = _("<LABEL=SABATA>サバタ</LABEL>\n「母を失い、父を倒(たお)し、");
const u8 String_0447[] = _("それでも・・・\n俺(おれ)たちは前に進まなけれ\nばならない。");
const u8 String_0448[] = _("俺たちの戦いに、勝ちはない。\nだが、だからこそ、\n絶対に負けるわけにはいかない");
const u8 String_0449[] = _("あらがい続けること・・・");
const u8 String_044A[] = _("それだけが、銀河意志ダ―クに\n対抗(たいこう)するための唯一\n(ゆいいつ)絶対の手段!!");
const u8 String_044B[] = _("そうだろう、<NAME>?」");
const u8 String_044C[] = _("<PROC=0>\n<END>");
const u8 String_044D[] = _("<LABEL=SABATA>サバタ</LABEL>\n「<NAME>、");
const u8 String_044E[] = _("おまえが地下に向かっている間\nに、ひまわりたちが封印(ふう\nいん)の準備をする。");
const u8 String_044F[] = _("おまえはただひたすら、ヨルム\nンガンドの頭を叩(たた)くこと\nだけを考えるんだ。いいな?」");
const u8 String_0450[] = _("<PROC=0>\n<END>");
const u8 String_0451[] = _("<LABEL=SABATA>サバタ</LABEL>\n「無事、イモ―タルを始末した\nようだな。");
const u8 String_0452[] = _("・・・ヤツは塔の中だ。");
const u8 String_0453[] = _("この螺旋(らせん)の塔は、太陽\nと暗黒、2つの塔からなってい\nる。");
const u8 String_0454[] = _("2つの塔には2つのセキュリティ\nロック。ロック解除に必要なカ\nギも2つだ。");
const u8 String_0455[] = _("それは太陽と暗黒の2つの力。");
const u8 String_0456[] = _("太陽の光から生まれる太陽エネ\nルギ―と、闇(やみ)から生まれ\nる暗黒物質ダ―クマタ―だ。");
const u8 String_0457[] = _("どちらが欠けていても最上階に\nたどり着くことはできない。");
const u8 String_0458[] = _("ダ―インが親父やおまえの身体\nを狙(ねら)ったのもそのためだ");
const u8 String_0459[] = _("もはや太陽の力を失った俺(お\nれ)ではなくな・・・");
const u8 String_045A[] = _("敵同士であるはずの太陽仔(た\nいようし)と暗黒仔が共に守ろ\nうとしたもの。");
const u8 String_045B[] = _("そうまでして守りたいものとは\nいったい何なのか・・・?");
const u8 String_045C[] = _("それが何であれ、そんなものを\nヤツの好きにさせるわけにはい\nかない!");
const u8 String_045D[] = _("<NAME>、\n塔を上りヤツを追うぞ!!」");
const u8 String_045E[] = _("<PROC=0>\n<END>");
const u8 String_045F[] = _("<LABEL=SABATA>サバタ</LABEL>\n「準備はいいな?」\n <ALTER>いい</ALTER>　<ALTER>まだ</ALTER>");
const u8 String_0460[] = _("<PROC=0>\n<END>");
const u8 String_0461[] = _("<LABEL=SABATA>サバタ</LABEL>\n「時間はないぞ!!\n早く準備を済ませるんだ!」");
const u8 String_0462[] = _("<PROC=0>\n<END>");
const u8 String_0463[] = _("<LABEL=SABATA>サバタ</LABEL>\n「よし!");
const u8 String_0464[] = _("まずは俺(おれ)が暗黒チャ―ジ\nを使い、暗黒の扉(とびら)を開\nける。");
const u8 String_0465[] = _("暗黒の扉が開いたら、おまえは\n急いで太陽チャ―ジをし、太陽\nの扉を開けるんだ。");
const u8 String_0466[] = _("いいな、行くぞ!!」");
const u8 String_0467[] = _("<PROC=0>\n<END>");
const u8 String_0468[] = _("<LABEL=SABATA>サバタ</LABEL>\n「何をやっている!!");
const u8 String_0469[] = _("太陽チャ―ジを行うには、\n太陽センサ―に太陽の光を当て\nＡボタンを押(お)すんだ!」");
const u8 String_046A[] = _("<PROC=0>\n<END>");
const u8 String_046B[] = _("<LABEL=SABATA>サバタ</LABEL>\n「時間がない!!");
const u8 String_046C[] = _("暗黒チャ―ジを行うには、");
const u8 String_046D[] = _("太陽センサ―を太陽の光から隠\n(かく)して、Ａボタンを押(お)\nしっぱなしにするんだ!」");
const u8 String_046E[] = _("<PROC=0>\n<END>");
const u8 String_046F[] = _("<LABEL=SABATA>サバタ</LABEL>\n「いいか、<NAME>。");
const u8 String_0470[] = _("この塔では太陽と暗黒、2つの\nル―トを同時に攻略(こうりゃ\nく)しなくては、");
const u8 String_0471[] = _("最上階にたどり着くことはでき\nない。");
const u8 String_0472[] = _("俺は暗黒の塔を行く。\nおまえは太陽の塔を攻略するん\nだ。");
const u8 String_0473[] = _("足を引っ張るなよ?」");
const u8 String_0474[] = _("<PROC=0>\n<END>");
const u8 String_0475[] = _("サバタの声\n「<NAME>!!\n何をやっている!");
const u8 String_0476[] = _("さっさと太陽の塔を上るんだ!\n」");
const u8 String_0477[] = _("<PROC=0>\n<END>");
const u8 String_0478[] = _("サバタの声\n「<NAME>!!\n何をやっている!");
const u8 String_0479[] = _("今は後戻(あともど)りをしてい\nる場合ではないぞ!!」");
const u8 String_047A[] = _("<PROC=0>\n<END>");
const u8 String_047B[] = _("ダ―インの攻撃(こうげき)、ダ\n―クブラストは、エリア全体を\n暗闇(くらやみ)にしてしまう。");
const u8 String_047C[] = _("しかし太陽の光さえあれば、\nその力を弱めることも可能だ。");
const u8 String_047D[] = _("<PROC=0>\n<END>");
const u8 String_047E[] = _("足元からのつかみ攻撃(こうげ\nき)、影(かげ)の腕(うで)に捕\n(つか)まれば、");
const u8 String_047F[] = _("ライフを奪(うば)われ、ダメ―\nジを受けると共にダ―インの暗\n黒ゲ―ジを回復させてしまう。");
const u8 String_0480[] = _("攻撃をやり過ごし、闇の晴れる\nとき、反撃のチャンスを見逃す\nな。");
const u8 String_0481[] = _("<PROC=0>\n<END>");
const u8 String_0482[] = _("<LABEL=DAAIN>黒のダ―イン</LABEL>\n「クッ・・・\nいまいましい身体だ!");
const u8 String_0483[] = _("もうそんなものはいらない!!");
const u8 String_0484[] = _("・・・見るがいい!");
const u8 String_0485[] = _("<PROC=1>真なる暗黒仔(あんこくし)たる\nボクの力!");
const u8 String_0486[] = _("星すらもおおいつくす影(かげ)\nの力を!!」");
const u8 String_0487[] = _("<PROC=0>\n<END>");
const u8 String_0488[] = _("<LABEL=SABATA>サバタ</LABEL>\n「クロのことなら心配ない。");
const u8 String_0489[] = _("この約束の丘には、敵モンスタ\n―も入って来れんようだからな\n」");
const u8 String_048A[] = _("<PROC=0>\n<END>");
const u8 String_048B[] = _("<LABEL=SABATA>サバタ</LABEL>\n「悪いが、アイテムはおまえの\nバッグから使わせてもらう。");
const u8 String_048C[] = _("代わりに俺(おれ)が手に入れた\nアイテムは、おまえのバッグに\n入れておこう。");
const u8 String_048D[] = _("暗黒転移(ワ―プ)の応用だ」");
const u8 String_048E[] = _("<PROC=0>\n<END>");
const u8 String_048F[] = _("<LABEL=KURO_BAN>クロ</LABEL>\n「・・・」");
const u8 String_0490[] = _("<PROC=0>\n<END>");
const u8 String_0491[] = _("<LABEL=OTENKO>おてんこさま</LABEL>\n「どうした、<NAME>?");
const u8 String_0492[] = _("ん?\nその機械は・・・」");
const u8 String_0493[] = _("<LABEL=ROCKMAN>ロックマン</LABEL>\n「あなたは・・・\nおてんこさま!?」");
const u8 String_0494[] = _("<PROC=0>\n<END>");
const u8 String_0495[] = _("<LABEL=OTENKO>おてんこさま</LABEL>\n「そうか、そんなことが・・・");
const u8 String_0496[] = _("<NAME>、");
const u8 String_0497[] = _("おまえはロックマンと協力して\nシェ―ドマンの野望を食い止め\nるんだ。");
const u8 String_0498[] = _("ヨルムンガンドについては、私\nとサバタが監視(かんし)を続け\nよう。");
const u8 String_0499[] = _("今は大人しくしているようだが\n油断はできん」");
const u8 String_049A[] = _("<LABEL=ROCKMAN>ロックマン</LABEL>\n「ありがとう、\nおてんこさま!!」");
const u8 String_049B[] = _("<PROC=0>\n<END>");
const u8 String_049C[] = _("<LABEL=OTENKO>おてんこさま</LABEL>\n「ロックマン、");
const u8 String_049D[] = _("住まう世界は違(ちが)えども、\n共に闇(やみ)と戦う仲間だ。");
const u8 String_049E[] = _("困ったときはえんりょなく言っ\nてくれ。協力はおしまんぞ!」");
const u8 String_049F[] = _("<PROC=0>\n<END>");
const u8 String_04A0[] = _("<LABEL=OTENKO>おてんこさま</LABEL>\n「シェ―ドマン・・・");
const u8 String_04A1[] = _("闇(やみ)の力をあつかう人型プ\nログラム、ダ―クロイドか。");
const u8 String_04A2[] = _("だが、いったいどうやってこの\n世紀末世界に・・・");
const u8 String_04A3[] = _("それに実体を持たないプログラ\nムに、なぜこの世界での活動が\nできるのか?");
const u8 String_04A4[] = _("・・・この事件の裏には、\n何かあるな・・・」");
const u8 String_04A5[] = _("<PROC=0>\n<END>");
const u8 String_04A6[] = _("<LABEL=SABATA>サバタ</LABEL>\n「何をしている?");
const u8 String_04A7[] = _("とっととそのシェ―ドマンとか\nいうプログラムを、デリ―ト(\n消去)してこい。");
const u8 String_04A8[] = _("その間、ヨルムンガンドの方は\n俺(おれ)がおさえてみせる!!」");
const u8 String_04A9[] = _("<PROC=0>\n<END>");
const u8 String_04AA[] = _("<LABEL=SABATA>サバタ</LABEL>\n<PROC=1>「フッ、");
const u8 String_04AB[] = _("こんな状況(じょうきょう)にあ\nってさえ、他人の心配とはな。");
const u8 String_04AC[] = _("おまえもあいつと同じ・・・");
const u8 String_04AD[] = _("まったく、俺(おれ)の周りはい\nつもバカばかりだ・・・」");
const u8 String_04AE[] = _("<PROC=0>\n<END>");
const u8 String_04AF[] = _("<LABEL=ROCKMAN>ロックマン</LABEL>\n「<NAME>くん、");
const u8 String_04B0[] = _("シェ―ドマンの反応はこの塔の\n上みたいだ」");
const u8 String_04B1[] = _("<PROC=0>\n<END>");
const u8 String_04B2[] = _("「キ―デ―タ1」\nを手に入れた!!");
const u8 String_04B3[] = _("<LABEL=ROCKMAN>ロックマン</LABEL>\n「キ―デ―タ・・・");
const u8 String_04B4[] = _("4体のバットが持つ4つのデ―タ\nが、あの扉(とびら)を開けるた\nめのカギというわけか・・・");
const u8 String_04B5[] = _("デ―タはあと3つ。\n残りのシェ―ドバットはどこに\n・・・?」");
const u8 String_04B6[] = _("<PROC=0>\n<END>");
const u8 String_04B7[] = _("「キ―デ―タ2」\nを手に入れた!!");
const u8 String_04B8[] = _("<LABEL=ROCKMAN>ロックマン</LABEL>\n「2つ目のキ―デ―タが手に入\nったね!");
const u8 String_04B9[] = _("残るデ―タはあと2つ。\nがんばって、\n<NAME>くん!!」");
const u8 String_04BA[] = _("<PROC=0>\n<END>");
const u8 String_04BB[] = _("「キ―デ―タ3」\nを手に入れた!!");
const u8 String_04BC[] = _("<LABEL=ROCKMAN>ロックマン</LABEL>\n「これで3つ目!");
const u8 String_04BD[] = _("残るデ―タはあと1つ。\nもう一息だよ、\n<NAME>くん!!」");
const u8 String_04BE[] = _("<PROC=0>\n<END>");
const u8 String_04BF[] = _("「キ―デ―タ4」\nを手に入れた!!");
const u8 String_04C0[] = _("<LABEL=ROCKMAN>ロックマン</LABEL>\n「やったね、<NAME>くん!!");
const u8 String_04C1[] = _("これですべてのデ―タがそろっ\nたよ。");
const u8 String_04C2[] = _("さあ、シェ―ドマンのいる北の\n塔に向かおう!」");
const u8 String_04C3[] = _("<PROC=0>\n<END>");
const u8 String_04C4[] = _("2つの塔に挑(いど)め。");
const u8 String_04C5[] = _("チェンジ魔方陣を利用して、2\nつの塔を同時に攻略(こうりゃ\nく)せよ。");
const u8 String_04C6[] = _("魔方陣の上でＡボタンを押(お)\nせば、操作するキャラクタ―を\n交代することができる。");
const u8 String_04C7[] = _("<PROC=0>\n<END>");
const u8 String_04C8[] = _("た・・・");
const u8 String_04C9[] = _("<PROC=0>\n<END>");
const u8 String_04CA[] = _("たいよ・・・");
const u8 String_04CB[] = _("<PROC=0>\n<END>");
const u8 String_04CC[] = _("太陽・・・");
const u8 String_04CD[] = _("<PROC=0>\n<END>");
const u8 String_04CE[] = _("太陽ぉ・・・");
const u8 String_04CF[] = _("<PROC=0>\n<END>");
const u8 String_04D0[] = _("太陽ぉ―――!");
const u8 String_04D1[] = _("<PROC=0>\n<END>");
const u8 String_04D2[] = _("太陽ぉ―――――――!");
const u8 String_04D3[] = _("<PROC=0>\n<END>");
const u8 String_04D4[] = _("<LABEL=R_DJUNGO><NAME></LABEL>\n「あのとき、");
const u8 String_04D5[] = _("ヨルムンガンドの動きを止めた\n黒い影(かげ)・・・");
const u8 String_04D6[] = _("あれはおとうさんだったのか?");
const u8 String_04D7[] = _("それとも・・・」");
const u8 String_04D8[] = _("<PROC=0>\n<END>");
const u8 String_04D9[] = _("<LABEL=ZAJI>ザジ</LABEL>\n「黒きダ―イン、やったて?」");
const u8 String_04DA[] = _("<LABEL=R_DJUNGO><NAME></LABEL>\n「分からない・・・けど、");
const u8 String_04DB[] = _("光が強ければ、その隣(となり)\nに並び立つ影は、より深い闇(\nやみ)となる。");
const u8 String_04DC[] = _("暗闇は怖(こわ)いけど・・・\nそれでも、\n夕暮れ時には思うんだ。");
const u8 String_04DD[] = _("そんな暗い影があるからこそ、\n世界はこんなにも・・・」");
const u8 String_04DE[] = _("<PROC=0>\n<END>");
const u8 String_04DF[] = _("<LABEL=ZAJI>ザジ</LABEL>\n「そないなことも・・・");
const u8 String_04E0[] = _("・・・あるかも知れへんな」");
