const u8 String_04E7[] = _("<LABEL=RITA>リタ</LABEL>\n「黒きダ―イン、ですか?」");
const u8 String_04E8[] = _("<LABEL=R_DJUNGO><NAME></LABEL>\n「分からない・・・けど、");
const u8 String_04E9[] = _("光が強ければ、その隣(となり)\nに並び立つ影は、より深い闇(\nやみ)となる。");
