const u8 String_0500[] = _("<LABEL=SABATA>サバタ</LABEL>\n「ヤツが・・・?」");
const u8 String_0501[] = _("<LABEL=R_DJUNGO><NAME></LABEL>\n「分からない・・・けど、");
const u8 String_0502[] = _("光が強ければ、その隣(となり)\nに並び立つ影は、より深い闇(\nやみ)となる。");
