const u8 String_0506[] = _("<LABEL=SABATA>サバタ</LABEL>\n<PROC=1>「フッ・・・");
const u8 String_0507[] = _("まったく、\nおまえのお人好しにもほどがあ\nるな・・・」");
const u8 String_0508[] = _("<PROC=0>\n<END>");
