const u8 String_050C[] = _("それとも・・・」");
const u8 String_050D[] = _("<PROC=0>\n<END>");
const u8 String_050E[] = _("<LABEL=LADY>レディ</LABEL>\n「例の・・・\n影のイモ―タル?」");
const u8 String_050F[] = _("<LABEL=R_DJUNGO><NAME></LABEL>\n「分からない・・・けど、");
const u8 String_0510[] = _("光が強ければ、その隣(となり)\nに並び立つ影は、より深い闇(\nやみ)となる。");
const u8 String_0511[] = _("暗闇は怖(こわ)いけど・・・\nそれでも、\n夕暮れ時には思うんだ。");
