const u8 String_0513[] = _("<PROC=0>\n<END>");
const u8 String_0514[] = _("<LABEL=LADY>レディ</LABEL>\n「美しい・・・か。");
const u8 String_0515[] = _("詩人ね、<NAME>くん?」");
const u8 String_0516[] = _("<PROC=0>\n<END>");
const u8 String_0517[] = _("闇(やみ)の力に守られている状\n態では、ヨルムンガンドにダメ\n―ジをあたえることはできない");
const u8 String_0518[] = _("太陽の光を浴びせ、闇の守りを\n追い払(はら)え。");
const u8 String_0519[] = _("<PROC=0>\n<END>");
const u8 String_051A[] = _("ヨルムンガンドの弱点はその舌\nにある。");
const u8 String_051B[] = _("左右の瞳(ひとみ)それぞれを攻\n撃(こうげき)し、口を開かせろ");
const u8 String_051C[] = _("<PROC=0>\n<END>");
const u8 String_051D[] = _("大量のバットを召喚(しょうか\nん)するシェ―ドマンの特殊攻\n撃(とくしゅこうげき)、");
const u8 String_051E[] = _("ウイングスト―ムは、避(よ)け\nることが困難だ。");
const u8 String_051F[] = _("しかし通常攻撃であるレッドウ\nイングの際、召喚されたバット\nを倒(たお)しておけば、");
const u8 String_0520[] = _("ウイングスト―ムで召喚される\nバットの数を、減らすことがで\nきる。");
const u8 String_0521[] = _("<PROC=0>\n<END>");
const u8 String_0522[] = _("ウイングスト―ムを放った後の\nシェ―ドマンには、隙(すき)が\n生まれる。");
const u8 String_0523[] = _("攻撃のチャンスを見逃(みのが)\nすな。");
const u8 String_0524[] = _("<PROC=0>\n<END>");
const u8 String_0525[] = _("<LABEL=SHADEMAN>シェ―ドマン</LABEL>\n「キ、キキ・・・キサマ!!");
const u8 String_0526[] = _("太陽少年が闇(やみ)の力を使う\nとは・・・!?");
const u8 String_0527[] = _("だが、守りを破られたとはいえ\n闇の力、ダ―クマタ―は健在だ");
const u8 String_0528[] = _("ワタシを怒(おこ)らせたこと、\n後悔(こうかい)するぞ!!」");
const u8 String_0529[] = _("<LABEL=ROCKMAN>ロックマン</LABEL>\n「今だ、<NAME>くん!!");
const u8 String_052A[] = _("太陽の力でシェ―ドマンのダ―\nクマタ―を焼却(しょうきゃく)\nするんだ!」");
const u8 String_052B[] = _("<PROC=0>\n<END>");
const u8 String_052C[] = _("ヨルムンガンドの弱点はその舌\nにある。");
const u8 String_052D[] = _("左右の瞳(ひとみ)それぞれを攻\n撃(こうげき)し、口を開かせろ");
const u8 String_052E[] = _("<PROC=0>\n<END>");
const u8 String_052F[] = _("<LABEL=SABATA>サバタ</LABEL>\n「ん?");
const u8 String_0530[] = _("ようやくカンを取り戻したか。\nチャ―ジショットがレベル2に\nなったようだな。");
const u8 String_0531[] = _("いいだろう・・・\nこれを受け取れ」");
const u8 String_0532[] = _("<PROC=0>\n<END>");
const u8 String_0533[] = _("<PROC=1>「ジョ―カ―の紋章」\nを手に入れた!!");
const u8 String_0534[] = _("<PROC=0>\n<END>");
const u8 String_0535[] = _("<LABEL=SABATA>サバタ</LABEL>\n「そのジョ―カ―の紋章(もん\nしょう)を持つ者は、");
const u8 String_0536[] = _("ガンタイプの武器を使うとき、\nチャ―ジショットのタメ時間を\n半分にすることができる。");
const u8 String_0537[] = _("チャ―ジショットは、");
const u8 String_0538[] = _("エナジ―の消費量はそのままに\nショットの攻撃力を高めること\nのできる攻撃だ。");
const u8 String_0539[] = _("それを使いこなせずして、ガン\nマスタ―とは呼べんぞ?」");
const u8 String_053A[] = _("<PROC=0>\n<END>");
const u8 String_053B[] = _("いらっしゃいませ!");
const u8 String_053C[] = _("ご利用になられますか?");
const u8 String_053D[] = _("<WEIGHT>✚ボタン</WEIGHT>の左右で、太陽エネル\nギ―の移し替えができます。");
const u8 String_053E[] = _("ありがとうございました!");
const u8 String_053F[] = _("    ソル✕(1+利息: )\n=    ソル借ります。");
const u8 String_0540[] = _("返済は<VAR=0>日後、太陽バンクから\nの<WEIGHT>自動引き落し</WEIGHT>となります。");
const u8 String_0541[] = _("限度ソルを超えるので、\nこれ以上お貸しできません。");
const u8 String_0542[] = _("ご利用内容を選択してください");
const u8 String_0543[] = _("暗黒ロ―ンに<WEIGHT><VAR=0>ソル</WEIGHT>借りて\nやり直しますか?");
const u8 String_0544[] = _("今度はきちんと返済してくださ\nいね、<NAME>さん。");
const u8 String_0545[] = _("本当に大丈夫なんですか?\n<NAME>さん・・・");
const u8 String_0546[] = _("本当に好きなんですね?\n走るの・・・");
const u8 String_0547[] = _("<NAME>さん・・・");
