const u8 String_054B[] = _("<PROC=1><LABEL=NONE>???</LABEL>\n「<PROC=7><LOCK=48>いらっしゃいませ!!\n<PROC=5>暗黒ロ―ンにようこそ!」");
const u8 String_054C[] = _("<PROC=4><LABEL=NONE>???</LABEL>\n「わたしは太陽バンク受付の陽\n子です」<LOCK=30>");
const u8 String_054D[] = _("<PROC=2><PROC=3><LABEL=NONE>???</LABEL>\n「暗黒ロ―ン受付の暗子です」<LOCK=30>");
const u8 String_054E[] = _("<PROC=1><LABEL=NONE>陽子ちゃんと暗子ちゃん</LABEL>\n「ここでは私たち2人が、");
const u8 String_054F[] = _("太陽バンクと暗黒ロ―ンについ\nて説明いたします。<PROC=5><PROC=6>よろしくお\nつきあいくださいね♪」");
const u8 String_0550[] = _("<PROC=0>\n<END>");
const u8 String_0551[] = _("バンクとロ―ンについて\n <ALTER>太陽スタンド</ALTER>　<ALTER>太陽バンク</ALTER>\n <ALTER>暗黒ロ―ン</ALTER>　　<ALTER>暗黒カ―ド</ALTER>");
const u8 String_0552[] = _("<PROC=0>\n<END>");
const u8 String_0553[] = _("<LABEL=NONE>太陽バンクの陽子ちゃん</LABEL><PROC=2>\n「それでは、わたしから説明さ\nせていただきます!");
const u8 String_0554[] = _("<PROC=4>右側にあります緑色の機械、\nこれが太陽スタンドです。");
const u8 String_0555[] = _("太陽センサ―がキャッチした太\n陽の光を、自動的に貯めておい\nてくれる魔法機械、");
const u8 String_0556[] = _("それが太陽スタンドです。");
const u8 String_0557[] = _("スタンドに貯まった太陽エネル\nギ―は、スタンドの前でＡボタ\nンを押(お)すことにより、");
const u8 String_0558[] = _("エナジ―(ENE)としてチャ―ジ\nすることができます。");
const u8 String_0559[] = _("夜間でもチャ―ジすることがで\nきますので、昼間の内に太陽の\n光を集めておくのが吉(きち)♪<PROC=2>");
const u8 String_055A[] = _("太陽スタンドはダンジョンの各\n所に設置されておりますので、\n有効にご活用ください」");
const u8 String_055B[] = _("<PROC=0>\n<END>");
const u8 String_055C[] = _("<LABEL=NONE>太陽バンクの陽子ちゃん</LABEL><PROC=2>\n「それでは、わたしから説明さ\nせていただきます!");
const u8 String_055D[] = _("<PROC=4>太陽バンクには太陽スタンドに\n貯めたエネルギ―を、");
const u8 String_055E[] = _("通貨、ソル(SOL)として預けて\nおくことができます。");
const u8 String_055F[] = _("バンクに預けられたソルは、お\n金として商店街でのショッピン\nグにご利用いただけます。<PROC=2>");
const u8 String_0560[] = _("ソルには利息も付きますので、");
const u8 String_0561[] = _("余分な太陽エネルギ―はバンク\nに預けておくのが吉、ですよ♪\n」");
const u8 String_0562[] = _("<PROC=0>\n<END>");
const u8 String_0563[] = _("<LABEL=NONE>暗黒ロ―ンの暗子ちゃん</LABEL><PROC=1>\n「それでは、わたしから説明さ\nせていただきます!");
const u8 String_0564[] = _("<PROC=3>暗黒ロ―ンでは、太陽エネルギ\n―をエナジ―としてお貸しして\nいます。");
const u8 String_0565[] = _("24時間いつでもエナジ―をチャ\n―ジできます。便利ですね♪");
const u8 String_0566[] = _("ただし、借りたモノは返すのが\n世の中のル―ル。");
const u8 String_0567[] = _("お貸ししたエネルギ―は3日後\nソルとして太陽バンクから引き\n落とさせていただきます。");
const u8 String_0568[] = _("残高が足りない場合は、さらに\n太陽スタンドから引き落とさせ\nていただきますが、");
const u8 String_0569[] = _("それでも足りない場合は・・・<PROC=1>");
const u8 String_056A[] = _("とっても大変なことになります\n楽しみですね♪」");
const u8 String_056B[] = _("<PROC=0>\n<END>");
const u8 String_056C[] = _("<LABEL=NONE>暗黒ロ―ンの暗子ちゃん</LABEL><PROC=1>\n「それでは、わたしから説明さ\nせていただきます!");
const u8 String_056D[] = _("<PROC=3>暗黒ロ―ンのゴ―ルドカ―ド、\n暗黒カ―ドには、2つのサ―ビ\nス機能が付いています。");
const u8 String_056E[] = _("1つは暗黒ロ―ンの呼び出しサ\n―ビス。");
const u8 String_056F[] = _("これを使えばいつでもどこでも\n暗黒ロ―ンをご利用いただけま\nす。便利ですね♪");
const u8 String_0570[] = _("もう1つはゴ―ルド会員限定の\nやり直しサ―ビス。");
const u8 String_0571[] = _("ダンジョンの中で思わぬ失敗を\nしてしまった!");
const u8 String_0572[] = _("そんなときに便利なのが、この\nやり直しサ―ビスです。");
const u8 String_0573[] = _("やり直しを使えば、ダンジョン\nのそのエリアに入ったところか\nら、");
const u8 String_0574[] = _("冒険(ぼうけん)をやり直すこと\nができます。");
const u8 String_0575[] = _("ただし、やり直しには相応の費\n用がかかります。<PROC=1>");
const u8 String_0576[] = _("かかった費用は3日後、太陽バ\nンクから引き落とさせていただ\nきます。楽しみですね♪」");
const u8 String_0577[] = _("<PROC=0>\n<END>");
const u8 String_0578[] = _("<LABEL=NONE>???</LABEL>\n「あっ、<NAME>さま!!");
const u8 String_0579[] = _("暗子ちゃん!!\n<NAME>さまだよ!」");
