const u8 String_0598[] = _("くろねこならあっちだ");
const u8 String_0599[] = _("<PROC=0>");
const u8 String_059A[] = _("マラソン");
const u8 String_059B[] = _("<PROC=0>");
const u8 String_059C[] = _("ちゃうねん");
const u8 String_059D[] = _("<PROC=0>");

const u8 String_059E[] = _("太陽鍛冶について\n <ALTER>太陽鍛冶とは</ALTER>　<ALTER>鍛冶の内容</ALTER>\n <ALTER>材料の選択</ALTER>　　<ALTER>鍛冶の手順</ALTER>");
const u8 String_059F[] = _("<PROC=0>\n<END>");
const u8 String_05A0[] = _("太陽鍛冶(たいようかじ)とは、");
const u8 String_05A1[] = _("太陽の力を利用した鍛冶(熱し\nた金属を打ちきたえて物を作る\nこと)である。");
const u8 String_05A2[] = _("<PROC=0>\n<END>");
const u8 String_05A3[] = _("太陽鍛冶(たいようかじ)では、");
const u8 String_05A4[] = _("材料となる2つの武器から、新\nしい武器を1つ作り出すことが\nできる。");
const u8 String_05A5[] = _("無料で何度でも行なうことがで\nきるが、材料となる武器は自分\nで用意しなければならない。");
const u8 String_05A6[] = _("<PROC=0>\n<END>");
const u8 String_05A7[] = _("鍛冶(かじ)を行なうにはまず、");
const u8 String_05A8[] = _("持っている武器の中から、材料\nにする武器を2つ選ばなければ\nならない。");
const u8 String_05A9[] = _("装備中の武器や倉庫に預けてあ\nる武器は、選択(せんたく)する\nことができないので要注意。");
const u8 String_05AA[] = _("また、材料にした武器は元には\n戻(もど)らない。よく考えてか\nら決定すること。");
const u8 String_05AB[] = _("<PROC=0>\n<END>");
const u8 String_05AC[] = _("<END>");
const u8 String_05AD[] = _("武器について\n <ALTER>鍛冶</ALTER>　<ALTER>クオリティ</ALTER>\n <ALTER>継承</ALTER>　<ALTER>レベル</ALTER>");
const u8 String_05AE[] = _("<PROC=0>\n<END>");
const u8 String_05AF[] = _("太陽鍛冶(たいようかじ)におい\nては、");
const u8 String_05B0[] = _("通常、同じ組み合わせの材料か\nらは同じ武器が作られる。");
const u8 String_05B1[] = _("ただし同じ名前の武器であって\nも、鍛冶の出来しだいでその能\n力は大きく異なる。");
const u8 String_05B2[] = _("<PROC=0>\n<END>");
const u8 String_05B3[] = _("鍛冶(かじ)による武器の出来の\n良さ、すなわちクオリティは、");
const u8 String_05B4[] = _("武器の名前の後に付く記号で表\nされる。");
const u8 String_05B5[] = _("たとえば+2は、通常のものより\n威力(いりょく)が2高いことを\n表し、-2は2低いことを表す。");
const u8 String_05B6[] = _("また武器の中には、鍛冶によっ\nて特殊効果(とくしゅこうか)の\n付くものもあり、");
const u8 String_05B7[] = _("特殊効果の付いた武器には、名\n前の後にSP(スペシャル)が付く");
const u8 String_05B8[] = _("<PROC=0>\n<END>");
const u8 String_05B9[] = _("特殊効果(とくしゅこうか)は通\n常、1つの武器に1つしか付かな\nいが、");
const u8 String_05BA[] = _("特殊効果の付いた武器を材料に\n鍛冶(かじ)を行なうと、");
const u8 String_05BB[] = _("特殊効果が出来上がった武器に\n受け継(つ)がれることがある。");
const u8 String_05BC[] = _("これをSPの継承(けいしょう)と\nいい、");
const u8 String_05BD[] = _("これによって、複数の特殊効果\nを持った武器が作られることが\nある。");
const u8 String_05BE[] = _("またSPと同様に、+-といった武\n器の威力(いりょく)が継承され\nることもある。");
const u8 String_05BF[] = _("<PROC=0>\n<END>");
const u8 String_05C0[] = _("武器にはそれぞれにレベルが設\n定されている。");
const u8 String_05C1[] = _("自分のレベルよりレベルの高い\n武器は、手に入れることはでき\nても装備することはできない。");
const u8 String_05C2[] = _("<PROC=0>\n<END>");
const u8 String_05C3[] = _("<END>");
const u8 String_05C4[] = _("<LABEL=OTENKO>おてんこさま</LABEL>\n「これは・・・");
const u8 String_05C5[] = _("太陽樹が運び去られた跡(あと)\n・・・まさに大地の傷跡だな。");
const u8 String_05C6[] = _("世界を支える生命の社(やしろ)\nたる太陽樹は、");
const u8 String_05C7[] = _("太陽の光をエネルギ―に大地を\n浄化(じょうか)する力を秘めて\nいる。");
const u8 String_05C8[] = _("死の都イストラカンに取り込(\nこ)まれた太陽樹は、");
const u8 String_05C9[] = _("大地の巫女(みこ)リタの協力に\nより復活を果たし、");
const u8 String_05CA[] = _("彼(か)の地は浄化(じょうか)さ\nれた。");
const u8 String_05CB[] = _("だがこのサン・ミゲルは・・・\nこの街にはそれをさまたげる何\nかがある。");
const u8 String_05CC[] = _("それを突(つ)き止めない限り、\nこの太陽の街を救うことはでき\nない・・・」");
const u8 String_05CD[] = _("<PROC=0>\n<END>");
const u8 String_05CE[] = _("<LABEL=OTENKO>おてんこさま</LABEL>\n「さあ、");
const u8 String_05CF[] = _("棺桶(かんおけ)をパイルドライ\nバ―の真ん中にセットするんだ\n!!」");
const u8 String_05D0[] = _("<PROC=0>\n<END>");
const u8 String_05D1[] = _("<LABEL=OTENKO>おてんこさま</LABEL>\n「よし!!");
const u8 String_05D2[] = _("4つのジェネレ―タ―を、エン\nチャント攻撃(こうげき)によっ\nてセッティングするんだ。");
const u8 String_05D3[] = _("このジェネレ―タ―は、父なる\n太陽と母なる大地の恩恵(おん\nけい)を受け、");
const u8 String_05D4[] = _("太陽エネルギ―を増幅(ぞうふ\nく)してくれる。");
const u8 String_05D5[] = _("イモ―タルの浄化(じょうか)は\nこのパイルドライバ―をもって\nのみ可能なのだ!!」");
const u8 String_05D6[] = _("<PROC=0>\n<END>");
const u8 String_05D7[] = _("<LABEL=OTENKO>おてんこさま</LABEL>\n「準備完了(じゅんびかんりょ\nう)!!」");
const u8 String_05D8[] = _("<PROC=0>\n<END>");
const u8 String_05D9[] = _("<LABEL=OTENKO>おてんこさま</LABEL>\n「いいか、<NAME>。");
const u8 String_05DA[] = _("パイルドライバ―の起動には太\n陽の光が必要だ。");
const u8 String_05DB[] = _("太陽は出ているな?」");
const u8 String_05DC[] = _("<PROC=0>\n<END>");
const u8 String_05DD[] = _(" <ALTER>出ている</ALTER>　<ALTER>出ていない</ALTER>");
const u8 String_05DE[] = _("<PROC=0>\n<END>");
const u8 String_05DF[] = _("<LABEL=OTENKO>おてんこさま</LABEL>\n「よし!!\n太陽センサ―に太陽の光を当て");
const u8 String_05E0[] = _("白く光った紋章(もんしょう)の\n上でＡボタンを押(お)せば、パ\nイルドライバ―が起動する!」");
const u8 String_05E1[] = _("<PROC=0>\n<END>");
const u8 String_05E2[] = _("<LABEL=OTENKO>おてんこさま</LABEL>\n「ううむ・・・");
const u8 String_05E3[] = _("それではイモ―タルを浄化(じ\nょうか)することはできない。");
const u8 String_05E4[] = _("パイルドライバ―の起動には太\n陽の光が必要だ。太陽の光が得\nられる時間に出直すんだ。");
const u8 String_05E5[] = _("太陽街の外、フィ―ルドに出て\n新たなダンジョンの探索(たん\nさく)をするか、");
const u8 String_05E6[] = _("いったん冒険(ぼうけん)を中断\nし、太陽が出るのを待つしかな\nい・・・」");
