const u8 String_05E8[] = _("<LABEL=OTENKO>おてんこさま</LABEL>\n「ん?");
const u8 String_05E9[] = _("太陽だ!!\nパイルドライバ―を起動するに\nは太陽の光が必要だ!");
const u8 String_05EA[] = _("太陽センサ―に太陽の光を当て\nるんだ!!」");
