const u8 String_05F0[] = _("<LABEL=B_DJUNGO><NAME></LABEL>\n「太陽ぉ――――――!!」");
const u8 String_05F1[] = _("<PROC=0>\n<END>");
const u8 String_05F2[] = _("<LABEL=OTENKO>おてんこさま</LABEL>\n「バトルドライブ開始!!");
const u8 String_05F3[] = _("ジェネレ―タ―から発射される\n太陽パイルで、イモ―タルを浄\n化(じょうか)するんだ!");
const u8 String_05F4[] = _("太陽センサ―がキャッチした太\n陽の光が強ければ強いほど、\nパイルのパワ―も上がるぞ。");
