const u8 String_05F9[] = _("<PROC=0>\n<END>");
const u8 String_05FA[] = _("<LABEL=ZAJI>ザジ</LABEL>\n「サバタ、ええか?");
const u8 String_05FB[] = _("エクトプラズムを棺桶(かんお\nけ)に押(お)し戻(もど)して、\n<NAME>をおさえるんや。");
