const u8 String_05FD[] = _("あんたの身体も長くはもたへん\n時間との勝負や、ええな?」");
const u8 String_05FE[] = _("<PROC=0>\n<END>");
const u8 String_05FF[] = _("<LABEL=OTENKO>おてんこさま</LABEL>\n「いかん!!\nイモ―タルが逃(に)げるぞ!");
const u8 String_0600[] = _("急いで棺桶をパイルドライバ―\nの中央にセットし直すんだ。");
