const u8 String_06F8[] = _("<LABEL=NONE>???</LABEL>\n「キミは誰(だれ)・・・?");
const u8 String_06F9[] = _("ここは時の家・・・\n現在と過去が折(お)り重なった\n時空のひずみ・・・");
