const u8 String_06FD[] = _("<PROC=0>\n<END>");
const u8 String_06FE[] = _("壊(こわ)せ!!");
const u8 String_06FF[] = _("このような傷んだ壁(かべ)は、\nダイナマイトを使っての破壊(\nはかい)が可能だ。");
const u8 String_0700[] = _("壊せる壁は、叩(たた)いたとき\nの音が普通(ふつう)とは違(ち\nが)う。");
const u8 String_0701[] = _("あやしい場所は壁叩きでチェッ\nクせよ。");
const u8 String_0702[] = _("<PROC=0>\n<END>");
const u8 String_0703[] = _("時を越(こ)えろ。");
const u8 String_0704[] = _("タイム魔方陣は時空のひずみの\n特異点。現在と過去を結ぶ時の\n扉(とびら)だ。");
const u8 String_0705[] = _("魔方陣の上でＡボタンを押(お)\nせば、現在と過去を行き来する\nことができる。");
