const u8 String_0726[] = _("扉はかたく閉ざされている。");
const u8 String_0727[] = _("<PROC=0>\n<END>");
const u8 String_0728[] = _("<LABEL=NONE>幽霊少年</LABEL>\n「パパは現在の家の中にいるは\nずなんだ・・・");
const u8 String_0729[] = _("パパ、\n大丈夫(だいじょうぶ)かな?」");
const u8 String_072A[] = _("<PROC=0>\n<END>");
const u8 String_072B[] = _("<LABEL=NONE>幽霊少年</LABEL>\n「ゴ―ストたちがキミの邪魔(\nじゃま)をするかもしれない。");
const u8 String_072C[] = _("くれぐれも注意してね」");
const u8 String_072D[] = _("<PROC=0>\n<END>");
const u8 String_072E[] = _("夢幻のすべてを乗り越えた!!");
const u8 String_072F[] = _("夢幻街(むげんがい)の成長はこ\nこまでだが・・・");
const u8 String_0730[] = _("財宝を求める者は、さらなる挑\n戦(ちょうせん)を続けよ。");
const u8 String_0731[] = _("<PROC=0>\n<END>");
const u8 String_0732[] = _("\n　　　夢幻街：レベル<VAR=0>　　　");
const u8 String_0733[] = _("<PROC=0>\n<END>");
const u8 String_0734[] = _("夢幻の心得・その1");
const u8 String_0735[] = _("夢幻街(むげんがい)とは、\n世紀末現象が生み出した、夢と\n幻(まぼろし)の街である。");
const u8 String_0736[] = _("そこに住むのは、現実世界での\n限界を突破(とっぱ)した、ナイ\nトメア・モンスタ―・・・");
const u8 String_0737[] = _("その力は、現実をはるかに超(\nこ)える。");
const u8 String_0738[] = _("<PROC=0>\n<END>");
const u8 String_0739[] = _("夢幻の心得・その2");
const u8 String_073A[] = _("上の階層への青い扉のカギは、\n重量スイッチにより隠(かく)さ\nれている。");
const u8 String_073B[] = _("ただしここでの重量スイッチは\n起動するまで何が起こるかわか\nらない、トラップパネルだ。");
const u8 String_073C[] = _("冒険者(ぼうけんしゃ)を助ける\nパネルもあれば、苦しめるパネ\nルもある。");
const u8 String_073D[] = _("危険を回避(かいひ)したければ\n敵モンスタ―にパネルを踏(ふ)\nませ、その効果を確認せよ。");
const u8 String_073E[] = _("カギを見つけ出し、最終階層を\n目指せ。");
const u8 String_073F[] = _("<PROC=0>\n<END>");
const u8 String_0740[] = _("夢幻の心得・その3");
const u8 String_0741[] = _("夢幻街(むげんがい)では、その\n中でセ―ブすることはできない");
const u8 String_0742[] = _("最終階層から生還(せいかん)し\nて初めて、そこでの経験を現実\nのものとすることができる。");
const u8 String_0743[] = _("コンティニュ―しても、入口に\n戻されてしまうので注意せよ。");
const u8 String_0744[] = _("<PROC=0>\n<END>");
const u8 String_0745[] = _("夢幻の心得・その4");
const u8 String_0746[] = _("最終階層にたどり着き、試練を\n乗り越(こ)えるたびに、");
const u8 String_0747[] = _("夢幻街(むげんがい)は成長し、\nレベルをアップする。");
const u8 String_0748[] = _("夢幻を育て上げ、\n財宝を手に入れよ。");
const u8 String_0749[] = _("<PROC=0>\n<END>");
const u8 String_074A[] = _("財宝を発見した!!");
const u8 String_074B[] = _("<PROC=0>\n<END>");
const u8 String_074C[] = _("<LABEL=NONE>???</LABEL>\n「さすがはあいつの忘れ形見\n・・・");
const u8 String_074D[] = _("兄貴の方は母親似やけど、\nあんたは父親似やな。\nほんまよう似とるわ・・・");
const u8 String_074E[] = _("あんたらやったら、未来を変え\nていけるかもしれへん・・・");
const u8 String_074F[] = _("うちの星読みもムダにならへん\nかったんやね・・・");
const u8 String_0750[] = _("・・・したら、\n後は任せたで・・・");
const u8 String_0751[] = _("あの娘のことも、\nこの世界のこともな・・・");
const u8 String_0752[] = _("こっからこの世界がどうなって\n行くんか・・・\nほんま・楽しみ・・や・・・」");
const u8 String_0753[] = _("<PROC=0>\n<END>");
const u8 String_0754[] = _("依頼の実行を中止しますか?\n <ALTER>はい</ALTER>　<ALTER>いいえ</ALTER>");
const u8 String_0755[] = _("四方封印により閉ざされている");
const u8 String_0756[] = _("すでに3つの封印が解かれてい\nる・・・");
const u8 String_0757[] = _("<PROC=0>\n<END>");
const u8 String_0758[] = _("1");
const u8 String_0759[] = _("2");
const u8 String_075A[] = _("3");
const u8 String_075B[] = _("<LABEL=SABATA>サバタ</LABEL>\n「<NAME>、\nイモ―タルの始末はどうした?");
const u8 String_075C[] = _("さっさとあのドヴァリンとかい\nうイモ―タルを浄化(じょうか)\nするんだ!!");
const u8 String_075D[] = _("話はそれからだ」");
const u8 String_075E[] = _("<PROC=0>\n<END>");
const u8 String_075F[] = _("<LABEL=SABATA>サバタ</LABEL>\n「クロなら無事だ。\nこの先で休ませている」");
const u8 String_0760[] = _("<PROC=0>\n<END>");
const u8 String_0761[] = _("<LABEL=OTENKO>おてんこさま</LABEL>\n「外に出たようだな・・・");
const u8 String_0762[] = _("<PROC=0>\n<END>");
const u8 String_0763[] = _("いいか、<NAME>。\nエナジ―を回復するには太陽の\n光が必要だが、");
const u8 String_0764[] = _("強すぎる光を浴び続けたり、\n長時間、太陽の光を浴び続けて\nいると、");
const u8 String_0765[] = _("ソル・デ・バイスはもちろん、\nおまえ自身もオ―バ―ヒ―トを\nしてしまう。");
const u8 String_0766[] = _("オ―バ―ヒ―トで倒(たお)れれ\nば、当然、冒険(ぼうけん)を続\nけることはできない。");
const u8 String_0767[] = _("太陽ゲ―ジの上にオ―バ―ヒ―\nトの警告が表示されたら、");
const u8 String_0768[] = _("日陰(ひかげ)に入り、冒険を中\n断して休憩(きゅうけい)を取る\nんだ。いいな?」");
const u8 String_0769[] = _("<PROC=0>\n<END>");
const u8 String_076A[] = _("<LABEL=OTENKO>おてんこさま</LABEL>\n「逃(に)げるのか!?");
const u8 String_076B[] = _("太陽銃(たいようじゅう)を失っ\nたおまえの不安は分かる・・・");
const u8 String_076C[] = _("だがおまえが太陽少年足り得る\nのは、ただ単に太陽銃をあつか\nえるからではないぞ。");
const u8 String_076D[] = _("私は信じている・・・\nおまえの中に宿る血と魂(たま\nしい)を」");
const u8 String_076E[] = _("<PROC=0>\n<END>");
const u8 String_076F[] = _("<LABEL=OTENKO>おてんこさま</LABEL>\n「何という自己再生能力だ!!");
const u8 String_0770[] = _("このような植物は自然界にはあ\nりえない。これも吸血変異の影\n響(えいきょう)なのか?");
const u8 String_0771[] = _("どちらにせよ今の我々にこの植\n物、暗黒の根を倒(たお)すこと\nはできないな・・・」");
const u8 String_0772[] = _("<PROC=0>\n<END>");
const u8 String_0773[] = _("<LABEL=OTENKO>おてんこさま</LABEL>\n「これは・・・");
const u8 String_0774[] = _("この街のいたるところに根を出\nしているあの植物、暗黒の根の\n破壊跡(はかいあと)か。");
const u8 String_0775[] = _("これはダ―ク属性、暗黒の力に\nよるもの・・・");
const u8 String_0776[] = _("ひまわり娘(むすめ)の言ってい\nた遺跡(いせき)はこの先だな」");
const u8 String_0777[] = _("<PROC=0>\n<END>");

const u8 String_0778[] = _("閉ざされている。\nまだ、この扉を開けることはで\nきないようだ・・・");
const u8 String_0779[] = _("<PROC=0>\n<END>");
const u8 String_077A[] = _("どのランクに挑みますか?\n <ALTER><EXTEND=0>ブロンズ</ALTER> ");
const u8 String_077B[] = _("どのランクに挑みますか?\n <ALTER><EXTEND=0>ブロンズ</ALTER>　<ALTER><EXTEND=1>シルバ―</ALTER>");
const u8 String_077C[] = _("どのランクに挑みますか?\n <ALTER><EXTEND=0>ブロンズ</ALTER>　<ALTER><EXTEND=1>シルバ―</ALTER>\n <ALTER><EXTEND=2>ゴ―ルド</ALTER>");
const u8 String_077D[] = _("どのランクに挑みますか?\n <ALTER><EXTEND=0>ブロンズ</ALTER>　<ALTER><EXTEND=1>シルバ―</ALTER>\n <ALTER><EXTEND=2>ゴ―ルド</ALTER>　<ALTER><EXTEND=3>プラチナ</ALTER>");
const u8 String_077E[] = _("ブロンズ");
const u8 String_077F[] = _("シルバ―");
