const u8 String_0782[] = _("★");
const u8 String_0783[] = _("");
const u8 String_0784[] = _("<EXTEND=0>に挑みます。");
const u8 String_0785[] = _("<PROC=0>\n<END>");
const u8 String_0786[] = _("<LABEL=OTENKO>おてんこさま</LABEL>\n「ここは・・・");
const u8 String_0787[] = _("感じるか?\nアンデッドの気配を・・・");
const u8 String_0788[] = _("これではもはや街とは呼べない\nそう、ここはまさにアンデッド\nダンジョン。");
const u8 String_0789[] = _("アンデッドダンジョンではそこ\nに足を踏(ふ)み込(こ)むたびに");
const u8 String_078A[] = _("仕掛(しか)けも敵モンスタ―も\nすべてが元の状態に戻(もど)っ\nてしまう。");
const u8 String_078B[] = _("<PROC=0>\n<END>");
const u8 String_078C[] = _("<LABEL=OTENKO></LABEL>これも世紀末現象の成せる業。\n気を抜(ぬ)くんじゃないぞ、\n<NAME>!!」");
const u8 String_078D[] = _("<PROC=0>\n<END>");
const u8 String_078E[] = _("<LABEL=NONE>???</LABEL>\n「<NAME>、\nこんなところで寄り道かい?");
const u8 String_078F[] = _("それもまあいいさ。\nここでアンデッドと遊ぶのもね");
const u8 String_0790[] = _("このようなアンデッドダンジョ\nンでは、そこに足を踏(ふ)み込\n(こ)むたびに、");
const u8 String_0791[] = _("仕掛(しか)けも敵モンスタ―も\nすべてが元の状態に戻(もど)っ\nてしまう。");
