const u8 String_0793[] = _("<PROC=0>\n<END>");
const u8 String_0794[] = _("<LABEL=NONE>???</LABEL>\n「<NAME>・・・");
const u8 String_0795[] = _("そこはアンデッドダンジョンだ\n・・・");
const u8 String_0796[] = _("アンデッドダンジョンではそこ\nに足を踏(ふ)み込(こ)むたびに");
