const u8 String_079A[] = _("<LABEL=OTENKO>おてんこさま</LABEL>\nおい!ホニャララ!");
const u8 String_079B[] = _("ナントカをアレして\nアレコレするんだ!");
const u8 String_079C[] = _("<PROC=0>\n<END>");
