const u8 String_079E[] = _("やっぱり、\nナントカをソレして");
const u8 String_079F[] = _("イイカンジに\nアレコレするんだ!{MEOW6}");
const u8 String_07A0[] = _("<PROC=0>\n<END>");

const u8 String_07A1[] = _("<LABEL=ZAJI>魔法少女</LABEL>\n「無事来よったな。\nくさっても太陽少年や。");
const u8 String_07A2[] = _("そや、\nソル・デバのレンタル料、\n太陽バンクに頼(たの)むで。");
const u8 String_07A3[] = _("そやなぁ、\n100万ぽっきりでええわ。");
const u8 String_07A4[] = _("何?\n金がないやて?");
const u8 String_07A5[] = _("ほんましょうのないやっちゃな\nぁ・・・");
const u8 String_07A6[] = _("あんたにはコレが必要やな。\nコレあったらいつでもエナジ―\n借りれんねんよ。");
const u8 String_07A7[] = _("ただし借りたもんは返さんなら\nんから注意しぃや?\nご利用は計画的に、や。");
const u8 String_07A8[] = _("<PROC=0>\n<END>");
const u8 String_07A9[] = _("<LABEL=ZAJI></LABEL>くわしいことは、そこにある暗\n黒ロ―ンで聞いといてな」");
const u8 String_07AA[] = _("<PROC=0>\n<END>");
const u8 String_07AB[] = _("<PROC=1>「暗黒カ―ド」\nを手に入れた!!");
const u8 String_07AC[] = _("<PROC=0>\n<END>");
const u8 String_07AD[] = _("<LABEL=OTENKO>おてんこさま</LABEL>\n「なつかしいその言葉使い\n・・・");
const u8 String_07AE[] = _("おまえはもしや・・・\nひまわり娘(むすめ)?」");
const u8 String_07AF[] = _("<LABEL=ZAJI>魔法少女</LABEL>\n「太陽の使者、おてんこさまで\nすね?");
const u8 String_07B0[] = _("お初にお目にかかります。\nうちは星読みのザジいいます。");
const u8 String_07B1[] = _("ひまわり娘ちゅうのは確かうち\nのば・・・師匠(ししょう)の若\nいころの2つ名。");
const u8 String_07B2[] = _("あのば・・・いえ師匠の娘時代\nやなんて想像もできませんけど");
const u8 String_07B3[] = _("かつては最強のヴァンパイアハ\nンタ―、紅のリンゴと共に世界\nを救ったとか。");
const u8 String_07B4[] = _("うちは師匠の星読みに従いこの\n街に来ました。世紀末の終わり\nを見届けるために・・・」");
const u8 String_07B5[] = _("<PROC=0>\n<END>");
const u8 String_07B6[] = _("<LABEL=OTENKO>おてんこさま</LABEL>\n「世紀末の終わり・・・");
const u8 String_07B7[] = _("彼女(かのじょ)がそう言ったの\nか?」");
const u8 String_07B8[] = _("<PROC=0>\n<END>");
const u8 String_07B9[] = _("<LABEL=ZAJI>ザジ</LABEL>\n「はい・・・」");
const u8 String_07BA[] = _("<PROC=0>\n<END>");
const u8 String_07BB[] = _("<LABEL=OTENKO>おてんこさま</LABEL>\n「ううむ・・・");
const u8 String_07BC[] = _("あのヴァンパイアといい・・・\nいったいこの街で何が起きよう\nとしているのだ?");
const u8 String_07BD[] = _("深き影(かげ)とは・・・?」");
const u8 String_07BE[] = _("<PROC=0>\n<END>");
const u8 String_07BF[] = _("<LABEL=ZAJI>ザジ</LABEL>\n「ところで・・・");
const u8 String_07C0[] = _("あんたを太陽少年と見込(みこ)\nんで頼(たの)みたいことがあん\nねん。");
const u8 String_07C1[] = _("この子スミレちゃん言うんやけ\nど、じいちゃんが何や調べに行\nって帰らへんねんて。");
const u8 String_07C2[] = _("こんなかわいこちゃんを泣かし\nたらあかんやろ?");
const u8 String_07C3[] = _("あんたひとっ走り行って、スミ\nちゃんのじいちゃんを連れ戻(\nもど)してくれへん?」");
const u8 String_07C4[] = _("<LABEL=OTENKO>おてんこさま</LABEL>\n「この子は?");
const u8 String_07C5[] = _("吸血変異に襲(おそ)われたこの\n街で、よく無事でいられたな」");
const u8 String_07C6[] = _("<PROC=0>\n<END>");
const u8 String_07C7[] = _("<LABEL=ZAJI>ザジ</LABEL>\n「この太陽街に張られた結界の\nおかげやと思います。");
const u8 String_07C8[] = _("くわしい事情は、じいちゃんに\n会わんことには分かりませんが");
const u8 String_07C9[] = _("何や言うてもスミちゃんのじい\nちゃん、あの鋼鉄のスミスらし\nいんです」");
const u8 String_07CA[] = _("<LABEL=OTENKO>おてんこさま</LABEL>\n「スミス!!\nスミスが生きているのか!?」");
const u8 String_07CB[] = _("<LABEL=ZAJI>ザジ</LABEL>\n「そうですねん。");
const u8 String_07CC[] = _("そやから何がなんでも彼(かれ)\nを助けなあきません」");
const u8 String_07CD[] = _("<PROC=0>\n<END>");
const u8 String_07CE[] = _("<LABEL=OTENKO>おてんこさま</LABEL>\n「鋼鉄のスミス・・・");
const u8 String_07CF[] = _("かつてはガンマスタ―とも呼ば\nれた天才銃職人(ガンスミス)。");
const u8 String_07D0[] = _("最強のヴァンパイアハンタ―で\nあったおまえの親父、リンゴに\n銃(じゅう)を教えた男だ。");
const u8 String_07D1[] = _("この街の異変の裏に潜(ひそ)む\nもの、彼は何らかのヒントをつ\nかんだに違(ちが)いない」");
const u8 String_07D2[] = _("<PROC=0>\n<END>");
const u8 String_07D3[] = _("<LABEL=ZAJI>ザジ</LABEL>\n「うちの星読みによると、向か\nった先は北西にある大聖堂。");
const u8 String_07D4[] = _("ほんまはうちが探しに行ければ\nええんですけど・・・今うちは\n結界を守らなあきません。");
const u8 String_07D5[] = _("この太陽街に張られた結界も、\nだいぶ弱なってます・・・");
const u8 String_07D6[] = _("うちの力でどこまでできるんか\n分からしませんけど、できるだ\nけのことはやってみます」");
const u8 String_07D7[] = _("<PROC=0>\n<END>");
const u8 String_07D8[] = _("<LABEL=SUMIRE>スミレ</LABEL>\n「これ・・・」");
const u8 String_07D9[] = _("<LABEL=OTENKO>おてんこさま</LABEL>\n「それは・・・");
const u8 String_07DA[] = _("太陽銃(たいようじゅう)レンズ\nフレイム!!」");
const u8 String_07DB[] = _("<LABEL=SUMIRE>スミレ</LABEL>\n「さっきひろったの・・・」");
const u8 String_07DC[] = _("<PROC=0>\n<END>");
const u8 String_07DD[] = _("<LABEL=ZAJI>ザジ</LABEL>\n「<NAME>やったっけ?");
const u8 String_07DE[] = _("スミちゃんからの依頼料(いら\nいりょう)や。受け取っとき。");
const u8 String_07DF[] = _("ソル・デ・バイスを使(つこ)て\nそのレンズからエンチャントの\n力を引き出すんや」");
const u8 String_07E0[] = _("<PROC=0>\n<END>");
const u8 String_07E1[] = _("<PROC=2>太陽銃レンズ「フレイム」\nを取り戻した!");
const u8 String_07E2[] = _("<PROC=0>\n<END>");
const u8 String_07E3[] = _("<PROC=1>月光魔法\n「エンチャント・フレイム」\nを覚えた!!");
const u8 String_07E4[] = _("<PROC=0>\n<END>");
const u8 String_07E5[] = _("<LABEL=OTENKO>おてんこさま</LABEL>\n「そのレンズが落ちていたとい\nうことは・・・");
const u8 String_07E6[] = _("ヤツは近くにいる!?\nだが・・・");
const u8 String_07E7[] = _("今はスミスの捜索(そうさく)が\n先だ。");
const u8 String_07E8[] = _("<NAME>、\n北西の大聖堂に向かうんだ!!」");
const u8 String_07E9[] = _("<PROC=0>\n<END>");

const u8 String_07EA[] = _("<LABEL=OTENKO>おてんこさま</LABEL>\n「今のは・・・」");
const u8 String_07EB[] = _("<PROC=0>\n<END>");
const u8 String_07EC[] = _("???\n<PROC=1><LOCK=44>「お待ちなさい・・・」");
const u8 String_07ED[] = _("<PROC=0>\n<END>");
const u8 String_07EE[] = _("<LABEL=DUNEYRR>白いコ―トの女</LABEL>\n「あなたが太陽少年・・・?\nかわいらしい坊(ぼう)やだこと");
const u8 String_07EF[] = _("私は白きドゥネイル。\n空を支配するイモ―タル・・・");
const u8 String_07F0[] = _("いきなりで悪いけど・・・\nあなたにはここで死んでもらう\nわ。");
const u8 String_07F1[] = _("お兄さまは相手にするな、\nなんておっしゃったけれど\n・・・");
const u8 String_07F2[] = _("私、お腹がすいたの。\n本当に永いこと眠(ねむ)ってい\nたんだもの。");
const u8 String_07F3[] = _("でも、目覚めてそうそうに太陽\n仔(たいようし)を食べられるな\nんて、素敵だわ・・・");
const u8 String_07F4[] = _("そういうことだから・・・\nごめんなさいね、坊や」");
const u8 String_07F5[] = _("<PROC=0>\n<END>");

const u8 String_07F6[] = _("<LABEL=OTENKO>おてんこさま</LABEL>\n「スミス!!」");
const u8 String_07F7[] = _("<LABEL=SMITH>スミス</LABEL>\n「う・・・うう・・・」");
const u8 String_07F8[] = _("<PROC=0>\n<END>");
const u8 String_07F9[] = _("<LABEL=SMITH>スミス</LABEL>\n「あんたは・・・\nおお、おてんこ!!」");
const u8 String_07FA[] = _("<LABEL=OTENKO>おてんこさま</LABEL>\n「久しいな、ガンスミス!!」");
const u8 String_07FB[] = _("<LABEL=SMITH>スミス</LABEL>\n「今ではただの鍛冶屋(かじや)\nブラックスミスじゃよ。");
const u8 String_07FC[] = _("頭はすっかり白いがな。");
const u8 String_07FD[] = _("そんなことより<NAME>!!\nよくぞ無事帰ってくれた。");
const u8 String_07FE[] = _("ヴァンパイア・ロ―ド、伯爵(\nはくしゃく)を倒(たお)したん\nじゃな!?」");
const u8 String_07FF[] = _("<PROC=0>\n<END>");
const u8 String_0800[] = _("<LABEL=OTENKO>おてんこさま</LABEL>\n「そう、");
const u8 String_0801[] = _("それにクイ―ン・オブ・イモ―\nタルとなったヘルもだ・・・");
const u8 String_0802[] = _("・・・だが同時に我々は、");
const u8 String_0803[] = _("<NAME>の母親・・・\n月下美人のマ―ニをも失ってし\nまった・・・」");
const u8 String_0804[] = _("<LABEL=SMITH>スミス</LABEL>\n「そうか・・・」");
const u8 String_0805[] = _("<LABEL=OTENKO>おてんこさま</LABEL>\n「スミス、リンゴは!?\nリンゴはやはり・・・」");
const u8 String_0806[] = _("<LABEL=SMITH>スミス</LABEL>\n「ああ・・・");
const u8 String_0807[] = _("師を残して1人で先に逝(い)っ\nちまうとは・・・");
const u8 String_0808[] = _("あのバカ弟子が!!");
const u8 String_0809[] = _("・・・すまない、\n<NAME>・・・」");
const u8 String_080A[] = _("<PROC=0>\n<END>");
const u8 String_080B[] = _("<LABEL=OTENKO>おてんこさま</LABEL>\n「・・・");
const u8 String_080C[] = _("ところで・・・\nおまえはなぜここに残った?");
const u8 String_080D[] = _("いったいこの街に何があったと\n言うんだ?」");
const u8 String_080E[] = _("<LABEL=SMITH>スミス</LABEL>\n「それなんじゃが・・・\nこいつを見てくれ」");
const u8 String_080F[] = _("<PROC=0>\n<END>");
const u8 String_0810[] = _("<LABEL=OTENKO>おてんこさま</LABEL>\n「これは・・・くさび?\n何かの封印(ふういん)か?」");
const u8 String_0811[] = _("<LABEL=SMITH>スミス</LABEL>\n「伯爵が去った後、吸血変異は\n収まったかに見えた・・・");
const u8 String_0812[] = _("だがその後、アンデッドどもが\n妙(みょう)な動きを見せ始めた\nんじゃ。");
const u8 String_0813[] = _("まるで何かを探しているかのよ\nうな・・・");
const u8 String_0814[] = _("そしてこの街の守人(もりびと)\nその子孫であるシャイアンが警\n告した。");
const u8 String_0815[] = _("アンデッドどもが封印を破(や\nぶ)ろうとしている、と。");
const u8 String_0816[] = _("その封印が何なのかは分からん\nじゃが・・・」");
const u8 String_0817[] = _("<LABEL=OTENKO>おてんこさま</LABEL>\n「破壊(はかい)されたくさび\n・・・");
const u8 String_0818[] = _("ここに封印されていたのがあの\nドゥネイルか・・・?");
const u8 String_0819[] = _("だが例のヴァンパイアのことも\nある。この街にはまだ我々の知\nらない何かがあるのだ・・・」");
const u8 String_081A[] = _("<PROC=0>\n<END>");
const u8 String_081B[] = _("<LABEL=OTENKO>おてんこさま</LABEL>\n「その猫(ねこ)は?」");
const u8 String_081C[] = _("<PROC=0>\n<END>");
const u8 String_081D[] = _("<LABEL=SMITH>スミス</LABEL>\n「こいつはクロ。\n孫娘(まごむすめ)の友達じゃ。");
const u8 String_081E[] = _("こんな所にまでむかえに来ると\nは・・・\n猫ながら大した度胸じゃわい」");
const u8 String_081F[] = _("<LABEL=OTENKO>おてんこさま</LABEL>\n「ふうむ・・・");
const u8 String_0820[] = _("我々がこの場にたどり着けたの\nも、その猫のおかげだからな。\n礼を言うぞ、クロ!!」");
const u8 String_0821[] = _("<PROC=0>\n<END>");
const u8 String_0822[] = _("<LABEL=OTENKO>おてんこさま</LABEL>\n「ともかく、");
const u8 String_0823[] = _("スミスは太陽街に戻(もど)って\nいてくれ。\nスミレも心配している。");
const u8 String_0824[] = _("我々はあのイモ―タルを浄化(\nじょうか)する」");
const u8 String_0825[] = _("<LABEL=SMITH>スミス</LABEL>\n「分かった。\n太陽街で待つとしよう」");
const u8 String_0826[] = _("<PROC=0>\n<END>");
const u8 String_0827[] = _("<LABEL=OTENKO>おてんこさま</LABEL>\n「よし、<NAME>!!");
const u8 String_0828[] = _("あの棺桶(かんおけ)を商店街の\n北にあった広場まで運ぶんだ。");
const u8 String_0829[] = _("そこにパイルドライバ―を召喚\n(しょうかん)し、");
const u8 String_082A[] = _("太陽の光をもってイモ―タル、\n白きドゥネイルを浄化する!」");
const u8 String_082B[] = _("<PROC=0>\n<END>");

const u8 String_082C[] = _("<LABEL=NONE>リボンの少女</LABEL>\n「<NAME>さま!!\nおてんこさま!!」");
const u8 String_082D[] = _("<LABEL=OTENKO>おてんこさま</LABEL>\n「リタ!!\nどうしてここに!");
const u8 String_082E[] = _("サバタが予見していたように、\n今このサン・ミゲルにはアンデ\nッドがさまよい、");
const u8 String_082F[] = _("その裏にはイモ―タルの陰謀(\nいんぼう)が見え隠(かく)れし\nている。");
const u8 String_0830[] = _("いくら君が・・・」");
const u8 String_0831[] = _("<LABEL=RITA>リタ</LABEL>\n「もうしわけありません!!\n・・・ですが、");
const u8 String_0832[] = _("お2人が命がけで戦っていらっ\nしゃるというのに、");
const u8 String_0833[] = _("わたしは安全なところで待って\nいるだけだなんて!」");
const u8 String_0834[] = _("<LABEL=OTENKO>おてんこさま</LABEL>\n「だが君は、巫女(みこ)であり\n戦士ではない。");
const u8 String_0835[] = _("わざわざ危険の中に身をさらす\nことはないだろう?」");
const u8 String_0836[] = _("<LABEL=RITA>リタ</LABEL>\n「おっしゃる通り、わたしは戦\n士ではなく巫女です・・・");
const u8 String_0837[] = _("ですが大地の巫女であるわたし\nにも、わたしだからこそできる\nことがある。そう思ったんです");
const u8 String_0838[] = _("それに、このサン・ミゲルはわ\nたしにとっても故郷(こきょう)");
const u8 String_0839[] = _("この太陽の街から闇(やみ)を払\n(はら)うために、");
const u8 String_083A[] = _("<PROC=0>\n<END>");
const u8 String_083B[] = _("<LABEL=RITA></LABEL>わたしにもできる限りのことを\nさせてください!!」");
const u8 String_083C[] = _("<LABEL=OTENKO>おてんこさま</LABEL>\n「・・・分かった。");
const u8 String_083D[] = _("そこまでの覚悟(かくご)がある\nのなら、私から言うべきことは\n何もない。");
const u8 String_083E[] = _("いや、大地の巫女リタよ・・・");
const u8 String_083F[] = _("共にイモ―タルの野望を打ち砕\n(くだ)き、この太陽の街に再び\n光を取り戻(もど)そう!!」");
const u8 String_0840[] = _("<PROC=0>\n<END>");
const u8 String_0841[] = _("<LABEL=RITA>リタ</LABEL>\n「ありがとうございます、\nおてんこさま・・・」");
const u8 String_0842[] = _("<LABEL=OTENKO>おてんこさま</LABEL>\n「さっそくだが、リタ。");
const u8 String_0843[] = _("吸血変異の収まったはずのこの\n街が、いまだに浄化(じょうか)\nされないその理由・・・");
const u8 String_0844[] = _("何か心当たりが?」");
const u8 String_0845[] = _("<PROC=0>\n<END>");
const u8 String_0846[] = _("<LABEL=RITA>リタ</LABEL>\n「はい・・・");
const u8 String_0847[] = _("このサン・ミゲルの大地からは\n今、太陽の力が失われています");
const u8 String_0848[] = _("降り注ぐ太陽の光、そのエネル\nギ―が大地にたくわえられるそ\nの前に・・・");
const u8 String_0849[] = _("何者かがそれを奪(うば)い去っ\nているのです。");
const u8 String_084A[] = _("ですからその原因を取り除かな\nい限り、この地に再び太陽樹さ\nまの種を根づかせ、");
const u8 String_084B[] = _("そのお力でこの呪(のろ)われた\n街を浄化していただくことはで\nきません」");
const u8 String_084C[] = _("<LABEL=OTENKO>おてんこさま</LABEL>\n「そうか・・・」");
const u8 String_084D[] = _("<PROC=0>\n<END>");
const u8 String_084E[] = _("<LABEL=OTENKO>おてんこさま</LABEL>\n「これで我々の目標は定まった");
const u8 String_084F[] = _("1つはあのヴァンパイアを見つ\nけだし、太陽銃(たいようじゅ\nう)を取り戻すこと。");
const u8 String_0850[] = _("そしてもう1つは、大地から力\nを奪っている何者か、その原因\nを取り除くことだ。");
const u8 String_0851[] = _("まずは手がかりを集めなくては\n・・・");
const u8 String_0852[] = _("ひまわり娘(むすめ)やスミスが\n何かをつかんでいるかもしれん\n商店街に向かおう」");
const u8 String_0853[] = _("<PROC=0>\n<END>");
const u8 String_0854[] = _("<LABEL=RITA>リタ</LABEL>\n「商店街といえば、");
const u8 String_0855[] = _("少しでも街に残ったみなさんの\nお役に立てないかとお願いして");
const u8 String_0856[] = _("<PROC=0>\n<END>");
const u8 String_0857[] = _("<LABEL=RITA></LABEL>わたし、果物屋さんをさせてい\nただくことになったんです!");
const u8 String_0858[] = _("<PROC=0>\n<END>");
const u8 String_0859[] = _("<LABEL=RITA></LABEL>お店であつかっている太陽の果\n実は、お2人の冒険(ぼうけん)\nにもきっと役立ちますわ!!");
const u8 String_085A[] = _("<PROC=0>\n<END>");
const u8 String_085B[] = _("<LABEL=RITA></LABEL>ぜひお立ち寄りくださいね、\n<NAME>さま♪");
const u8 String_085C[] = _("<PROC=0>\n<END>");
const u8 String_085D[] = _("<LABEL=RITA></LABEL><PROC=1><LOCK=90>いつも心に太陽を!」");
const u8 String_085E[] = _("<PROC=0>\n<END>");
const u8 String_085F[] = _("<LABEL=OTENKO>おてんこさま</LABEL>\n「ふっ・・・");
const u8 String_0860[] = _("この街を救いたい、というリタ\nの想いはもちろん本心だろうが\n・・・");
const u8 String_0861[] = _("少しでもおまえの近くにいたか\nったというのが本音かな?」");
const u8 String_0862[] = _("<PROC=0>\n<END>");
const u8 String_0863[] = _(" <ALTER>うれしい</ALTER>  <ALTER>不安かも</ALTER>");
const u8 String_0864[] = _("<PROC=0>\n<END>");
const u8 String_0865[] = _("<LABEL=OTENKO>おてんこさま</LABEL>\n「うむ。");
const u8 String_0866[] = _("<PROC=0>\n<END>");
const u8 String_0867[] = _("<LABEL=OTENKO></LABEL>彼女(かのじょ)の想いに応える\nためにも・・・\nこの戦い、負けられないぞ!!」");
const u8 String_0868[] = _("<PROC=0>\n<END>");
const u8 String_0869[] = _("<LABEL=OTENKO>おてんこさま</LABEL>\n「そうか・・・");
const u8 String_086A[] = _("まあ、相手が相手だ。\nおまえが不安を感じるのも無理\nはない。");
const u8 String_086B[] = _("まさかあの大穴をこの短時間に\n埋(う)めるとは・・・」");
const u8 String_086C[] = _("<PROC=0>\n<END>");
const u8 String_086D[] = _("<LABEL=OTENKO>おてんこさま</LABEL>\n「がんばれよ、\n<NAME>・・・」");
const u8 String_086E[] = _("<PROC=0>\n<END>");
const u8 String_086F[] = _("<LABEL=SMITH>スミス</LABEL>\n「無事、イモ―タルを浄化(じ\nょうか)したようじゃな!");
const u8 String_0870[] = _("さすがは最強のヴァンパイアハ\nンタ―、紅のリンゴの息子じゃ\n<NAME>!!」");
const u8 String_0871[] = _("<PROC=0>\n<END>");
const u8 String_0872[] = _("<LABEL=SUMIRE>スミレ</LABEL>\n「あの・・・");
const u8 String_0873[] = _("<PROC=0>\n<END>");
const u8 String_0874[] = _("<LABEL=SUMIRE></LABEL>おじいちゃんをたすけてくれて\nありがとう!!」");
const u8 String_0875[] = _("<PROC=0>\n<END>");
const u8 String_0876[] = _("<LABEL=SMITH>スミス</LABEL>\n「事情はひまわり娘(むすめ)か\nら聞いた。");
const u8 String_0877[] = _("太陽銃(たいようじゅう)ガン・\nデル・ソルを奪(うば)われると\nは・・・");
const u8 String_0878[] = _("だがその太陽機ソル・デ・バイ\nスも、太陽銃に負けない、ある\nいはそれ以上の力を秘めておる");
const u8 String_0879[] = _("その力を引き出すには、おまえ\nのレベルと武器の威力(いりょ\nく)を高める必要があるな。");
const u8 String_087A[] = _("わしは今、鍛冶屋(かじや)をや\nっておる。");
const u8 String_087B[] = _("おまえの持つ太陽の力を利用す\nれば、より威力の高い武器を作\nることができるかもしれん。");
const u8 String_087C[] = _("言わば太陽鍛冶じゃ。");
const u8 String_087D[] = _("ただし新たな武器を作るには、\nその材料となる武器が2つ必要\nなんじゃ。");
const u8 String_087E[] = _("当然ながら材料しだいで出来上\nがる武器も変わるぞ。");
const u8 String_087F[] = _("材料になりそうな武器が集まっ\nたら、この鍛冶屋に来てくれ。");
const u8 String_0880[] = _("今のわしにできるのは鍛冶くら\nいじゃが・・・");
const u8 String_0881[] = _("協力は惜(お)しまんからな!!」");
const u8 String_0882[] = _("<PROC=0>\n<END>");
const u8 String_0883[] = _("<LABEL=ZAJI>ザジ</LABEL>\n「ご苦労やったな、\n<NAME>!!");
const u8 String_0884[] = _("しかしじいちゃん連れ戻(もど)\nすついでに、イモ―タルまで1\n人片づけるやなんて、");
const u8 String_0885[] = _("ほんまようやるわ。");
const u8 String_0886[] = _("これもうちが貸したったソル・\nデバのおかげやな!");
const u8 String_0887[] = _("(あないなガラクタがこない役\n立つやなんて、分からんもんや\n・・・にゃはは♪)");
const u8 String_0888[] = _("それはそうと、例のヴァンパイ\nアの行方や。");
const u8 String_0889[] = _("スミちゃんがレンズ拾うたっち\nゅう辺りから、闇(やみ)の気配\nを探ってみたんやけど、");
const u8 String_088A[] = _("南東にある砂漠(さばく)の遺跡\n(いせき)がどうも臭(にお)うで");
const u8 String_088B[] = _("<PROC=0>\n<END>");
const u8 String_088C[] = _("<LABEL=ZAJI></LABEL>遺跡はその道を行った先や。");
const u8 String_088D[] = _("でも気ぃつけや。\nうちの感じた気配は1つやない");
const u8 String_088E[] = _("あの遺跡には少なくとも2人以\n上のイモ―タルがおるで・・・");
const u8 String_088F[] = _("<PROC=0>\n<END>");
const u8 String_0890[] = _("<LABEL=ZAJI></LABEL>ふわぁ・・・\nほなうちは休ませてもらうわ。");
const u8 String_0891[] = _("結界を維持(いじ)するんも楽や\nないねん。");
const u8 String_0892[] = _("そこの宿屋におるから、何やあ\nったら起こしてな。\n後は任せたで」");
const u8 String_0893[] = _("<PROC=0>\n<END>");
const u8 String_0894[] = _("<LABEL=KID>アフロの男</LABEL>\n「何だ、またオマエか・・・");
const u8 String_0895[] = _("ん!?\n何か違(ちが)うな?");
const u8 String_0896[] = _("さっきオマエそっくりなヤツに\n会ったんだが・・・ま、いいか");
const u8 String_0897[] = _("オレはキッド。\n街の道具屋で働いている。");
const u8 String_0898[] = _("アンデッドに追われて、この遺\n跡(いせき)に逃(に)げ込(こ)ん\nだはいいが、");
const u8 String_0899[] = _("あの妙(みょう)な植物に邪魔(\nじゃま)されて、出られなくな\nっちまったんだ。");
const u8 String_089A[] = _("おまけに変なオッサンには襲(\nおそ)われそうになるし、");
const u8 String_089B[] = _("まったく踏(ふ)んだりけったり\n・・・バッドだぜ。");
const u8 String_089C[] = _("だがそれもここまでだ。");
const u8 String_089D[] = _("さっき言ったオマエそっくりな\nヤツが、トゲトゲをぶっ壊(こ\nわ)してくれたからな。");
const u8 String_089E[] = _("オレはとっとと逃げるとするぜ");
const u8 String_089F[] = _("それはそうと、オマエはこんな\nところで何してんだ?」");
const u8 String_08A0[] = _("<PROC=0>\n<END>");
const u8 String_08A1[] = _(" <ALTER>ヴァンパイアを追っている</ALTER>\n <ALTER>道に迷っている</ALTER>");
const u8 String_08A2[] = _("<PROC=0>\n<END>");
const u8 String_08A3[] = _("<LABEL=KID>キッド</LABEL>\n「なるほど・・・");
const u8 String_08A4[] = _("そんなときに役に立つのが、メ\nニュ―画面のマップだぜ?");
const u8 String_08A5[] = _("だがダンジョンのマップは、初\nめから見ることができるわけじ\nゃあない。");
const u8 String_08A6[] = _("ダンジョンごとに地図を手に入\nれなきゃ、マップを見ることは\nできない。");
const u8 String_08A7[] = _("しかも地図は、1つのダンジョ\nンに1枚とは限らないからな。");
const u8 String_08A8[] = _("確かその辺に1枚落ちていたよ\nうな・・・");
const u8 String_08A9[] = _("で、\n結局おまえはだれなんだ?」");
const u8 String_08AA[] = _("<PROC=0>\n<END>");
const u8 String_08AB[] = _("<LABEL=KID>キッド</LABEL>\n「するってぇと・・・");
const u8 String_08AC[] = _("オマエがスミスのジジイが言っ\nてたソ―ラ―ボ―イだな!?");
const u8 String_08AD[] = _("あの話、本当だったのか・・・\nグレイト!!");
const u8 String_08AE[] = _("もうこの街もおしまいかと思っ\nたが、こうなって来ると話は別\nだ。");
const u8 String_08AF[] = _("オレも残るぜ!!");
const u8 String_08B0[] = _("さっそく店を開けなきゃな。\nオマエも来てくれよ?");
const u8 String_08B1[] = _("ウチの道具屋は、アイテムの他\nに防具も取りあつかってるから\nな!");
const u8 String_08B2[] = _("そういえばさっき言ったオッサ\nン、");
const u8 String_08B3[] = _("オマエそっくりなヤツに追われ\nて、どっか行っちまったんだが");
const u8 String_08B4[] = _("こんなものを落としていったぜ\n?");
const u8 String_08B5[] = _("あれがヴァンパイアだったとす\nると、コイツは何かの役に立つ\nんじゃないか?」");
const u8 String_08B6[] = _("<PROC=0>\n<END>");
const u8 String_08B7[] = _("<PROC=2>太陽銃レンズ「フロスト」\nを取り戻した!");
const u8 String_08B8[] = _("<PROC=0>\n<END>");
const u8 String_08B9[] = _("<PROC=1><LOCK=96>月光魔法\n「エンチャント・フロスト」\nを覚えた!!");
const u8 String_08BA[] = _("<PROC=0>\n<END>");
const u8 String_08BB[] = _("<LABEL=KID>キッド</LABEL>\n「もう分かっているだろうが、\nこの遺跡には罠(わな)が多い。");
const u8 String_08BC[] = _("くれぐれも注意しろよ?\n特に宝箱にはな。");
const u8 String_08BD[] = _("じゃあな!\n生きて戻(もど)れよ、\nボ―イ!!」");
const u8 String_08BE[] = _("<PROC=0>\n<END>");
const u8 String_08BF[] = _("<LABEL=OTENKO>おてんこさま</LABEL>\n「そのレンズ・・・\nやはりヤツはこの遺跡にいる!!");
const u8 String_08C0[] = _("それにおまえにそっくりな者と\nいえば・・・\nあいつもここに?」");
const u8 String_08C1[] = _("<PROC=0>\n<END>");
const u8 String_08C2[] = _("<LABEL=OTENKO>おてんこさま</LABEL>\n「暗黒少年サバタ!!");
const u8 String_08C3[] = _("やはりこのサン・ミゲルに来て\nいたのか」");
const u8 String_08C4[] = _("<PROC=0>\n<END>");
const u8 String_08C5[] = _("<LABEL=SABATA>サバタ</LABEL>\n「<NAME>・・・");
const u8 String_08C6[] = _("とんだドジを踏(ふ)んだものだ\nな?");
const u8 String_08C7[] = _("おまえともあろう者が、太陽銃\n(たいようじゅう)を奪(うば)わ\nれるとは・・・」");
const u8 String_08C8[] = _("<PROC=0>\n<END>");
const u8 String_08C9[] = _("<LABEL=OTENKO>おてんこさま</LABEL>\n「どうしてそれを?」");
const u8 String_08CA[] = _("<LABEL=SABATA>サバタ</LABEL>\n<PROC=1>「フッ・・・");
const u8 String_08CB[] = _("<PROC=2>味わったからな。忘れもしない\n太陽銃ガン・デル・ソル、その\n一撃(いちげき)を」");
const u8 String_08CC[] = _("<PROC=0>\n<END>");
const u8 String_08CD[] = _("<LABEL=OTENKO>おてんこさま</LABEL>\n「ではあのヴァンパイアと?\nヤツはどこに!?」");
const u8 String_08CE[] = _("<LABEL=SABATA>サバタ</LABEL>\n「逃(に)げられた・・・いや、\n見逃されたというべきか・・・");
const u8 String_08CF[] = _("ただのヴァンパイアだと油断し\nた。あれほどの手練(てだれ)だ\nとはな。");
const u8 String_08D0[] = _("その上太陽銃まで使われては。\n・・・おかげでこのざまだ。");
const u8 String_08D1[] = _("ヤツはいったい何者なんだ?」");
const u8 String_08D2[] = _("<LABEL=OTENKO>おてんこさま</LABEL>\n「分からない・・・");
const u8 String_08D3[] = _("だが何かが引っかかる。\n私はヤツに・・・初めて会った\n気がしないのだ・・・」");
const u8 String_08D4[] = _("<LABEL=SABATA>サバタ</LABEL>\n「・・・");
const u8 String_08D5[] = _("いずれにせよ、太陽銃を失った\nおまえにかなう相手ではない。");
const u8 String_08D6[] = _("引き返せ、<NAME>」");
const u8 String_08D7[] = _("<PROC=0>\n<END>");
const u8 String_08D8[] = _(" <ALTER>引き返す</ALTER>　<ALTER>そうはいかない</ALTER>");
const u8 String_08D9[] = _("<PROC=0>\n<END>");
const u8 String_08DA[] = _("<LABEL=SABATA>サバタ</LABEL>\n「・・・");
const u8 String_08DB[] = _("いずれにせよ、太陽銃を失った\nおまえにかなう相手ではない。");
const u8 String_08DC[] = _("引き返せ、<NAME>」");
const u8 String_08DD[] = _("<PROC=0>\n<END>");
const u8 String_08DE[] = _(" <ALTER>引き返す</ALTER>　<ALTER>そうはいかない</ALTER>");
const u8 String_08DF[] = _("<PROC=0>\n<END>");
const u8 String_08E0[] = _("<LABEL=SABATA>サバタ</LABEL>\n「どうしても行くというのか?");
const u8 String_08E1[] = _("<PROC=1><LOCK=20>フッ・・・");
const u8 String_08E2[] = _("<PROC=3>この星のすべての生命種を切り\n捨てようとする銀河宇宙の意思");
const u8 String_08E3[] = _("それに逆らおうというおまえた\nちだ・・・勝ち目のない戦いに\nは慣れている、か?");
const u8 String_08E4[] = _("<PROC=2><LOCK=63>フッハッハッハッハッ!!\nいいだろう、\nこれを持って行け」");
const u8 String_08E5[] = _("<PROC=0>\n<END>");
const u8 String_08E6[] = _("<PROC=2>太陽銃レンズ「クラウド」\nを取り戻した!");
const u8 String_08E7[] = _("<PROC=0>\n<END>");
const u8 String_08E8[] = _("<PROC=1><LOCK=96>月光魔法\n「エンチャント・クラウド」\nを覚えた!!");
const u8 String_08E9[] = _("<PROC=0>\n<END>");
const u8 String_08EA[] = _("<LABEL=SABATA>サバタ</LABEL>\n「ヤツはこの先の扉(とびら)の\n向こうに去った。");
const u8 String_08EB[] = _("ヤツを追うには扉を開けるため\nのカギが必要だ。\nまずはそれを探し出せ」");
const u8 String_08EC[] = _("<PROC=0>\n<END>");
const u8 String_08ED[] = _("<LABEL=RINGO1>ヴァンパイア</LABEL>\n「来るな・・・");
const u8 String_08EE[] = _("俺に、近づくな・・・");
const u8 String_08EF[] = _("心が・闇(やみ)・・に・・・");
const u8 String_08F0[] = _("沈・・・む・・・」");
const u8 String_08F1[] = _("<PROC=0>\n<END>");
const u8 String_08F2[] = _("<LABEL=OTENKO>おてんこさま</LABEL>\n「これは・・・\nあのときと同じ!?」");
const u8 String_08F3[] = _("<LABEL=RINGO1>ヴァンパイア</LABEL>\n<PROC=1>「う・・・う!!");
const u8 String_08F4[] = _("逃(に)げろ・・・");
const u8 String_08F5[] = _("逃げるんだ、<NAME>!!」");
const u8 String_08F6[] = _("<LABEL=OTENKO>おてんこさま</LABEL>\n「おまえは・・・まさか!?」");
const u8 String_08F7[] = _("<PROC=0>\n<END>");
const u8 String_08F8[] = _("<LABEL=DAAIN>黒い影</LABEL>\n<PROC=1><LOCK=57>「クックックッ・・・");
const u8 String_08F9[] = _("<PROC=2>ようやく気がついたかい?\nでも、もう手遅(ておく)れさ。");
const u8 String_08FA[] = _("太陽の使者おてんこ。あなたに\nはここらで退場してもらおう。");
const u8 String_08FB[] = _("ここからの道案内はボクが引き\n継(つ)ぐ。");
const u8 String_08FC[] = _("彼(かれ)ら2人の・・・\n闇(やみ)への道案内をね!!」");
const u8 String_08FD[] = _("<PROC=0>\n<END>");
const u8 String_08FE[] = _("<LABEL=RINGO1>ヴァンパイア</LABEL>\n「ああああああああああ!!」");
const u8 String_08FF[] = _("<PROC=0>\n<END>");
const u8 String_0900[] = _("<LABEL=SABATA>サバタ</LABEL>\n「何をボサッとしている!\n<NAME>!!");
const u8 String_0901[] = _("おてんこのことは後だ。\n今はこのヴァンパイアを倒(た\nお)すことを考えろ!");
const u8 String_0902[] = _("俺がブラックホ―ルでヤツの動\nきを封(ふう)じる!");
const u8 String_0903[] = _("それまで、援護(えんご)は任せ\nたぞ!!」");
const u8 String_0904[] = _("<PROC=0>\n<END>");
const u8 String_0905[] = _("<LABEL=RINGO2>ヴァンパイア</LABEL>\n「おまえたちは・・・");
const u8 String_0906[] = _("<NAME>・・・\nそれに、まさか・・・\n・・・サバタ!?」");
const u8 String_0907[] = _("<LABEL=SABATA>サバタ</LABEL>\n「なぜ俺の名を・・・!?」");
const u8 String_0908[] = _("<LABEL=R_DJUNGO><NAME></LABEL>\n「おとう・・・さん?」");
const u8 String_0909[] = _("<PROC=0>\n<END>");
const u8 String_090A[] = _("<LABEL=RINGO2>ヴァンパイア</LABEL>\n「・・・");
const u8 String_090B[] = _("<NAME>・・・!!」");
const u8 String_090C[] = _("<PROC=0>\n<END>");
const u8 String_090D[] = _("<LABEL=SABATA>サバタ</LABEL>\n「<NAME>!!");
const u8 String_090E[] = _("<PROC=0>\n<END>");
const u8 String_090F[] = _("<LABEL=SABATA></LABEL>くっ、ヴァンパイアの血を受け\n吸血変異が進行している・・・");
const u8 String_0910[] = _("変異をおさえるはずの月光仔(\nげっこうし)の血が効いていな\nい。なぜだ!?");
const u8 String_0911[] = _("拒絶反応(きょぜつはんのう)が\n強すぎる!");
const u8 String_0912[] = _("このままではヴァンパイア化す\nるどころか命が危ない・・・");
const u8 String_0913[] = _("危険な賭(か)けだが・・・\nパイルドライバ―を使うしかな\nい・・・!!」");
const u8 String_0914[] = _("<PROC=0>\n<END>");
const u8 String_0915[] = _("<LABEL=SABATA>サバタ</LABEL>\n「画面右上にあるのが\n<NAME>のライフゲ―ジ。");
const u8 String_0916[] = _("これがゼロになる前に太陽街の\nパイルドライバ―に運ばなけれ\nば・・・」");
const u8 String_0917[] = _("<PROC=0>\n<END>");
const u8 String_0918[] = _("<LABEL=NONE></LABEL><PROC=1>暗黒少年サバタのエナジ―は暗\n黒物質ダ―クマタ―だ。");
const u8 String_0919[] = _("エナジ―の回復には暗黒チャ―\nジが必要となる。");
const u8 String_091A[] = _("太陽ゲ―ジがゼロならばエナジ\n―は自然にチャ―ジされる。");
const u8 String_091B[] = _("また、Ａボタンを押(お)しっぱ\nなしにすれば急速チャ―ジを行\nうこともできる。");
const u8 String_091C[] = _("<PROC=0>\n<END>");
const u8 String_091D[] = _("<LABEL=SABATA>サバタ</LABEL>\n「破壊(はかい)されたくさび\n・・・");
const u8 String_091E[] = _("恐(おそ)らくは古のイモ―タル\nを封(ふう)じ込(こ)めたもの。");
const u8 String_091F[] = _("ここから復活したのがおてんこ\nを連れ去ったあの影(かげ)か。");
const u8 String_0920[] = _("<PROC=0>\n<END>");
const u8 String_0921[] = _("<LABEL=SABATA></LABEL>フッ、やはり死を超越(ちょう\nえつ)できるのは不死者、イモ\n―タルのみか・・・」");
const u8 String_0922[] = _("<PROC=0>\n<END>");
const u8 String_0923[] = _("<LABEL=RITA>リタ</LABEL>\n「<NAME>さま!?」");
const u8 String_0924[] = _("<PROC=0>\n<END>");
const u8 String_0925[] = _("<LABEL=ZAJI>ザジ</LABEL>\n「サバタの言う通り・・・\n今の<NAME>を助けるには、");
const u8 String_0926[] = _("パイルドライバ―でヴァンパイ\nアの血を浄化(じょうか)するし\nかあらへん」");
const u8 String_0927[] = _("<LABEL=RITA>リタ</LABEL>\n「でも・・・そんなことをした\nら、<NAME>さまは・・・」");
const u8 String_0928[] = _("<LABEL=ZAJI>ザジ</LABEL>\n「そや。これは賭(か)け、\n命がけの賭けや・・・」");
const u8 String_0929[] = _("<PROC=0>\n<END>");
const u8 String_092A[] = _("<LABEL=RITA>リタ</LABEL>\n「そんな!!\nそんなのって・・・」");
const u8 String_092B[] = _("<PROC=0>\n<END>");
const u8 String_092C[] = _("<LABEL=ZAJI>ザジ</LABEL>\n「あんた、\nあいつのこと好きなんやろ?」");
const u8 String_092D[] = _("<PROC=0>\n<END>");
const u8 String_092E[] = _("<LABEL=RITA>リタ</LABEL>\n「えっ!!\nあの、その、わたし・・・」");
const u8 String_092F[] = _("<LABEL=ZAJI>ザジ</LABEL>\n「ならあいつを信じたらんと。");
const u8 String_0930[] = _("星読みも同じや。\n信じたからといって必ずしも成\n功するとは限らへん。");
const u8 String_0931[] = _("どんなにがんばったかて、ダメ\nなもんはダメなんかも知れん。\nけどな、");
const u8 String_0932[] = _("信じんかったら、\nあきらめてしもたら・・・\nそれでもう、終わりなんや。");
const u8 String_0933[] = _("あのサバタにはそれがよう分か\nっとる。");
const u8 String_0934[] = _("だからあんたも・・・\nあいつのこと、信じるんや!");
const u8 String_0935[] = _("その想いはきっと通じる!!」");
const u8 String_0936[] = _("<PROC=0>\n<END>");
const u8 String_0937[] = _("<LABEL=RITA>リタ</LABEL>\n「<NAME>さま、\nそのお身体は・・・!?」");
const u8 String_0938[] = _("<LABEL=SABATA>サバタ</LABEL>\n「ヴァンパイア化までは・・・\n止められなかった・・・か」");
const u8 String_0939[] = _("<PROC=0>\n<END>");
const u8 String_093A[] = _("<LABEL=ZAJI>ザジ</LABEL>\n「サバタ!!」");
const u8 String_093B[] = _("<PROC=0>\n<END>");
const u8 String_093C[] = _("<PROC=2><LOCK=140>暗黒の力を手に入れた!");
const u8 String_093D[] = _("<PROC=1><LOCK40>月光魔法\n「エンチャント・ダ―ク」\nを覚えた!!");
const u8 String_093E[] = _("<PROC=1><LOCK=40>暗黒魔法「スリ―ピング」\nを覚えた!!");
const u8 String_093F[] = _("<PROC=1><LOCK=40>暗黒魔法「チェンジ・マウス」\nを覚えた!!");
const u8 String_0940[] = _("<PROC=1><LOCK=40>暗黒魔法「チェンジ・バット」\nを覚えた!!");
const u8 String_0941[] = _("<PROC=1><LOCK=40>暗黒魔法「チェンジ・ウルフ」\nを覚えた!!");
const u8 String_0942[] = _("<PROC=3><LOCK=200>太陽の力を失った!");
const u8 String_0943[] = _("<PROC=0>\n<END>");
const u8 String_0944[] = _("<LABEL=ZAJI>ザジ</LABEL>\n「<NAME>、");
const u8 String_0945[] = _("確かに今のあんたは半分ヴァン\nパイアや。");
const u8 String_0946[] = _("太陽の光はあんたの体を焼き、\n水はあんたの身を焦(こ)がす。");
const u8 String_0947[] = _("もはや太陽少年やなんて呼べへ\nん・・・\n言うたら黒<NAME>や。");
const u8 String_0948[] = _("せやけど、本当に大変なんはこ\nれからやで?");
const u8 String_0949[] = _("このまま暗黒の力に飲み込(こ)\nまれて、ほんまのヴァンパイア\nになってまうか、");
const u8 String_094A[] = _("それを退け、太陽少年としての\n自分を取り戻(もど)すか、");
const u8 String_094B[] = _("すべてはこれからや・・・」");
const u8 String_094C[] = _("<PROC=0>\n<END>");
const u8 String_094D[] = _("<LABEL=ZAJI>ザジ</LABEL>\n「サバタは?」");
const u8 String_094E[] = _("<LABEL=RITA>リタ</LABEL>\n「まだ、お目覚めになりません\n・・・」");
const u8 String_094F[] = _("<LABEL=ZAJI>ザジ</LABEL>\n「さよか・・・");
const u8 String_0950[] = _("<PROC=0>\n<END>");
const u8 String_0951[] = _("<LABEL=ZAJI></LABEL>魔女の弟子やっちゅうても、無\n力なもんや。こんなとき、何も\nできへんやなんて・・・」");
const u8 String_0952[] = _("<PROC=0>\n<END>");
const u8 String_0953[] = _("<LABEL=SHAIAN>???</LABEL>\n「ヴァンパイア・・・");
const u8 String_0954[] = _("やはりあの暗黒樹を操るはイモ\n―タルか。");
const u8 String_0955[] = _("<PROC=0>\n<END>");
const u8 String_0956[] = _("<LABEL=SHAIAN></LABEL>私はシャイアン。\nサン・ミゲルの守人、\n太陽の4士族が風の戦士。");
const u8 String_0957[] = _("たとえ最後の1人となろうとも\nおまえたちイモ―タルの好きに\nはさせん!");
const u8 String_0958[] = _("太陽を汚(けが)す夜の眷族(け\nんぞく)よ、");
const u8 String_0959[] = _("我が刃(やいば)を受け、\n闇(やみ)に帰るがいい!!」");
const u8 String_095A[] = _("<PROC=0>\n<END>");
const u8 String_095B[] = _(" <ALTER>待て!</ALTER>　<ALTER>来い!</ALTER>");
const u8 String_095C[] = _("<PROC=0>\n<END>");
const u8 String_095D[] = _("<LABEL=SHAIAN>シャイアン</LABEL>\n「問答無用!!」");
const u8 String_095E[] = _("<PROC=0>\n<END>");
const u8 String_095F[] = _("<LABEL=SHAIAN>シャイアン</LABEL>\n「おおおおおお!!」");
const u8 String_0960[] = _("<PROC=0>\n<END>");
const u8 String_0961[] = _("<LABEL=SHAIAN>シャイアン</LABEL>\n「まさか、\n<NAME>なのか・・・!!");
const u8 String_0962[] = _("おまえがヴァンパイアになろう\nとは・・・");
const u8 String_0963[] = _("・・・だが私は確信していた。\nおまえとの再会を・・・!");
const u8 String_0964[] = _("覚えているか?\nあの日、おまえの父親、紅のリ\nンゴの犠牲(ぎせい)により、");
const u8 String_0965[] = _("我々はサン・ミゲルからの脱出\n(だっしゅつ)に成功した。");
const u8 String_0966[] = _("しかしそこに待っていたのは、\n伯爵(はくしゃく)の罠(わな)\n・・・");
const u8 String_0967[] = _("ヴァンパイアの襲撃(しゅうげ\nき)を受け、我々は多くを失っ\nた。");
const u8 String_0968[] = _("スミスは片目を、私は兄弟を、\nそしておまえは・・・母親、マ\n―ニを奪(うば)われた。");
const u8 String_0969[] = _("だがそれでも、おまえは決して\nあきらめなかった。");
const u8 String_096A[] = _("父の形見、深紅のマフラ―をま\nとい、おまえは旅立った。\n死の都、イストラカンへ・・・");
const u8 String_096B[] = _("そして今、その身体に暗黒の血\nを受けてなお、おまえの目に絶\n望の色は見えない。");
const u8 String_096C[] = _("おまえの太陽は・・・\nまだ沈んではいない!!」");
const u8 String_096D[] = _("<PROC=0>\n<END>");
const u8 String_096E[] = _("<LABEL=SHAIAN>シャイアン</LABEL>\n「我ら守人は、古よりこの太陽\nの街を守ってきた。");
const u8 String_096F[] = _("しかしこの暗黒の時代・・・");
const u8 String_0970[] = _("伝承に残されたくさびの封印(\nふういん)、\nそれが何を封じたものなのか?");
const u8 String_0971[] = _("すべては時の彼方(かなた)に置\nき去りにされてしまった。");
const u8 String_0972[] = _("人々が太陽を忘れてしまったよ\nうに・・・");
const u8 String_0973[] = _("今や闇(やみ)の一族はよみがえ\nった。");
const u8 String_0974[] = _("大聖堂と砂漠(さばく)の遺跡(\nいせき)、すでに2つの封印が破\nられている。");
const u8 String_0975[] = _("あれを見てくれ。」");
const u8 String_0976[] = _("<PROC=0>\n<END>");
const u8 String_0977[] = _("<LABEL=SHAIAN>シャイアン</LABEL>\n「あの植物・・・\n自然界のものではない。");
const u8 String_0978[] = _("まさに暗黒樹・・・");
const u8 String_0979[] = _("<PROC=0>\n<END>");
const u8 String_097A[] = _("<LABEL=SHAIAN></LABEL>このようすでは、3つ目の封印\nも無事ではあるまい。");
const u8 String_097B[] = _("街中にあふれるあの暗黒の根の\nことを考えれば、");
const u8 String_097C[] = _("むしろこの暗黒街が、すべての\n始まりだったのかもしれん。");
const u8 String_097D[] = _("この街は、人々が自ら生み出し\nた暗黒に飲み込(こ)まれようと\nしている。");
const u8 String_097E[] = _("我々守人は、いったい何を守っ\nてきたのか・・・」");
const u8 String_097F[] = _("<PROC=0>\n<END>");
const u8 String_0980[] = _("<LABEL=SHAIAN>シャイアン</LABEL>\n「私の力では、あの暗黒樹にと\nどめを刺(さ)すことはできん。");
const u8 String_0981[] = _("もはやこの場に、私にできるこ\nとはない・・・");
const u8 String_0982[] = _("太陽街に戻(もど)り店を開けて\nおこう。スミスの鍛冶屋(かじ\nや)の向かい、武器屋だ。");
const u8 String_0983[] = _("少しはおまえの役に立つだろう");
const u8 String_0984[] = _("くさびの封印についても、引き\n続き調べてみよう。");
const u8 String_0985[] = _("<NAME>、\nおまえの手で、この暗黒の街を\n救ってくれ!");
const u8 String_0986[] = _("おまえならあの暗黒樹に・・・\n自らの暗黒にも勝てるはず!!");
const u8 String_0987[] = _("<PROC=0>\n<END>");
const u8 String_0988[] = _("<LABEL=SHAIAN></LABEL>このカギで1階の扉(とびら)が\n開く」");
const u8 String_0989[] = _("<PROC=0>\n<END>");
const u8 String_098A[] = _("<LABEL=NONE></LABEL><PROC=1>「○のカギ」\nを手に入れた!!");
const u8 String_098B[] = _("<PROC=0>\n<END>");
const u8 String_098C[] = _("<LABEL=SHAIAN>シャイアン</LABEL>\n「信じているぞ、\n太陽少年<NAME>!!」");
const u8 String_098D[] = _("<PROC=0>\n<END>");
const u8 String_098E[] = _("<LABEL=DAAIN>黒い影</LABEL>\n「とうとうここまでたどり着い\nたね。");
const u8 String_098F[] = _("暗黒の力は気に入ったかい?");
const u8 String_0990[] = _("今のキミは半ヴァンパイア。\nまだ暗黒の力を使いこなせては\nいない・・・でも、");
const u8 String_0991[] = _("そのすばらしさは理解できただ\nろう?");
const u8 String_0992[] = _("ここまで来られたのも、その力\nのおかげだからね。");
const u8 String_0993[] = _("<PROC=1><LOCK=85>ハッハッハッ・・・!!");
const u8 String_0994[] = _("<PROC=2>・・・紹介が遅(おく)れたね。\nボクは真なる暗黒仔(あんこく\nし)、黒きダ―イン。");
const u8 String_0995[] = _("<NAME>、\nボクたちの同志になるんだ。");
const u8 String_0996[] = _("真に世界を救う者、\nそれはイモ―タルに他ならない");
const u8 String_0997[] = _("共にこの世界を、許されざる者\nたちの手から解放しよう。");
const u8 String_0998[] = _("そうすればヴァンパイアとなっ\nたキミの父親、リンゴも喜ぶ」");
const u8 String_0999[] = _("<PROC=0>\n<END>");
const u8 String_099A[] = _("<LABEL=NONE>???</LABEL>\n「勝手に俺(おれ)の名を語って\nもらっては困るな!」");
const u8 String_099B[] = _("<PROC=0>\n<END>");
const u8 String_099C[] = _("<LABEL=DAAIN>黒きダ―イン</LABEL>\n「何・・・!!");
const u8 String_099D[] = _("<PROC=0>\n<END>");
const u8 String_099E[] = _("<LABEL=DAAIN></LABEL>記憶(きおく)が戻(もど)ったの\nか!?」");
const u8 String_099F[] = _("<LABEL=NONE>リンゴ</LABEL>\n「<NAME>、\n無事でいてくれたか・・・");
const u8 String_09A0[] = _("おまえの血・・・\nおまえの中に流れるマ―ニの血\nが、俺を目覚めさせた。");
const u8 String_09A1[] = _("だがそれも長くはもたん!");
const u8 String_09A2[] = _("今の内に、俺がこいつをおさえ\nている間に、暗黒樹の本体を倒\n(たお)すんだ!!」");
const u8 String_09A3[] = _("<PROC=0>\n<END>");
const u8 String_09A4[] = _("<LABEL=DAAIN>黒きダ―イン</LABEL>\n「クッ、");
const u8 String_09A5[] = _("伯爵(はくしゃく)め・・・\nこんな不完全なヴァンパイアを\n・・・」");
const u8 String_09A6[] = _("<PROC=0>\n<END>");
const u8 String_09A7[] = _("<LABEL=DURATHROR>赤毛の少女</LABEL>\n「黒兄さまもお遊びが過ぎる\n・・・");
const u8 String_09A8[] = _("白姉さまが敗れ、\n青姉さまはいまだ目覚めていな\nい。");
const u8 String_09A9[] = _("これ以上あなたを遊ばせておく\nわけにはいかないわ。");
const u8 String_09AA[] = _("害虫はすみやかに取り除かなく\nては・・・");
const u8 String_09AB[] = _("<PROC=0>\n<END>");
const u8 String_09AC[] = _("<LABEL=DURATHROR></LABEL>捨てられた街、暗黒街。\nその闇(やみ)が生んだ暗黒の種\n私が育てた暗黒の種・・・");
const u8 String_09AD[] = _("それは私に根づき、芽となった");
const u8 String_09AE[] = _("そして吸血変異のあの日・・・\n私はついに、\n本当の自分に目覚めた。");
const u8 String_09AF[] = _("黒兄さまが私を呼んでくれた!");
const u8 String_09B0[] = _("私はもう1人じゃない!");
const u8 String_09B1[] = _("私は必要とされている!");
const u8 String_09B2[] = _("私はここにいていいの!");
const u8 String_09B3[] = _("私は赤きドゥラスロ―ル!!\n陸を支配するイモ―タル!」");
const u8 String_09B4[] = _("<PROC=0>\n<END>");
const u8 String_09B5[] = _("<LABEL=DURATHROR>赤きドゥラスロ―ル</LABEL>\n「・・・光は闇(やみ)を引きつ\nける。");
const u8 String_09B6[] = _("でも、あなたの光は強すぎた。\nそれは黒兄さまを惑(まど)わせ\nる・・・");
const u8 String_09B7[] = _("もう光などいらないでしょ?");
const u8 String_09B8[] = _("私が連れて行ってあげる。\n光のない世界・・・\n日の昇(のぼ)らない世界へ!」");
const u8 String_09B9[] = _("<PROC=0>\n<END>");
const u8 String_09BA[] = _("リンゴの声\n「<NAME>・・・");
const u8 String_09BB[] = _("暗黒樹を浄化(じょうか)するん\nだ・・・」");
const u8 String_09BC[] = _("<PROC=0>\n<END>");
const u8 String_09BD[] = _("<LABEL=ZAJI>ザジ</LABEL>\n「それは・・・\n暗黒樹のイモ―タル?");
const u8 String_09BE[] = _("どうやら暗黒の力を使いこなし\nたようやな・・・");
const u8 String_09BF[] = _("せやけど<NAME>、\nあんたその身体でパイルドライ\nバ―を使う気なんか?");
const u8 String_09C0[] = _("確かに暗黒樹を浄化(じょうか\n)せな、このサン・ミゲルを救\nうことはできへん。");
const u8 String_09C1[] = _("せやけど、サバタがどないなっ\nたんか忘れたわけやないやろ?\nそれでもやる言うんか?」");
const u8 String_09C2[] = _("<PROC=0>\n<END>");
const u8 String_09C3[] = _(" <ALTER>やる</ALTER>　<ALTER>やらない</ALTER>");
const u8 String_09C4[] = _("<PROC=0>\n<END>");
const u8 String_09C5[] = _("<LABEL=ZAJI>ザジ</LABEL>\n「・・・");
const u8 String_09C6[] = _("あんたら兄弟そろって無茶やで");
const u8 String_09C7[] = _("ほんま無茶苦茶や・・・");
const u8 String_09C8[] = _("せやけどあんたらのそういうと\nこ、うちは好きやで。");
const u8 String_09C9[] = _("わかったわ、もう止めへん。");
const u8 String_09CA[] = _("あんたの戦いはうちが見守った\nる。思う存分やったり!!」");
const u8 String_09CB[] = _("<PROC=0>\n<END>");
const u8 String_09CC[] = _("<LABEL=ZAJI>ザジ</LABEL>\n「・・・");
const u8 String_09CD[] = _("そんなウソ、うちに通じると思\nてんの?");
const u8 String_09CE[] = _("ほんま兄弟そろって素直やない\nなぁ。");
const u8 String_09CF[] = _("せやけどあんたらのそういうと\nこ、うちは好きやで。");
const u8 String_09D0[] = _("わかったわ、もう止めへん。");
const u8 String_09D1[] = _("あんたの戦いはうちが見守った\nる。思う存分やったり!!」");
const u8 String_09D2[] = _("<PROC=0>\n<END>");
const u8 String_09D3[] = _("<LABEL=ZAJI>ザジ</LABEL>\n「<NAME>!?」");
const u8 String_09D4[] = _("<PROC=0>\n<END>");
const u8 String_09D5[] = _("<LABEL=NONE>???</LABEL>\n「<NAME>・・・");
const u8 String_09D6[] = _("起きるのです。");
const u8 String_09D7[] = _("あなたにはまだやるべきことが\n・・・");
const u8 String_09D8[] = _("あなたにしかできないことがあ\nるはずです。");
const u8 String_09D9[] = _("あなたを必要とする人たちがい\nるはずです。");
const u8 String_09DA[] = _("彼(かれ)らの声が聞こえません\nか?」");
const u8 String_09DB[] = _("<PROC=0>\n<END>");
const u8 String_09DC[] = _("<LABEL=ZAJI>ひまわり娘</LABEL>\n「こら<NAME>!!\nさっさと起きんかい!」");
const u8 String_09DD[] = _("<LABEL=SMITH>スミス</LABEL>\n「<NAME>!!」");
const u8 String_09DE[] = _("<LABEL=SUMIRE>スミレ</LABEL>\n「おにいちゃん!!」");
const u8 String_09DF[] = _("<LABEL=KID>キッド</LABEL>\n「ボ―イ!!」");
const u8 String_09E0[] = _("<LABEL=SHAIAN>シャイアン</LABEL>\n「<NAME>!!」");
const u8 String_09E1[] = _("<LABEL=RITA>リタ</LABEL>\n「<NAME>さま!!」");
const u8 String_09E2[] = _("<PROC=0>\n<END>");
const u8 String_09E3[] = _("<LABEL=SABATA>サバタ</LABEL>\n「<NAME>、\n暗黒の力に屈(くっ)するのか?");
const u8 String_09E4[] = _("忘れたのか、\nクイ―ンとの戦いを?");
const u8 String_09E5[] = _("おまえが教えてくれたことだろ\nう?");
const u8 String_09E6[] = _("死を乗り越(こ)える力・・・\nそれは生きようとする意思。");
const u8 String_09E7[] = _("それこそが・・・」");
const u8 String_09E8[] = _("<PROC=0>\n<END>");
const u8 String_09E9[] = _("<LABEL=B_DJUNGO><NAME></LABEL>\n「それこそが・・・");
const u8 String_09EA[] = _("<PROC=0>\n<END>");
const u8 String_09EB[] = _("<LABEL=B_DJUNGO></LABEL><PROC=1><LOCK=42>ボクらの・・・」");
const u8 String_09EC[] = _("<PROC=0>\n<END>");
const u8 String_09ED[] = _("<PROC=2><LOCK=176>太陽の力を取り戻した!!");
const u8 String_09EE[] = _("<PROC=1><LOCK=96>月光魔法「トランス」\nを覚えた!!");
const u8 String_09EF[] = _("トランスは太陽と暗黒、どちら\nの力を使うかを切り換(か)える\nチェンジ(変身)魔法だ。");
const u8 String_09F0[] = _("太陽状態である赤<NAME>\nなら、太陽少年としての能力を");
const u8 String_09F1[] = _("暗黒状態である黒<NAME>\nなら、ヴァンパイアとしての能\n力を使うことができる。");
const u8 String_09F2[] = _("<PROC=1><LOCK=96>月光魔法「ライジングサン」\nを覚えた!!");
const u8 String_09F3[] = _("ライジングサンは太陽の欠片を\n呼び出す召喚(しょうかん)魔法\nだ。");
const u8 String_09F4[] = _("ライジングサンを使えば、しば\nらくの間、その場を太陽の光で\n満たすことができる。");
const u8 String_09F5[] = _("<PROC=0>\n<END>");
const u8 String_09F6[] = _("<LABEL=ZAJI>ザジ</LABEL>\n「ほんま、\nびびらせるんやないで・・・」");
const u8 String_09F7[] = _("<LABEL=SMITH>スミス</LABEL>\n「まったく、\n心配させよって!!」");
const u8 String_09F8[] = _("<PROC=0>\n<END>");
const u8 String_09F9[] = _("<LABEL=SUMIRE>スミレ</LABEL>\n「良かったね、\nおにいちゃん♪」");
const u8 String_09FA[] = _("<PROC=0>\n<END>");
const u8 String_09FB[] = _("<LABEL=KID>キッド</LABEL>\n「オマエがいないと、\nこの街もつまんね―からな」");
const u8 String_09FC[] = _("<LABEL=SHAIAN>シャイアン</LABEL>\n「信じていたぞ、\n太陽少年<NAME>!!」");
const u8 String_09FD[] = _("<PROC=0>\n<END>");
const u8 String_09FE[] = _("<LABEL=RITA>リタ</LABEL>\n「<NAME>さま!!\nわたし・・・");
const u8 String_09FF[] = _("グズッ");
const u8 String_0A00[] = _("・・・ごめんなざい」");
const u8 String_0A01[] = _("<PROC=0>\n<END>");
const u8 String_0A02[] = _("<LABEL=SABATA>サバタ</LABEL>\n「やれやれだな・・・」");
const u8 String_0A03[] = _("<PROC=0>\n<END>");
const u8 String_0A04[] = _("<LABEL=RITA>リタ</LABEL>\n「暗黒樹が消えた今、");
const u8 String_0A05[] = _("吸血変異に侵(おか)されたこの\n街にもようやく、希望の光が差\nし込(こ)みました。");
const u8 String_0A06[] = _("<PROC=0>\n<END>");
const u8 String_0A07[] = _("<LABEL=RITA></LABEL>見てください。\n太陽樹さまの芽がもうこんなに\n・・・");
const u8 String_0A08[] = _("<PROC=0>\n<END>");
const u8 String_0A09[] = _("<LABEL=RITA></LABEL>太陽樹さまもお喜びですわ」");
const u8 String_0A0A[] = _("<PROC=0>\n<END>");
const u8 String_0A0B[] = _("<LABEL=R_DJUNGO><NAME></LABEL>\n(ドゥラスロ―ル!?)");
const u8 String_0A0C[] = _("<PROC=0>\n<END>");
const u8 String_0A0D[] = _("大地の祝福を得た!!");
const u8 String_0A0E[] = _("<PROC=0>\n<END>");
const u8 String_0A0F[] = _("<PROC=1><LOCK=96>太陽魔法「ヒ―リング」\nを覚えた!!");
const u8 String_0A10[] = _("ヒ―リングは目の前の植物に元\n気をあたえる回復魔法だ。");
const u8 String_0A11[] = _("回復力は太陽ゲ―ジの値に比例\nする。");
const u8 String_0A12[] = _("<PROC=0>\n<END>");
const u8 String_0A13[] = _("<LABEL=RITA>リタ</LABEL>\n「今はまだ小さいけれど・・・\nこの新しい太陽樹さまと、");
const u8 String_0A14[] = _("太陽と大地のある限り・・・\n人がその恩恵(おんけい)を忘れ\nない限り、");
const u8 String_0A15[] = _("いつまでも、共に支えあって生\nきていくことができるはずです");
const u8 String_0A16[] = _("たとえこの世界が世紀末の輪廻\n(りんね)にあろうとも・・・」");
const u8 String_0A17[] = _("<PROC=0>\n<END>");
const u8 String_0A18[] = _("<LABEL=SABATA>サバタ</LABEL>\n「どうだ?");
const u8 String_0A19[] = _("例のヴァンパイアの行方は分か\nったか?」");
const u8 String_0A1A[] = _("<PROC=0>\n<END>");
const u8 String_0A1B[] = _("<LABEL=ZAJI>ザジ</LABEL>\n「あかんねん・・・");
const u8 String_0A1C[] = _("おてんこさまもリンゴさまも、\n黒い雲に隠(かく)されたまんま\nや・・・");
const u8 String_0A1D[] = _("相変わらずうちの星読みは役立\nたずやな。");
const u8 String_0A1E[] = _("病み上がりのあんたらががんば\nってるっちゅうのに、うちは何\nもできへん。");
const u8 String_0A1F[] = _("あのヴァンパイアがリンゴさま\nやったことにも、気ぃつかへん\nかったやなんて・・・");
const u8 String_0A20[] = _("こんなん、ばばあに合わせる顔\nないわ・・・」");
const u8 String_0A21[] = _("<LABEL=SABATA>サバタ</LABEL>\n「後悔(こうかい)なら後にしろ");
const u8 String_0A22[] = _("できることがないだと?\n笑わせるな!!");
const u8 String_0A23[] = _("この太陽街に張られた結界、");
const u8 String_0A24[] = _("それがなければ、この街は当の\n昔に敵モンスタ―の侵入(しん\nにゅう)を許していた。");
const u8 String_0A25[] = _("これほどの結界、おまえの他に\nいったい誰(だれ)が維持(いじ)\nできるというのだ?");
const u8 String_0A26[] = _("伝説の魔女の弟子であるおまえ\nの他に」");
const u8 String_0A27[] = _("<LABEL=ZAJI>ザジ</LABEL>\n「うちにしか・・・\nできへんこと?");
const u8 String_0A28[] = _("<PROC=0>\n<END>");
const u8 String_0A29[] = _("<LABEL=ZAJI></LABEL>そや、うちにもできることが、\nやるべきことがあるんや・・・");
const u8 String_0A2A[] = _("この街に張られた結界、");
const u8 String_0A2B[] = _("それを守り、この街の人たちを\n・・・まだ幼い太陽樹を守った\nること、");
const u8 String_0A2C[] = _("それは今、\nうちにしかできへん!!");
const u8 String_0A2D[] = _("たとえ雨が降っても、");
const u8 String_0A2E[] = _("<PROC=4><LOCK=72>ひまわりはうつむかへん!");
const u8 String_0A2F[] = _("<NAME>にそう言ったんは\nうちやったのに・・・\n何を今さらいじけとんねん!」");
const u8 String_0A30[] = _("<LABEL=SABATA>サバタ</LABEL>\n「まったくだな。");
const u8 String_0A31[] = _("ひまわり娘(むすめ)が聞いてあ\nきれる」");
const u8 String_0A32[] = _("<LABEL=ZAJI>ザジ</LABEL>\n「ふんっ!");
const u8 String_0A33[] = _("あんなばばあといっしょにせん\nといて!!");
const u8 String_0A34[] = _("うちにはザジっちゅう自分の名\n前があんねん。");
const u8 String_0A35[] = _("ばばあと同じにはできへんけど\nうちはうちや。うちのせいいっ\nぱいをやればええんや!」");
const u8 String_0A36[] = _("<LABEL=SABATA>サバタ</LABEL>\n<PROC=1><LOCK=20>「フッ・・・");
const u8 String_0A37[] = _("<PROC=2><LOCK=63>フッハッハッハッハッ!!」");
const u8 String_0A38[] = _("<LABEL=ZAJI>ザジ</LABEL>\n<PROC=3><LOCK=47>「にゃはははは!!」");
const u8 String_0A39[] = _("<PROC=0>\n<END>");
const u8 String_0A3A[] = _("<LABEL=SABATA>サバタ</LABEL>\n「おい、ひまわり。\nのどちんこが見えてるぞ?」");
const u8 String_0A3B[] = _("<LABEL=ZAJI>ザジ</LABEL>\n「ふにゃ!?」");
const u8 String_0A3C[] = _("<PROC=0>\n<END>");
const u8 String_0A3D[] = _("<LABEL=NONE>ザジ</LABEL>\n「んにゃ――――――っ!!」");
const u8 String_0A3E[] = _("<PROC=0>\n<END>");
const u8 String_0A3F[] = _("<LABEL=RINGO2>リンゴ</LABEL>\n「<NAME>!?");
const u8 String_0A40[] = _("ドゥラスロ―ルを倒(たお)した\nか・・・");
const u8 String_0A41[] = _("おまけに太陽の力を取り戻(も\nど)し、暗黒の力をも失ってい\nないとは・・・");
const u8 String_0A42[] = _("・・・");
const u8 String_0A43[] = _("それにしても、よくここが分か\nったな?");
const u8 String_0A44[] = _("<PROC=0>\n<END>");
const u8 String_0A45[] = _("<LABEL=RINGO2></LABEL>ダ―インはこの奥だ・・・");
const u8 String_0A46[] = _("あと一歩のところで、扉(とび\nら)の向こうに逃(に)げられて\nしまった。");
const u8 String_0A47[] = _("この奥にはおそらく、例のくさ\nびの封印(ふういん)があるに違\n(ちが)いない。");
const u8 String_0A48[] = _("くさびが破壊(はかい)されれば\nまた新たなイモ―タルが復活し\nてしまう。");
const u8 String_0A49[] = _("その前にヤツを倒さなければな\nらない。");
const u8 String_0A4A[] = _("それにはまず、このタロット封\n印を何とかしなければ・・・」");
const u8 String_0A4B[] = _("<PROC=0>\n<END>");
const u8 String_0A4C[] = _("<LABEL=RINGO2>リンゴ</LABEL>\n「確かに並のイモ―タルに、こ\nの封印を破ることはできまい。");
const u8 String_0A4D[] = _("だがヤツは影(かげ)のイモ―タ\nル・・・");
const u8 String_0A4E[] = _("目に見えないほどの隙間(すき\nま)からでも侵入(しんにゅう)\nできるようだ。");
const u8 String_0A4F[] = _("タロット封印を解くには、3賢\n者(けんじゃ)のカ―ドが必要だ");
const u8 String_0A50[] = _("俺(おれ)はこの場を離(はな)れ\nるわけにはいかん。");
const u8 String_0A51[] = _("<NAME>、\n3賢者のカ―ドを探して来てく\nれ!!");
const u8 String_0A52[] = _("カ―ドを探すのに役立つかもし\nれん・・・\nこれを渡(わた)しておこう」");
const u8 String_0A53[] = _("<PROC=0>\n<END>");
const u8 String_0A54[] = _("<PROC=1>太陽銃レンズ「ア―ス」\nを取り戻した!");
const u8 String_0A55[] = _("<PROC=0>\n<END>");
const u8 String_0A56[] = _("<PROC=2><LOCK=96>月光魔法\n「エンチャント・ア―ス」\nを覚えた!!");
const u8 String_0A57[] = _("<PROC=0>\n<END>");
const u8 String_0A58[] = _("<LABEL=NONE>???</LABEL>\n「待て、<NAME>!!\nそいつは親父ではない!」");
const u8 String_0A59[] = _("<PROC=0>\n<END>");
const u8 String_0A5A[] = _("<LABEL=RINGO2>リンゴ</LABEL>\n<PROC=1><LOCK=25>「遅(おそ)い!!」");
const u8 String_0A5B[] = _("<PROC=0>\n<END>");
const u8 String_0A5C[] = _("3賢者のカ―ドを使った!");
const u8 String_0A5D[] = _("<PROC=0>\n<END>");
const u8 String_0A5E[] = _("扉が開いた!!");
const u8 String_0A5F[] = _("<PROC=0>\n<END>");
const u8 String_0A60[] = _("<LABEL=SABATA>サバタ</LABEL>\n「行かせるか!!」");
const u8 String_0A61[] = _("<PROC=0>\n<END>");
const u8 String_0A62[] = _("<LABEL=NONE>リンゴの声</LABEL>\n「ありがとう、<NAME>。");
const u8 String_0A63[] = _("これで最後のくさびにたどり着\nくことができる。");
const u8 String_0A64[] = _("ささやかだが礼を用意しておい\nた。存分に味わってくれ。");
const u8 String_0A65[] = _("<PROC=1><LOCK=3>ハッハッハッ・・・!!」");
const u8 String_0A66[] = _("<LABEL=SABATA>サバタ</LABEL>\n「チッ・・・!!」");
const u8 String_0A67[] = _("<PROC=0>\n<END>");
const u8 String_0A68[] = _("<LABEL=RINGO2>リンゴ</LABEL>\n「遅(おそ)かったな、\n<NAME>?");
const u8 String_0A69[] = _("そんなことでは俺(おれ)を超(\nこ)えることはできんぞ?\n<PROC=1><LOCK=76>ハッハッハッ・・・!!」");
const u8 String_0A6A[] = _("<PROC=0>\n<END>");
const u8 String_0A6B[] = _("<LABEL=SABATA>サバタ</LABEL>\n「いいかげんに本当の姿を現し\nたらどうだ。");
const u8 String_0A6C[] = _("・・・黒のダ―イン!!」");
const u8 String_0A6D[] = _("<LABEL=RINGO2>リンゴ</LABEL>\n「本当の姿?\n本当の姿とは何だ?");
const u8 String_0A6E[] = _("そんなものは幻想(げんそう)さ\n・・・");
const u8 String_0A6F[] = _("人はそのときそのときで、都合\nのいい自分を演じる。");
const u8 String_0A70[] = _("好きな相手にはシッポを振(ふ\n)り、嫌(きら)いな相手にはク\nビを振る。");
const u8 String_0A71[] = _("太陽と暗黒を使い分けるように\nね・・・\nそうだろ、<NAME>?");
const u8 String_0A72[] = _("影(かげ)そのものであるボクに\nは、本当の姿などない。");
const u8 String_0A73[] = _("だからこうやって・・・\n他人の身体を借りることもでき\nる!!」");
const u8 String_0A74[] = _("<PROC=0>\n<END>");
const u8 String_0A75[] = _("<LABEL=RINGO3>黒のダ―イン</LABEL>\n「イモ―タルの宿敵にしてキミ\nたちの父親、紅のリンゴ・・・");
const u8 String_0A76[] = _("ヴァンパイアとなった彼(かれ)\nの身体は、実によくなじむよ!\n<PROC=1><LOCK=76>ハッハッハッ・・・!!」");
const u8 String_0A77[] = _("<LABEL=SABATA>サバタ</LABEL>\n<PROC=3>「・・・外道が!!」");
const u8 String_0A78[] = _("<LABEL=RINGO3>黒のダ―イン</LABEL>\n「キミにそんなことを言われる\nなんて心外だな。");
const u8 String_0A79[] = _("暗黒に染まりきったキミが、今\nさら銀河意思を裏切ってどうす\nる?」");
const u8 String_0A7A[] = _("<LABEL=SABATA>サバタ</LABEL>\n「裏切る?");
const u8 String_0A7B[] = _("<PROC=2>フンッ、\nたとえこの身がダ―クマタ―に\n侵(おか)されていようとも、");
const u8 String_0A7C[] = _("<PROC=3>俺はどこにも属さない!\n何者にも支配されない!");
const u8 String_0A7D[] = _("それが銀河意思ダ―クであって\nもな!!」");
const u8 String_0A7E[] = _("<LABEL=RINGO3>黒のダ―イン</LABEL>\n「ダ―クの意思はボクが実行す\nる・・・");
const u8 String_0A7F[] = _("受け継(つ)いだはずの2つの血\nそのどちらをも使えない、でき\n損ないの暗黒仔(あんこくし)。");
const u8 String_0A80[] = _("キミにもう、用はない」");
const u8 String_0A81[] = _("<LABEL=SABATA>サバタ</LABEL>\n「でき損ない・・・\n結構じゃないか。");
const u8 String_0A82[] = _("かつてはこの俺も完全であるこ\nとを求めた。完全なる力を。");
const u8 String_0A83[] = _("だが、人には不完全であるがゆ\nえに持ち得るモノがある!");
const u8 String_0A84[] = _("・・・そうありたいと願うこと\nその想いの力・・・");
const u8 String_0A85[] = _("不完全であればこそ、\nその未来には可能性がある!\n希望がある!!");
const u8 String_0A86[] = _("自分というものを持たないおま\nえには、とうてい理解できまい\nがな」");
const u8 String_0A87[] = _("<LABEL=RINGO3>黒のダ―イン</LABEL>\n「キミに希望などないよ・・・");
const u8 String_0A88[] = _("銀河意思に逆らってどうなる?");
const u8 String_0A89[] = _("勝ち目があるとでも?」");
const u8 String_0A8A[] = _("<LABEL=SABATA>サバタ</LABEL>\n<PROC=2>「フッ・・・");
const u8 String_0A8B[] = _("<PROC=3>相手はすべての生命の起源たる\n銀河宇宙の意思、ダ―ク。\n始めから勝ち目などない。");
const u8 String_0A8C[] = _("この星は無限の死に囲まれてい\nる・・・");
const u8 String_0A8D[] = _("・・・人は死ぬ。");
const u8 String_0A8E[] = _("だが俺は・・・\nその結果になど興味はない。");
const u8 String_0A8F[] = _("・・・すべてはどう生きるかだ");
const u8 String_0A90[] = _("あらがい、戦い続けること。\nそれが俺の・・・\n生きるということだ!!」");
const u8 String_0A91[] = _("<LABEL=RINGO3>黒のダ―イン</LABEL>\n「では戦って死ぬんだね・・・");
const u8 String_0A92[] = _("<NAME>、\nキミとはもう少しゆっくりと話\nがしたいな。");
const u8 String_0A93[] = _("でも今はあきらめるとするよ。");
const u8 String_0A94[] = _("・・・4人目は目覚めた。\nこの身体があればあの塔に入る\nこともできる・・・");
const u8 String_0A95[] = _("キミたちの相手はドヴァリンに\nゆずるとしよう。");
const u8 String_0A96[] = _("こいつも用済みだ・・・\n返しておくよ」");
const u8 String_0A97[] = _("<PROC=0>\n<END>");
const u8 String_0A98[] = _("<LABEL=PLAYER><NAME></LABEL>\n(クロ・・・!!)");
const u8 String_0A99[] = _("<PROC=0>\n<END>");
const u8 String_0A9A[] = _("<LABEL=SABATA>サバタ</LABEL>\n「<NAME>!!」");
const u8 String_0A9B[] = _("<LABEL=RINGO3>黒のダ―イン</LABEL>\n<PROC=1><LOCK=85>「ハッハッハッ・・・!!」");
const u8 String_0A9C[] = _("<PROC=0>\n<END>");
const u8 String_0A9D[] = _("<LABEL=DVALINN>青いシルエットの女</LABEL>\n「サバタには逃(に)げられたか\n・・・");
const u8 String_0A9E[] = _("まあいい。あやつ1人なら兄さ\nまが何とでもなさるだろう。");
const u8 String_0A9F[] = _("こちらはこちらで楽しもうじゃ\nないか。");
const u8 String_0AA0[] = _("おまえには子供たちが世話にな\nったみたいだからね・・・");
const u8 String_0AA1[] = _("私は青きドヴァリン。\n海を支配するイモ―タル」");
const u8 String_0AA2[] = _("<PROC=0>\n<END>");
const u8 String_0AA3[] = _("<LABEL=NONE>サバタの声</LABEL>\n「しっかりしろ、\n<NAME>!!");
const u8 String_0AA4[] = _("<PROC=0>\n<END>");
const u8 String_0AA5[] = _("<LABEL=NONE></LABEL>そいつの始末は任せたぞ!\n俺はヤツを追う!!」");
const u8 String_0AA6[] = _("<PROC=0>\n<END>");
const u8 String_0AA7[] = _("<LABEL=LADY>???</LABEL>\n「誰(だれ)かと思えば・・・");
const u8 String_0AA8[] = _("あなただったの、\n<NAME>くん。");
const u8 String_0AA9[] = _("私の仕掛(しか)けを突破(とっ\nぱ)するなんて、");
const u8 String_0AAA[] = _("さすがに死の都から生還(せい\nかん)しただけはあるわね。");
const u8 String_0AAB[] = _("私のこと、覚えてる?\n図書館の司書、レディよ」");
