const u8 String_0AAD[] = _(" <ALTER>覚えてる</ALTER>　<ALTER>知らない</ALTER>");
const u8 String_0AAE[] = _("<PROC=0>\n<END>");
const u8 String_0AAF[] = _("<LABEL=LADY>レディ</LABEL>\n「いい子ね♪");
const u8 String_0AB0[] = _("ところでそのカ―ド、\nどうするつもり?");
const u8 String_0AB1[] = _("それはこの街の水源を守るため\nの大事なもの・・・");
const u8 String_0AB2[] = _("たとえあなたが太陽少年だとし\nても、勝手に持って行かれると\n困るのよね?」");
const u8 String_0AB3[] = _("<PROC=0>\n<END>");
const u8 String_0AB4[] = _("<LABEL=LADY>レディ</LABEL>\n「あら、残念ね・・・");
const u8 String_0AB5[] = _("ところでそのカ―ド、\nどうするつもり?");
const u8 String_0AB6[] = _("それはこの街の水源を守るため\nの大事なもの・・・");
const u8 String_0AB7[] = _("たとえあなたが太陽少年だとし\nても、勝手に持って行かれると\n困るのよね?」");
const u8 String_0AB8[] = _("<PROC=0>\n<END>");
const u8 String_0AB9[] = _("<LABEL=LADY>レディ</LABEL>\n「タロット封印(ふういん)をす\nり抜(ぬ)けるなんて・・・");
const u8 String_0ABA[] = _("たとえどんなイモ―タルであっ\nても、そんなことはできないは\nずなのに・・・");
const u8 String_0ABB[] = _("いいわ、あなたを信じましょう");
const u8 String_0ABC[] = _("ただし、必ずそのイモ―タルを\n倒(たお)すのよ?");
const u8 String_0ABD[] = _("リタちゃんが太陽樹を復活させ\nたようだから、");
const u8 String_0ABE[] = _("水源の方はもう大丈夫(だいじ\nょうぶ)だと思うけど・・・");
const u8 String_0ABF[] = _("シャイアンが言ってたことが気\nになるわ。");
const u8 String_0AC0[] = _("・・・太陽街にも人が集まって\nきたようだし、私もそろそろ戻\n(もど)ろうかしら。");
