const u8 String_0AC2[] = _("じゃあまたね。\nイモ―タルの件は任せたわよ」");
const u8 String_0AC3[] = _("<PROC=0>\n<END>");
const u8 String_0AC4[] = _("<LABEL=ZAJI>ザジ</LABEL>\n「<NAME>!!");
const u8 String_0AC5[] = _("すぐに螺旋(らせん)の塔に来い\n・・・て、サバタからの伝言や");
const u8 String_0AC6[] = _("塔は太陽街の北、拾弍番街(じ\nゅうにばんがい)の先にある約\n束の丘に立っとる。");
const u8 String_0AC7[] = _("塔への道を閉ざしとった四方封\n印(しほうふういん)は、すでに\n破られてしもた・・・");
const u8 String_0AC8[] = _("くれぐれも気ぃつけてな。");
const u8 String_0AC9[] = _("あの塔はイモ―タルにとっても\n本来近づいたらあかんはずの場\n所や。");
const u8 String_0ACA[] = _("嫌(いや)な予感がすんねん\n・・・");
const u8 String_0ACB[] = _("・・・それから、\nリンゴさまを救ったげてな。");
const u8 String_0ACC[] = _("あんたのとうちゃんや、\nうちから頼(たの)むようなこと\nやないけど・・・");
const u8 String_0ACD[] = _("でもそれが、うちの師匠(しし\nょう)の、ばばあの最後の願い\nなんや・・・」");
const u8 String_0ACE[] = _("<PROC=0>\n<END>");
const u8 String_0ACF[] = _("<LABEL=SABATA>サバタ</LABEL>\n「ここが最上階・・・だが、");
const u8 String_0AD0[] = _("<PROC=0>\n<END>");
const u8 String_0AD1[] = _("<LABEL=SABATA></LABEL>・・・行き止まりか?");
const u8 String_0AD2[] = _("いや、\n2つの重量スイッチ・・・");
const u8 String_0AD3[] = _("<NAME>を待つしかないか」");
const u8 String_0AD4[] = _("<PROC=0>\n<END>");
const u8 String_0AD5[] = _("<LABEL=SABATA>サバタ</LABEL>\n「<NAME>、");
const u8 String_0AD6[] = _("おそらくダ―インはこの先にい\nる。今度こそヤツとの決着をつ\nけるぞ。");
const u8 String_0AD7[] = _("だがその前に、おまえに言って\nおくことがある。");
const u8 String_0AD8[] = _("ダ―インは親父の身体を乗っ取\nった。では親父の魂(たましい)\nはどうなったのか・・・");
const u8 String_0AD9[] = _("すでに闇(やみ)に沈(しず)んで\nしまったのか?");
const u8 String_0ADA[] = _("それとも内なる抵抗(ていこう)\nを続けているのか?");
const u8 String_0ADB[] = _("どちらにせよ手加減をして勝て\nる相手ではない。");
const u8 String_0ADC[] = _("いいか、\n全力でヤツを倒(たお)すんだ!!");
const u8 String_0ADD[] = _("間違(まちが)っても親父を助け\nようなどと思うなよ?」");
const u8 String_0ADE[] = _("<PROC=0>\n<END>");
const u8 String_0ADF[] = _("<LABEL=SABATA>サバタ</LABEL>\n「行くぞ!!」");
const u8 String_0AE0[] = _("<PROC=0>\n<END>");
const u8 String_0AE1[] = _("<LABEL=RINGO3>黒きダ―イン</LABEL>\n「やはりドヴァリンでは足止め\nがいいところか・・・");
const u8 String_0AE2[] = _("しかしその役目は十分に果たし\nてくれた。");
const u8 String_0AE3[] = _("いましめの槍(やり)は今、引き\n抜(ぬ)かれようとしている」");
const u8 String_0AE4[] = _("<PROC=0>\n<END>");
const u8 String_0AE5[] = _("<LABEL=RINGO3>黒きダ―イン</LABEL>\n<PROC=1><LOCK=57>「クックックッ・・・");
const u8 String_0AE6[] = _("これで真なる暗黒仔(あんこく\nし)としてのボクの使命も果た\nされた!");
const u8 String_0AE7[] = _("<PROC=2><LOCK=85>ハッハッハッ・・・!!」");
const u8 String_0AE8[] = _("<LABEL=SABATA>サバタ</LABEL>\n「貴様・・・\nいったい何をした!?」");
const u8 String_0AE9[] = _("<PROC=0>\n<END>");
const u8 String_0AEA[] = _("<LABEL=RINGO3>黒きダ―イン</LABEL>\n「やはり何も知らなかったか。");
const u8 String_0AEB[] = _("おてんこを封(ふう)じ込(こ)め\nたのは正解だったようだね。");
const u8 String_0AEC[] = _("太陽の街、サン・ミゲルはただ\nの街ではない。");
const u8 String_0AED[] = _("この街の地下に眠るのはかつて\nの太陽都市・・・");
const u8 String_0AEE[] = _("今は亡き太陽の一族、太陽仔(\nたいようし)が築いた天空都市");
const u8 String_0AEF[] = _("その1つが地上に落とされた。\nそれには当然、理由がある」");
const u8 String_0AF0[] = _("<LABEL=SABATA>サバタ</LABEL>\n「封印・・・」");
const u8 String_0AF1[] = _("<LABEL=RINGO3>黒きダ―イン</LABEL>\n「察しがいいね。");
const u8 String_0AF2[] = _("そう、太陽都市を地上に落とす\nそうまでして封印しなければな\nらなかったもの、");
const u8 String_0AF3[] = _("それが終末の獣(けもの)・・・\nヨルムンガンド。");
const u8 String_0AF4[] = _("イモ―タルさえも恐(おそ)れる\n原種、その欠片・・・」");
const u8 String_0AF5[] = _("<LABEL=SABATA>サバタ</LABEL>\n「原種の欠片?」");
const u8 String_0AF6[] = _("<LABEL=RINGO3>黒きダ―イン</LABEL>\n「伯爵(はくしゃく)がこの街を\n襲(おそ)ったのも、");
const u8 String_0AF7[] = _("もちろん計画の内さ。");
const u8 String_0AF8[] = _("もっとも、ヘルの元に送り込ん\nだスパイのはずであった彼(か\nれ)が、");
const u8 String_0AF9[] = _("あの女に同調して、ボクらから\n離反(りはん)してしまったのは\n予定外だったがね。");
const u8 String_0AFA[] = _("ヘルごときがクイ―ンだなんて\n悪い冗談(じょうだん)だよ」");
const u8 String_0AFB[] = _("<PROC=0>\n<END>");
const u8 String_0AFC[] = _("<LABEL=SABATA>サバタ</LABEL>\n「いましめの槍と言ったな?\nではこの塔が・・・」");
const u8 String_0AFD[] = _("<LABEL=RINGO3>黒きダ―イン</LABEL>\n「ご名答。");
const u8 String_0AFE[] = _("4つのくさびと3つの血によって\n守られた巨大な槍。ヨルムンガ\nンドをいましめる封印の塔。");
const u8 String_0AFF[] = _("それがこの螺旋(らせん)の塔さ\n<PROC=1><LOCK=57>クックックッ・・・」");
const u8 String_0B00[] = _("<LABEL=SABATA>サバタ</LABEL>\n<PROC=2><LOCK=20>「フンッ!!");
const u8 String_0B01[] = _("この塔がいましめの槍だという\nのなら、もう1度突(つ)き刺(さ\n)せばいいだけのこと!");
const u8 String_0B02[] = _("まだ槍は抜けきってはいない!!\n」");
const u8 String_0B03[] = _("<LABEL=RINGO3>黒きダ―イン</LABEL>\n「そう、まだ遅(おそ)くはない");
const u8 String_0B04[] = _("<NAME>、今一度問う。\nボクたちの同志になるんだ!\nボクらの黒き太陽に!!");
const u8 String_0B05[] = _("今、この世界は世紀末の輪廻(\nりんね)の最中にある。くり返\nされる生と死の輪廻・・・");
const u8 String_0B06[] = _("他者を傷つけ、自らも傷つき、\n世界さえをも傷つける生命種、\nゆるされざる者ども・・・");
const u8 String_0B07[] = _("その傷はこの星を、太陽系を、\nそしていずれは、銀河宇宙その\nものをも傷つける。");
const u8 String_0B08[] = _("誰(だれ)かが止めなければなら\nない。");
const u8 String_0B09[] = _("それができるのは、闇(やみ)の\n一族、イモ―タルのみ・・・");
const u8 String_0B0A[] = _("人がアンデッドとしての永遠を\n拒(こば)むのなら、");
const u8 String_0B0B[] = _("世紀末の終焉(しゅうえん)と共\nに無に、原種の元に還(かえ)っ\nてもらうしかない。");
const u8 String_0B0C[] = _("キミになら分かるだろう?");
const u8 String_0B0D[] = _("さあ<NAME>、\n共にこの世界を、許されざる者\nたちの手から解放しよう!!」");
const u8 String_0B0E[] = _("<PROC=0>\n<END>");
const u8 String_0B0F[] = _(" <ALTER>同志になる</ALTER>　<ALTER>断る!!</ALTER>");
const u8 String_0B10[] = _("<PROC=0>\n<END>");
const u8 String_0B11[] = _("<LABEL=SABATA>サバタ</LABEL>\n「愚問(ぐもん)だったな!\n行くぞ、<NAME>!!");
const u8 String_0B12[] = _("こいつを倒(たお)し、\n塔の封印を戻(もど)す!");
const u8 String_0B13[] = _("親父も・・・\nそれを望んでいるはずだ!!」");
const u8 String_0B14[] = _("<PROC=0>\n<END>");
const u8 String_0B15[] = _("<LABEL=SABATA>サバタ</LABEL>\n「バカな!?");
const u8 String_0B16[] = _("<NAME>・・・」");
const u8 String_0B17[] = _("<LABEL=RINGO3>黒きダ―イン</LABEL>\n<PROC=1><LOCK=85>「ハッハッハッ・・・!!」");
const u8 String_0B18[] = _("<PROC=0>\n<END>");

const u8 String_0B19[] = _("<LABEL=RINGO3>黒きダ―イン</LABEL>\n「ボクが・・・");
const u8 String_0B1A[] = _("真なる暗黒仔(あんこくし)たる\nこのボクが・・・なぜ・・・?\n」");
const u8 String_0B1B[] = _("<LABEL=SABATA>サバタ</LABEL>\n「まだ気がつかないのか?");
const u8 String_0B1C[] = _("おまえも俺(おれ)と同じ・・・");
const u8 String_0B1D[] = _("ダ―クに利用された、ただの捨\nてゴマだということに!!」");
const u8 String_0B1E[] = _("<LABEL=RINGO3>黒きダ―イン</LABEL>\n「バカ・・・な・・・");
const u8 String_0B1F[] = _("リンゴの魂(たましい)も・・・\n完全に闇(やみ)に沈(しず)めた\nはず・・・だったのに・・・」");
const u8 String_0B20[] = _("<LABEL=PLAYER><NAME></LABEL>\n<PROC=1><LOCK=69>「明日もまた日は昇(のぼ)る!");
const u8 String_0B21[] = _("太陽は沈もうとも・・・\n必ずまた、昇るんだ!!」");
const u8 String_0B22[] = _("<PROC=0>\n<END>");

const u8 String_0B23[] = _("<LABEL=SABATA>サバタ</LABEL>\n「これで塔は・・・\nいましめの槍(やり)は元通りだ");
const u8 String_0B24[] = _("あとは・・・終末の獣(けもの)\nとやらがどうなったのか・・・\nそれを確かめねばならん。");
const u8 String_0B25[] = _("<NAME>、\nおまえはそいつを浄化(じょう\nか)するんだ。");
const u8 String_0B26[] = _("親父を・・・\n弔(とむら)ってやってくれ」");
const u8 String_0B27[] = _("<PROC=0>\n<END>");
const u8 String_0B28[] = _("<LABEL=RINGO3>黒きダ―イン</LABEL>\n「嫌(いや)だ・・・");
const u8 String_0B29[] = _("こんな身体に閉じ込(こ)められ\nて、");
const u8 String_0B2A[] = _("ボクは・・・消えたくない!");
const u8 String_0B2B[] = _("助けて、<NAME>・・・");
const u8 String_0B2C[] = _("ボクと・・・1つに!!」");
const u8 String_0B2D[] = _("<PROC=0>\n<END>");
const u8 String_0B2E[] = _("<LABEL=PLAYER><NAME></LABEL>\n「ボクは生きる・・・");
const u8 String_0B2F[] = _("<LABEL=PLAYER></LABEL>限りある命をせいいっぱいに。");
const u8 String_0B30[] = _("生きることをあきらめて永遠を\n手に入れても、");
const u8 String_0B31[] = _("太陽のあたたかさは分からない\n・・・");
const u8 String_0B32[] = _("命のあたたかさは分からない!!");
const u8 String_0B33[] = _("<PROC=0>\n<END>");
const u8 String_0B34[] = _("<LABEL=PLAYER></LABEL>そうだよね・・・\nおとうさん!!」");
const u8 String_0B35[] = _("<PROC=0>\n<END>");
const u8 String_0B36[] = _("<LABEL=RINGO2>リンゴ</LABEL>\n「・・・その通りだ!!");
const u8 String_0B37[] = _("たとえこの身が消えようと、\nそれでも・・・");
const u8 String_0B38[] = _("<PROC=1><LOCK=71>明日もまた日は昇(のぼ)る!");
const u8 String_0B39[] = _("人は成長し、進化する!\nそれは決して、\n滅(ほろ)びへの道ではない!!");
const u8 String_0B3A[] = _("生きろよ、<NAME>!!");
const u8 String_0B3B[] = _("おてんこ・・・\n息子たちを頼(たの)んだぞ!」");
const u8 String_0B3C[] = _("<LABEL=RINGO3>黒きダ―イン</LABEL>\n「やめろ!\n・・・リンゴ!!」");
const u8 String_0B3D[] = _("<PROC=0>\n<END>");
const u8 String_0B3E[] = _("<LABEL=PLAYER><NAME></LABEL>\n(さようなら、\nおとうさん・・・)");
const u8 String_0B3F[] = _("<PROC=0>\n<END>");
const u8 String_0B40[] = _("<LABEL=NONE></LABEL>太陽銃が残された・・・");
const u8 String_0B41[] = _("<PROC=0>\n<END>");
const u8 String_0B42[] = _("<LABEL=ZAJI>ザジ</LABEL>\n「<NAME>、今のは・・・");
const u8 String_0B43[] = _("・・・");
const u8 String_0B44[] = _("リンゴさま・・・」");
const u8 String_0B45[] = _("<PROC=0>\n<END>");
const u8 String_0B46[] = _("<LABEL=ZAJI>ザジ</LABEL>\n「原種の欠片、\nヨルムンガンド・・・");
const u8 String_0B47[] = _("それが終末の獣(けもの)の正体\nやったんか・・・");
const u8 String_0B48[] = _("原種というんは生命の根源たる\n母なる存在。");
const u8 String_0B49[] = _("すべての生命種は原種から生み\n出された種なんや。");
const u8 String_0B4A[] = _("種は成長し、子供を作り、世代\nを越えた進化を続ける。\nそれは生と死の輪廻(りんね)。");
const u8 String_0B4B[] = _("そしてイモ―タルは、生と死を\n止められた反生命種・・・");
const u8 String_0B4C[] = _("静止した時の中で永遠を演じる\n闇(やみ)の一族。");
const u8 String_0B4D[] = _("せやけど、原種の欠片は生命種\nでも反生命種でもない。");
const u8 String_0B4E[] = _("生も死もあたえられず、\nただそこに存在するもの。");
const u8 String_0B4F[] = _("イモ―タルさえも恐(おそ)れる\n絶対存在、エタ―ナル・・・");
const u8 String_0B50[] = _("死を持たへんもんを殺すことは\nできへん。せやから封印(ふう\nいん)されたんや。");
const u8 String_0B51[] = _("まさに終末の獣や。");
const u8 String_0B52[] = _("そんなもんが目ぇ覚ましたら、\nこの世紀末世界もほんまに終わ\nりや。");
const u8 String_0B53[] = _("それが銀河宇宙の意思やったな\nんて・・・」");
const u8 String_0B54[] = _("<PROC=0>\n<END>");
const u8 String_0B55[] = _("<LABEL=ZAJI>ザジ</LABEL>\n「これは・・・!!\nまさかヨルムンガンドが!?");
const u8 String_0B56[] = _("もしそうやとしたら・・・");
const u8 String_0B57[] = _("ああっ!!\nこんなときにおてんこさまがい\nてくれたら!」");
const u8 String_0B58[] = _("<PROC=0>\n<END>");
const u8 String_0B59[] = _("<LABEL=ZAJI>ザジ</LABEL>\n「まさか・・・この子!?」");
const u8 String_0B5A[] = _("<LABEL=NONE>???</LABEL>\n「そうだ、その黒猫(くろねこ)\nがおてんこだ」");
const u8 String_0B5B[] = _("<PROC=0>\n<END>");
const u8 String_0B5C[] = _("<LABEL=SABATA>サバタ</LABEL>\n「かつてのダ―インの身体、");
const u8 String_0B5D[] = _("そして今は、おてんこを封じた\n魂(たましい)の器。\n・・・それがこのクロだ」");
const u8 String_0B5E[] = _("<PROC=0>\n<END>");
const u8 String_0B5F[] = _("<LABEL=SABATA>サバタ</LABEL>\n「終末の獣は目覚めつつある。");
const u8 String_0B60[] = _("その身体は今だ螺旋(らせん)の\n塔に捕(とら)われてはいるが、");
const u8 String_0B61[] = _("それもヨルムンガンドが目覚め\nるまでのこと・・・");
const u8 String_0B62[] = _("おまけにヤツに近づこうにも、\n地下への扉(とびら)は閉ざされ\nたままだ。");
const u8 String_0B63[] = _("太陽と暗黒に続く、3つ目の力\nに守られて・・・」");
const u8 String_0B64[] = _("<LABEL=ZAJI>ザジ</LABEL>\n「月の力、\n月光仔(げっこうし)の力やな」");
const u8 String_0B65[] = _("<LABEL=SABATA>サバタ</LABEL>\n「そうだ。");
const u8 String_0B66[] = _("今の俺(おれ)にその力はないが\n・・・");
const u8 String_0B67[] = _("クロに封(ふう)じ込(こ)められ\nたおてんこの魂を呼び戻(もど)\nすことはできる。");
const u8 String_0B68[] = _("かつてはこの俺も、自身の魂に\nおてんこを封じ込めたことがあ\nるからな。");
const u8 String_0B69[] = _("<PROC=0>\n<END>");
const u8 String_0B6A[] = _("<LABEL=SABATA></LABEL>体力の回復した今のこいつなら\n魂の分離(ぶんり)にも耐(た)え\nられるはず・・・");
const u8 String_0B6B[] = _("行くぞ、クロ!!」");
const u8 String_0B6C[] = _("<PROC=0>\n<END>");
const u8 String_0B6D[] = _("<LABEL=OTENKO>おてんこさま</LABEL>\n「ふう、\nようやく実体化できたか・・・");
const u8 String_0B6E[] = _("助かったぞ、サバタ!!」");
const u8 String_0B6F[] = _("<PROC=0>\n<END>");
const u8 String_0B70[] = _("<LABEL=SABATA>サバタ</LABEL>\n「フンッ、\n別にあんたのためじゃない。");
const u8 String_0B71[] = _("戦わずして負ける、\nそんなのはごめんだからな」");
const u8 String_0B72[] = _("<LABEL=OTENKO>おてんこさま</LABEL>\n「ふっ、");
const u8 String_0B73[] = _("それだけの減らず口が叩(たた)\nけるなら心配はないな」");
const u8 String_0B74[] = _("<LABEL=ZAJI>ザジ</LABEL>\n「おてんこさま、\nヨルムンガンドの封印が!!」");
const u8 String_0B75[] = _("<PROC=0>\n<END>");
const u8 String_0B76[] = _("<LABEL=OTENKO>おてんこさま</LABEL>\n「ああ、状況(じょうきょう)は\n分かっている。");
const u8 String_0B77[] = _("封じ込められたとはいえ、意識\nはクロと共有していたからな」");
const u8 String_0B78[] = _("<LABEL=SABATA>サバタ</LABEL>\n「では何か対策が?」");
const u8 String_0B79[] = _("<PROC=0>\n<END>");
const u8 String_0B7A[] = _("<LABEL=OTENKO>おてんこさま</LABEL>\n「方法は単純だ。");
const u8 String_0B7B[] = _("螺旋の塔の地下深く、ヨルムン\nガンドの頭を叩き、同時に再び\n封印をほどこすのだ」");
const u8 String_0B7C[] = _("<LABEL=SABATA>サバタ</LABEL>\n「だが地下への扉は!!」");
const u8 String_0B7D[] = _("<LABEL=OTENKO>おてんこさま</LABEL>\n「サバタ、");
const u8 String_0B7E[] = _("その問題はすでに解決済みだ」");
const u8 String_0B7F[] = _("<PROC=0>\n<END>");
const u8 String_0B80[] = _("<LABEL=OTENKO>おてんこさま</LABEL>\n「・・・");
const u8 String_0B81[] = _("ヴァンパイアと成りながらも、\n人としての最後を選んだか。");
const u8 String_0B82[] = _("まさに殺しても死なないような\nヤツだったな・・・");
const u8 String_0B83[] = _("・・・さらばだ、\n最強のヴァンパイアハンタ―!\n我が最愛の友、リンゴ!!");
const u8 String_0B84[] = _("おまえの血と魂は・・・");
const u8 String_0B85[] = _("息子たちが確実に受け継(つ)い\nでいるぞ!」");
const u8 String_0B86[] = _("<PROC=0>\n<END>");
const u8 String_0B87[] = _("<LABEL=OTENKO>おてんこさま</LABEL>\n「<NAME>・・・");
const u8 String_0B88[] = _("準備ができしだい螺旋の塔に来\nてくれ。");
const u8 String_0B89[] = _("この戦いにはサン・ミゲルだけ\nでなく、世界そのものの命運が\nかかっている。");
const u8 String_0B8A[] = _("くれぐれも心残りのないように\nな?");
const u8 String_0B8B[] = _("<PROC=1><LOCK=85>太陽と共にあらんことを!」");
const u8 String_0B8C[] = _("<PROC=0>\n<END>");
const u8 String_0B8D[] = _("<LABEL=OTENKO>おてんこさま</LABEL>\n「準備はいいな、\n<NAME>?」");
const u8 String_0B8E[] = _("<PROC=0>\n<END>");
const u8 String_0B8F[] = _("<LABEL=OTENKO>おてんこさま</LABEL>\n「では頼(たの)むぞ、サバタ。");
const u8 String_0B90[] = _("月は太陽の光を映し出す。\nだがそれはただの鏡ではない。");
const u8 String_0B91[] = _("その光は万物の慈愛(じあい)と\n狂気(きょうき)を宿し、");
const u8 String_0B92[] = _("太陽と暗黒、火水風土の4大元\n素、すべての力を操り導く。");
const u8 String_0B93[] = _("導きの力・・・\nそれが月光仔(げっこうし)の力");
const u8 String_0B94[] = _("かつておまえは古の精霊(せい\nれい)、ムスペルとガルムを従\nえ、");
const u8 String_0B95[] = _("私をも封(ふう)じ込(こ)めた。");
const u8 String_0B96[] = _("それは月の暗黒面、狂気の力。");
const u8 String_0B97[] = _("だが今、影(かげ)の牢獄(ろう\nごく)より私を救い出し、");
const u8 String_0B98[] = _("牢獄とされた小さき命までをも\n救ったその力。");
const u8 String_0B99[] = _("それはまぎれもなく月の太陽面\n慈愛の力!");
const u8 String_0B9A[] = _("他者を助けようとするその行為\n(こうい)こそが、おまえを月下\n美人へと導くのだ!");
const u8 String_0B9B[] = _("<PROC=0>\n<END>");
const u8 String_0B9C[] = _("<LABEL=OTENKO></LABEL>月の2面性、慈愛と狂気。\nその表裏を使いこなすものこそ\nが、真なる月下美人となる!!」");
const u8 String_0B9D[] = _("<PROC=0>\n<END>");
const u8 String_0B9E[] = _("<LABEL=SABATA>サバタ</LABEL>\n「聞け、古の精霊よ!");
const u8 String_0B9F[] = _("我らが母、\nその祖先たる月光仔たちよ!");
const u8 String_0BA0[] = _("かつてなんじらが封じたる災い\nが今、解き放たれようとしてい\nる。");
const u8 String_0BA1[] = _("我らの願いは災いの眠(ねむ)り\nなんじらの願いそのもの。");
const u8 String_0BA2[] = _("さればなんじら、そのいましめ\nを今ひととき我に預けよ!");
const u8 String_0BA3[] = _("我はなんじらの子、\n月下美人、サバタなり!!」");
const u8 String_0BA4[] = _("<PROC=0>\n<END>");
const u8 String_0BA5[] = _("<LABEL=OTENKO>おてんこさま</LABEL>\n「大丈夫(だいじょうぶ)か、\nサバタ!!」");
