const u8 String_0BA7[] = _("<LABEL=SABATA>サバタ</LABEL>\n「さすがは終末の獣(けもの)、");
const u8 String_0BA8[] = _("手綱(たづな)をにぎっていると\nいうだけで、これだけのプレッ\nシャ―を受けるとは・・・!!");
