const u8 String_0BF5[] = _("<PROC=0>\n<END>");
const u8 String_0BF6[] = _("<LABEL=ROCKMAN>ロックマン</LABEL>\n「<NAME>くん!!\nまたキミに会えるなんて!");
const u8 String_0BF7[] = _("でもどうしてキミがこのPETを\n・・・?」");
const u8 String_0BF8[] = _("<PROC=0>\n<END>");
const u8 String_0BF9[] = _("<LABEL=ROCKMAN>青い人</LABEL>\n「ボクは熱斗くんのネットナビ\nロックマン!!");
const u8 String_0BFA[] = _("でもどうしてキミがこのPETを\n・・・?」");
const u8 String_0BFB[] = _("<PROC=0>\n<END>");
const u8 String_0BFC[] = _("<LABEL=ROCKMAN>ロックマン</LABEL>\n「<NAME>くん、");
const u8 String_0BFD[] = _("ボクは闇(やみ)のネットナビで\nあるシェ―ドマンを追って、");
const u8 String_0BFE[] = _("ウラインタ―ネットのワ―プホ\n―ルに飛び込んだんだ。");
const u8 String_0BFF[] = _("でも、その先がこの世紀末世界\nだったなんて・・・");
const u8 String_0C00[] = _("<NAME>くん、\nシェ―ドマンを探すのを手伝っ\nてくれないかな?");
const u8 String_0C01[] = _("シェ―ドマンを追えば元の世界\nに、熱斗くんのところに帰る方\n法もわかるはずなんだ」");
const u8 String_0C02[] = _("<PROC=0>\n<END>");
const u8 String_0C03[] = _("<LABEL=ROCKMAN>ロックマン</LABEL>\n「ありがとう、\n<NAME>くん!!");
const u8 String_0C04[] = _("シェ―ドマンの持つ闇の力、\nダ―クソウル・・・");
