const u8 String_0C06[] = _("まずは北の塔に向かおう!」");
const u8 String_0C07[] = _("<PROC=0>\n<END>");
const u8 String_0C08[] = _("<LABEL=SHADEMAN>???</LABEL>\n「キキキ・・・");
const u8 String_0C09[] = _("早くもワタシの存在に気づくと\nは・・・");
const u8 String_0C0A[] = _("さすがだな、\n太陽少年<NAME>・・・」");
const u8 String_0C0B[] = _("<LABEL=ROCKMAN>ロックマン</LABEL>\n「シェ―ドマン!!」");
const u8 String_0C0C[] = _("<LABEL=SHADEMAN>シェ―ドマン</LABEL>\n「おやおや、\n誰(だれ)かと思えば・・・");
const u8 String_0C0D[] = _("こんなところにまで追いかけて\nくるとはね。");
const u8 String_0C0E[] = _("かつてはキミたちに敗れたワタ\nシだが、");
