const u8 String_0C10[] = _("そうすれば・・・\nキキキキ!」");
const u8 String_0C11[] = _("<LABEL=ROCKMAN>ロックマン</LABEL>\n「そんなことはさせない!!」");
const u8 String_0C12[] = _("<LABEL=SHADEMAN>シェ―ドマン</LABEL>\n「キキッ!\n相変わらずだね。");
const u8 String_0C13[] = _("ではキミのそのがんばりに敬意\nを表して、ヒントをプレゼント\nしよう。");
const u8 String_0C14[] = _("この扉(とびら)を開けるための\nカギ、");
const u8 String_0C15[] = _("それはワタシの部下・・・\n4体のシェ―ドバットだ。");
const u8 String_0C16[] = _("彼(かれ)らはこのサン・ミゲル\nの四方で、ワタシのために闇の\n力を集めてくれている。");
const u8 String_0C17[] = _("果たして彼らを見つけ出すこと\nができるかな?\nキキキ・・・」");
const u8 String_0C18[] = _("<PROC=0>\n<END>");
const u8 String_0C19[] = _("<LABEL=ROCKMAN>ロックマン</LABEL>\n「<NAME>くん!!");
const u8 String_0C1A[] = _("急いで4体のシェ―ドバットを\n探そう!");
const u8 String_0C1B[] = _("でも、この街の四方って、\nいったいどこなんだろう?\n心当たり・・・ある?」");
const u8 String_0C1C[] = _("<PROC=0>\n<END>");
const u8 String_0C1D[] = _("<LABEL=ROCKMAN>ロックマン</LABEL>\n「これで塔を上ることができる\nね。でも・・・");
