const u8 String_0C7A[] = _("<NAME>くん・・・\n・・・だったよね?\nぼくはマルチェロ。");
const u8 String_0C7B[] = _("街がアンデッドに襲(おそ)われ\nたあの日、1人逃(に)げ遅(おく\n)れてしまってね・・・」");
const u8 String_0C7C[] = _("<PROC=0>\n<END>");
const u8 String_0C7D[] = _("<LABEL=PEOPLE1>マルチェロ</LABEL>\n「なるほど・・・");
const u8 String_0C7E[] = _("それじゃあ、ぼくも太陽街に行\nってみるよ。");
const u8 String_0C7F[] = _("今現れた、このワ―プ魔方陣(\nまほうじん)を使えば、ダンジ\nョンの入口まで行けそうだしね");
const u8 String_0C80[] = _("それじゃあ、<NAME>くんも\n気をつけなよ!」");
const u8 String_0C81[] = _("<PROC=0>\n<END>");
const u8 String_0C82[] = _("<LABEL=PEOPLE3>老人</LABEL>\n「おぬしは・・・?");
const u8 String_0C83[] = _("・・・わしはルイス。");
const u8 String_0C84[] = _("アンデッドに追われて、こんな\nところに入り込んでしまっての");
const u8 String_0C85[] = _("わしの命もこれまでかとあきら\nめておったんじゃが・・・」");
const u8 String_0C86[] = _("<PROC=0>\n<END>");
const u8 String_0C87[] = _("<LABEL=PEOPLE3>ルイス</LABEL>\n「ふむ・・・");
const u8 String_0C88[] = _("ではわしも、みなのところに行\nこうかの。");
const u8 String_0C89[] = _("今現れた、このワ―プ魔方陣(\nまほうじん)を使えば、ダンジ\nョンの入口まで行けそうじゃ。");
