const u8 String_0C90[] = _("<LABEL=PEOPLE2>???</LABEL>\n「ふうむ・・・");
const u8 String_0C91[] = _("闇の一族と戦う太陽少年か\n・・・");
const u8 String_0C92[] = _("俺(おれ)の名前は・・・");
const u8 String_0C93[] = _("・・・ダメだ。\nやはり、何も思い出せん。");
const u8 String_0C94[] = _("どうやら俺は、記憶(きおく)を\n失っているらしい。");
const u8 String_0C95[] = _("そもそもなぜこんな壁(かべ)に\n囲まれた、出入り口のない部屋\nにいたのか?");
