const u8 String_0C97[] = _("<PROC=0>\n<END>");
const u8 String_0C98[] = _("<LABEL=PEOPLE2>???</LABEL>\n「そうだな・・・");
const u8 String_0C99[] = _("こんなところで悩(なや)んでい\nても仕方がない。おまえの言う\n太陽街にでも行ってみよう。");
const u8 String_0C9A[] = _("なあに、心配はいらんさ。\n腕(うで)には自信がある。");
const u8 String_0C9B[] = _("何の腕なのかは・・・\n俺にも分からんがな。");
const u8 String_0C9C[] = _("おまえも気をつけろよ、\n太陽少年!!」");
const u8 String_0C9D[] = _("<PROC=0>\n<END>");
const u8 String_0C9E[] = _("<LABEL=NONE>???</LABEL>\n「キミは・・・!?」");
const u8 String_0C9F[] = _("<PROC=0>\n<END>");
const u8 String_0CA0[] = _("<LABEL=NONE>幽霊少年</LABEL>\n「こんな時空のひずみの中で、\nよく迷子にならなかったね。");
