const u8 String_0CC9[] = _("<PROC=0>\n<END>");
const u8 String_0CCA[] = _("<LABEL=NONE>父親の幽霊</LABEL>\n「<NAME>さん、\n本当にありがとうございました");
const u8 String_0CCB[] = _("危うく悪霊の仲間入りをすると\nころでした。こうして再び息子\nに会えるとは・・・");
const u8 String_0CCC[] = _("ですが、あんなことになったの\nも、すべては私のせい・・・");
const u8 String_0CCD[] = _("生前の私が行ったことを考えれ\nば、当然の報いなのです」");
const u8 String_0CCE[] = _("<PROC=0>\n<END>");
const u8 String_0CCF[] = _("<LABEL=NONE>幽霊少年</LABEL>\n「でもそれはボクを助けるため\nに・・・");
const u8 String_0CD0[] = _("それにあの病気が広がれば、\nもっとたくさんの人たちが苦し\nむことになったんだ。");
const u8 String_0CD1[] = _("パパだけが悪いわけじゃないよ\n・・・」");
const u8 String_0CD2[] = _("<PROC=0>\n<END>");
const u8 String_0CD3[] = _("<LABEL=NONE>父親の幽霊</LABEL>\n「それでも、");
const u8 String_0CD4[] = _("誰(だれ)かを助けるために、\n他の誰かを犠牲(ぎせい)にする\nなど、許されることではない。");
const u8 String_0CD5[] = _("その上おまえの命も、結局は助\nけられなかったのだから・・・");
const u8 String_0CD6[] = _("私は死の国へ行き、女王の裁き\nを受ける。");
